INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_velk_shop', 'Velk''s Pre-Owned Furnishings', 'The shop is improbably full — every surface covered, every corner claimed. Chairs stacked on tables, lamps draped with fabric samples, shelves bowing under the weight of picture frames, drawer units, and objects with no obvious purpose but clear previous lives. It smells like oil soap and old wood. Somehow, it all feels livable.', 'safe', 0, 0, 1, '["Something in a pile shifts and settles with a creak.","A lamp flickers, steadies, then flickers again.","A drawer slides open an inch on its own. The shop is just settling, probably.","The scent of lemon oil drifts through the crowded aisles.","A price tag twirls slowly on a hanging lamp."]'::jsonb, '{"out":"zone_velk_exterior","down":"zone_velk_basement"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782918446', 'map_int_velk', 'zone_velk_exterior', 0, 0, 0, NULL, NULL, '#e08a4a', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_clone_facility_bathroom', 'Coldwater Clone Facility - Bathroom', 'A sterile, brightly lit washroom lined with smooth composite walls and seamless flooring. The air smells faintly of antiseptic and ozone, while quiet ventilation hums overhead. Hairline drainage channels and spotless surfaces give the unsettling impression that every trace of biological material is meant to disappear without a trace.', 'safe', 0, 0, 1, '[]'::jsonb, '{"west":"zone_start"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null}'::jsonb, NULL, '1782354298', 'map_int_1782352518150', NULL, 1, 0, 0, NULL, NULL, '#4bb36a', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_unit_503', 'Unit 503', 'Unit 503 on the fifth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]'::jsonb, '{"north":"zone_meridian_floor_5"}'::jsonb, '{"is_interior":true,"is_apartment":true}'::jsonb, NULL, '1782898110', 'map_int_meridian', 'zone_meridian_floor_5', 0, 1, 5, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
