INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_floor_2', 'The Meridian — Floor 2 Hallway', 'Floor 2 of The Meridian. A narrow corridor stretches between four unit doors — numbers 201, 202, 203, 204 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_meridian_floor_3","down":"zone_meridian_floor_1","east":"zone_meridian_unit_202","west":"zone_meridian_unit_204","north":"zone_meridian_unit_201","south":"zone_meridian_unit_203"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783112116', 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 2, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
