INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_pigeon_bar', 'The Dead Pigeon', 'A long, low bar named for the taxidermied pigeon nailed over the register, wings spread in permanent, moth-eaten glory. The counter is a slab of reclaimed door on oil drums; the stools don''t match and neither do the glasses. String lights and the blue flicker of a muted screen do all the lighting the place can afford. It smells of spilled synth-beer, cigarettes, and the particular warmth of a room where nobody is going to ask what you did today.', 'safe', 0, 0, 1, '["The taxidermied pigeon sheds a single feather onto the register.","Someone racks up a game in the corner; balls scatter with a crack.","The muted screen cuts to a test pattern and nobody notices.","A stool scrapes as a regular finds the exact spot they always sit."]'::jsonb, '{"out":"zone_mq_marquee","down":"zone_mq_pigeon_back"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"The Dead Pigeon","building_type":"bar","world_exit_zone":"zone_mq_marquee"}'::jsonb, NULL, '1782964407', 'map_int_mq_pigeon', 'zone_mq_marquee', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
