INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_velk_basement', 'Velk''s — Utility Room', 'A low-ceilinged basement room that smells of damp concrete and old cabling. A junction box occupies most of one wall, its panel door held shut with a twist of wire. Exposed conduit runs along the ceiling toward the shop above. A single bulb dangles from a cord, doing its best.', 'safe', 0, 0, 1, '[]'::jsonb, '{"up":"zone_velk_shop","down":"zone_util_zone_velk_basement"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782918447', 'map_int_velk', 'zone_velk_exterior', 0, 0, -1, NULL, NULL, '#e08a4a', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
