INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_start', 'Coldwater Clone Facility', 'Aseptic white tile floor that has long since gone grey at the grout lines. Vat chambers run along both walls — human-sized cylinders of cloudy fluid, most occupied, all humming at a frequency just below the threshold of comfort. Overhead fluorescents pulse with slow, clinical regularity. Somewhere in the walls, a machine breathes. This is where you come from. Every time.', 'safe', 0, 0, 1, '["A vat releases a slow bubble. Something shifts inside.","The reconstitution system cycles — a low harmonic you feel more than hear.","A printer somewhere spits out a receipt. Nobody comes to collect it."]'::jsonb, '{"out":"zone_city_west","down":"zone_clone_facility_z-1_1782276270002","east":"zone_clone_facility_bathroom"}'::jsonb, '{"is_building":true,"is_interior":true,"is_apartment":false,"building_name":"Coldwater Clone Facility","building_type":null,"world_exit_zone":"zone_city_west","scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1782495256', 'map_int_1782352518150', NULL, 0, 0, 0, NULL, NULL, '#4bb36a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
