INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_badland_w_gate', 'The Rust Quarter West', 'The processing yards peter out here into a maze of collapsed sheds and rusted-shut gantries. Everything worth stripping was stripped generations ago; what remains is too big or too broken to carry. The quiet has the particular weight of a place people simply stopped coming to.', 'low', 1, 0, 0, '["The ruins groan somewhere behind you. Structural settling, probably.","A long-dead cable sways and taps against a gantry.","Grit hisses across the cracked concrete and pools in the old wheel-ruts."]'::jsonb, '{"east":"zone_outskirts","west":"zone_ruins"}'::jsonb, '{"lawless":true,"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -3, 0, 0, 'QW', '#eeeeee', '#6d7c9e', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cherry_office', 'The Cherry Pit — Back Office', 'The office where the Cherry''s money is counted and its problems are solved. A metal desk, a safe bolted through the floor, and a wall of monitors cycling grainy feeds of every corner of the club. A cot in the corner says the manager either lives here or has nowhere better to hide. The air is stale with old smoke and the ozone tang of overworked electronics.', 'low', 0, 0, 0, '["A monitor rolls to static, then snaps back to the floor.","The bolted safe ticks as it cools, or as something inside settles.","Somewhere a phone rings twice and is silenced mid-tone."]'::jsonb, '{"up":"zone_mq_cherry_floor","north":"zone_mq_cherry_util"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1783020039', 'map_int_mq_cherry', 'zone_mq_cherry_floor', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_pigeon_back', 'The Dead Pigeon — Back Booth', 'A curtained booth down a short flight of steps, where the deals that keep the Dead Pigeon solvent actually happen. One table, four chairs, a lamp with a scarf thrown over it for mood or for darkness, depending on your business. The walls are soft with old soundproofing foam, so whatever is said here stays a rumor at most.', 'low', 0, 0, 0, '["Muffled bass thuds down through the ceiling from the bar above.","The scarf over the lamp smells faintly of scorching.","A chair creaks under someone who isn''t there anymore."]'::jsonb, '{"up":"zone_mq_pigeon_bar","north":"zone_mq_pigeon_util"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782964407', 'map_int_mq_pigeon', 'zone_mq_pigeon_bar', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cherry_vip', 'The Cherry Pit — VIP', 'A curtained-off nook the club calls VIP with a straight face. A curved couch, a low table ringed with the ghosts of glasses, and a rope that only pretends to be velvet. The privacy is real enough if you''ve paid for it, and the stains suggest a great many people have. A camera dome in the corner watches the room, which rather defeats the point.', 'low', 0, 0, 0, '["The camera dome tracks you with a soft, deliberate whir.","The privacy curtain sways though there''s no draft.","Muffled club noise presses against the little room like water."]'::jsonb, '{"south":"zone_mq_cherry_floor"}'::jsonb, '{"mis_ok":true,"is_interior":true}'::jsonb, NULL, '1783020038', 'map_int_mq_cherry', 'zone_mq_cherry_floor', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_unit_302', 'Unit 302', 'Unit 302 on the third floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]'::jsonb, '{"west":"zone_meridian_floor_3"}'::jsonb, '{"is_interior":true,"is_apartment":true}'::jsonb, NULL, '1782898110', 'map_int_meridian', 'zone_meridian_floor_3', 1, 0, 3, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_precinct', 'Muster Yard', 'A hard-standing of cracked concrete and painted lines nobody parks between anymore. Floodlights — real, working ones — wash the whole yard in interrogation white, so there is nowhere to stand that isn''t seen. Precinct 9 fronts the yard behind a caged sally-port, its charter placard swapped so many times the old bolt holes have merged into one long scar. A departmental drone idles on its pad, optics tracking anything that moves too fast.', 'safe', 0, 0, 1, '[]'::jsonb, '{"in":"zone_mq_precinct_lobby","east":"zone_yard_loadout","west":"zone_mq_battery","south":"zone_mq_cage"}'::jsonb, '{"artery":["Grand Avenue"],"is_building":true,"is_interior":false,"is_apartment":false,"building_name":"Precinct 9","building_type":"police","world_exit_zone":"zone_mq_battery","scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 5, 0, 0, 'P9', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_city_west', 'Franchise Strip', 'Pre-Handoff retail storefronts, repurposed and argued over for years. Big box skeletons and drive-through lanes now used as livestock pens, retrofitted for survival.', 'safe', 0, 0, 1, '["A vendor shouts: \"AUTHENTIC PRE-HANDOFF CANNED GOODS. ONLY SLIGHTLY EXPIRED.\"","Two people argue about whether the Architect controls the weather."]'::jsonb, '{"in":["zone_start","zone_residential_lobby"],"east":"zone_threshold","west":"zone_outskirts","north":"zone_city_east"}'::jsonb, '{"artery":["Grand Avenue"],"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -1, 0, 0, 'FS', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_under_commons', 'The Under — Commons Stair', 'A grimy stairwell bottoms out into a low concrete tunnel, tiled long ago and now furred with damp. Cold air moves from the north. A stair climbs back up to the Commons.', 'low', 0, 0, 0, '[]'::jsonb, '{"up":"zone_civ_commons","north":"zone_under_deep"}'::jsonb, '{"lawless":true}'::jsonb, NULL, '1783137464', 'map_world', NULL, -3, -3, -1, NULL, NULL, NULL, 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_container', 'Container Row', 'Stacked containers march away in canyons four high, their doors chalked with destinations and their contents a matter of faith. The wind between the stacks never stops.', 'low', 0, 0, 1, '["A container door bangs somewhere in the canyon and echoes and echoes.","Wind funnels between the stacks with a moan you feel in your sternum."]'::jsonb, '{"east":"zone_yard_freightworks","west":"zone_corp_boardroom","north":"zone_waste_oxide","south":"zone_yard_sidings"}'::jsonb, '{"artery":["Quay Road","Boxcar Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 6, -3, 0, 'Cn', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_chassis', 'Chassis Row', 'A row of stripped truck chassis up on blocks, cannibalised for parts one bolt at a time. Grease-black mechanics work under them, visible only as boots and the occasional curse.', 'low', 0, 0, 1, '["A wrench clatters under a chassis, followed by a considered obscenity.","A mechanic rolls out from under a truck, looks at you, and rolls back."]'::jsonb, '{"north":"zone_yard_loadout","south":"zone_yard_bonded"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 6, 1, 0, 'Ch', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_furniture_store', 'Dead Space Interiors', 'A decommissioned industrial unit repurposed as a furniture showroom. Exposed concrete, neon tube lighting that flickers on a deliberate schedule. The pieces are arranged in vignettes separated by strips of blue painter''s tape on the floor. Price tags are handwritten on recycled cardboard. The air smells of outgassing polymer and burnt coffee from a percolator no one will admit to owning.', 'safe', 0, 0, 0, '[]'::jsonb, '{"out":"zone_thresholdeast","north":"zone_furniture_util"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1782933540', 'map_int_furniture', 'zone_thresholdeast', 0, 0, 0, NULL, NULL, '#e08a4a', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_sump_cellar', 'Sump — Cellar', 'A brick cellar that predates everything above it, stacked with kegs, crates, and the accumulated evidence of a bar that never throws anything away. A bare bulb on a cord. Damp that has soaked so deep into the mortar the walls sweat. The drain from upstairs terminates somewhere down here, and you''d rather not learn exactly where.', 'low', 0, 0, 0, '["The bare bulb sways on its cord, though nothing touched it.","A keg settles in the stack with a hollow, ringing knock.","Water drips somewhere in the dark with metronomic patience."]'::jsonb, '{"up":"zone_mq_sump_bar","north":"zone_mq_sump_util"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782964407', 'map_int_mq_sump', 'zone_mq_sump_bar', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_grocery', 'Ration Nine', 'A grocery in the loosest post-Collapse sense: three aisles of dented cans, vac-packed protein bricks, and produce grown under lamps somewhere and trucked in still faintly warm. RATION NINE, the sign says, though there is no Ration One through Eight that anyone can name. Fluorescent tubes hum over shelves stocked with the grim staples of survival and, incongruously, a rack of gum by the register. A camera and a clerk track your hands with equal suspicion.', 'safe', 0, 0, 1, '["A fluorescent tube stutters over aisle two and gives up.","The cooler compressor kicks on with a shudder that rattles the cans.","A can rolls off a shelf somewhere and wobbles to a stop.","The register beeps, unprompted, and the clerk swears at it."]'::jsonb, '{"out":"zone_mq_battery","north":"zone_mq_grocery_stock"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"Ration Nine","building_type":"grocery","world_exit_zone":"zone_mq_battery"}'::jsonb, NULL, '1782964407', 'map_int_mq_grocery', 'zone_mq_battery', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_unit_403', 'Unit 403', 'Unit 403 on the fourth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]'::jsonb, '{"north":"zone_meridian_floor_4"}'::jsonb, '{"is_interior":true,"is_apartment":true}'::jsonb, NULL, '1782898110', 'map_int_meridian', 'zone_meridian_floor_4', 0, 1, 4, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_tunnels', 'The Under', 'Pre-Handoff subway tunnels, now home to the Archivists. Emergency lighting casts everything amber. The walls are dense with salvaged text — newspaper fragments, printed articles, handwritten notes.', 'medium', 0, 0, 1, '["Someone is typing, fast, somewhere in the dark.","A train horn sounds in the distance. There are no trains.","Scratched into the wall, half-legible: \"when the static’s bad, ask the shadows.\""]'::jsonb, '{"up":"zone_slums"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783169469', 'map_world', NULL, 0, 2, -1, NULL, '#111111', '#cf6a2e', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_forklift', 'Forklift Flat', 'A concrete apron where the yard''s forklifts are parked, charged, and fought over each shift. Tyre-black scuffs map a hundred near-misses across the slab.', 'low', 0, 0, 1, '["A forklift alarm beeps its slow reverse into the flat and cuts out.","Two drivers argue over a charging cable with real, tired heat."]'::jsonb, '{"north":"zone_yard_weighbridge","south":"zone_yard_railhead"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 8, 1, 0, 'FK', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_city_sw', 'The Under Entrance', 'A guarded stairwell down into the old subway tunnels. The Archivists'' real vault is below, but this entrance is calm, watched, safe.', 'safe', 0, 0, 1, '["A train horn sounds in the distance. There are no trains.","Cold air rises from the stairwell, smelling of paper and rust."]'::jsonb, '{"east":"zone_city_south"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -1, 1, 0, 'UE', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_corp_investor', 'Investor''s Walk', 'A colonnade where freight futures are traded on the strength of ships that may or may not exist. Fortunes are made and unmade here on cargo that is still, technically, at sea.', 'safe', 0, 0, 1, '["Someone on the Walk sells a shipment they''ve never seen to someone who never will.","A futures board flickers, and three people on the Walk quietly stop smiling."]'::jsonb, '{"west":"zone_up_chrome","north":"zone_corp_boardroom","south":"zone_yard_depot"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 5, -2, 0, 'Iv', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_city_se', 'The Clinic Block', 'One of the only reliably staffed medical points in the basin. People are polite here. Nobody wants to be the reason it closes.', 'safe', 0, 0, 1, '["A line forms outside, orderly, almost eerily so.","Someone hums a tune that might be older than the Handoff."]'::jsonb, '{"north":"zone_thresholdeast"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, NULL, '1783301927', 'map_world', NULL, 1, 1, 0, 'CB', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_precinct_lobby', 'Precinct 9 — Lobby', 'A bulletproof-glass lobby that manages to feel both fortified and abandoned. A duty officer sits behind the glass beneath a corporate charter seal and a laminated list of fees for services that used to be free. Bolted plastic chairs face a wall-screen scrolling WANTED faces and civic reminders. The floor is the specific institutional grey of a place designed to wear you down before you ever reach a desk. It is, however, warm, and no one gets murdered in here, which counts.', 'safe', 0, 0, 1, '["The duty officer''s terminal chimes and is ignored.","A WANTED face scrolls up the wall-screen, lingers, scrolls on.","The door buzzer sounds; the mag-lock clunks; no one comes in.","Somewhere past the glass, a phone rings in the empty bureaucratic dark."]'::jsonb, '{"out":"zone_mq_precinct","down":"zone_mq_precinct_holding","north":"zone_mq_precinct_bullpen"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"Precinct 9","building_type":"police","world_exit_zone":"zone_mq_precinct"}'::jsonb, NULL, '1782964407', 'map_int_mq_precinct', 'zone_mq_precinct', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cage_shop', 'The Cage', 'Inside, the store is exactly as advertised: aisles of hard goods behind floor-to-ceiling steel mesh, and the clerk sealed in a welded cage at the center like the last honest man in a bad neighborhood, which he may be. You point, he retrieves, money goes through the slot. The stock is a magpie''s hoard — batteries, blades, bandages, bad liquor, worse cigarettes — everything a person needs to get through one more week and nothing they''d want to be caught enjoying.', 'safe', 0, 0, 1, '["The clerk racks the shotgun''s action once, for no reason, for every reason.","A battery display buzzes behind the mesh, testing itself.","The vending machine out front thunks and dispenses to no one.","Steel mesh sings faintly as the cooler fan pushes air through it."]'::jsonb, '{"out":"zone_mq_cage","north":"zone_mq_cage_util"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"The Cage","building_type":"shop","world_exit_zone":"zone_mq_cage"}'::jsonb, NULL, '1782964407', 'map_int_mq_cage', 'zone_mq_cage', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_precinct_holding', 'Precinct 9 — Holding', 'Two cages of painted bar-steel in a concrete basement, a drain in the floor, and a bench bolted to each wall for the overnight guests. The paint on the bars is chipped down to raw metal exactly at hand height, all the way around, by every pair of hands that ever gripped them waiting to be processed or forgotten. It smells of disinfectant losing a war against everything else.', 'low', 0, 0, 0, '["A cage door, unlatched, swings a slow inch on its hinge and stops.","The floor drain exhales a cold, sour breath.","Bootsteps cross the ceiling overhead and recede.","The overnight fluorescent buzzes at a pitch engineered to prevent sleep."]'::jsonb, '{"up":"zone_mq_precinct_lobby"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782964408', 'map_int_mq_precinct', 'zone_mq_precinct_lobby', 0, 0, -1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_tare', 'Tare Row', 'Where empty containers are weighed and stacked, their tare marked in chalk on the steel. The stacks climb four high and lean in ways that keep the insurers awake.', 'low', 0, 0, 1, '["A container stack settles with a boom that you feel in your teeth.","Chalk figures on a container smear in the damp, no longer adding up."]'::jsonb, '{"north":"zone_yard_transfer","south":"zone_yard_interchange"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 7, 2, 0, 'Ta', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_warehouse', 'The Loading Bay West', 'A vast warehouse complex that The Franchise faction uses as a distribution hub. Everything here has a SKU. Everything here is for sale.', 'low', 0, 0, 1, '["\"CUSTOMER SATISFACTION IS OUR PRIORITY\" plays from overhead speakers. The voice sounds increasingly uncertain."]'::jsonb, '{"west":"zone_civ_sortation","north":"zone_up_aid"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -2, -1, 0, 'LW', '#eeeeee', '#42c96a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_warrens', 'The Warrens', 'Where the Sprawl''s foundations rot into a warren of lean-tos and tarp-roofed stalls. Everything here is for sale, and most of it is stolen off someone still warm.', 'medium', 1, 0, 1, '["A hawker rattles a tin of unlabelled pills at you and melts back into the tarps.","Two figures argue over a mattress in a doorway, then over a knife."]'::jsonb, '{"west":"zone_deep_tarpit","south":"zone_deep_rotrow"}'::jsonb, '{"lawless":true,"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, -2, 2, 0, 'WR', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_under_deep', 'The Under — Deep Passage', 'The passage runs dead straight beneath the city, service conduits bundled overhead ticking with unseen current. Your footsteps come back flat off the walls.', 'low', 0, 0, 0, '[]'::jsonb, '{"north":"zone_under_landing","south":"zone_under_commons"}'::jsonb, '{"lawless":true}'::jsonb, NULL, '1783137464', 'map_world', NULL, -3, -4, -1, NULL, NULL, NULL, 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_weapons_exterior', 'Rebar Cut', 'A shipping container grafted onto the alley wall, its roll-door cut down to a service hatch and barred with rebar. A stencilled sign — a rifle crossed with a wrench — hangs over the entrance. Somebody has scratched PRICES ARE FIRM into the paint, then, beneath it, SO AM I.', 'low', 0, 0, 1, '[]'::jsonb, '{"east":"zone_meat_ashpit","west":"zone_deep_gutter","north":"zone_mq_ember"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":"zone_deep_waste","scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 3, 2, 0, 'QS', '#111111', '#edbd99', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_bonded', 'The Bonded Store', 'A caged bonded warehouse for goods that are in the country but not yet, legally, anywhere. The padlocks are new; the paperwork authorising them is not.', 'low', 0, 0, 1, '["A guard rattles the bonded cage, confirms the locks, and moves on.","Something inside the bonded store is ticking. Nobody has volunteered to check."]'::jsonb, '{"north":"zone_yard_chassis","south":"zone_yard_skid"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 6, 2, 0, 'BD', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_amp_shop', 'Ampersand Electronics', 'A stall built into the overpass footing, every inch of it strung with salvaged tech: coils of cable, cracked slates, drones with their guts hanging out, and a wall of chargers for devices no one makes anymore. The proprietor works at a bench under a magnifier lamp, soldering iron never quite set down. Everything is priced by argument. A hand-lettered sign warns NO REFUNDS, NO EXCEPTIONS, NO EXORCISMS, the last apparently learned the hard way.', 'safe', 0, 0, 1, '["The soldering iron hisses as it meets flux; a thread of smoke curls up.","A salvaged drone on the shelf twitches one rotor and goes still.","Something on the tech wall emits a single mournful boot-chime.","A charger indicator blinks green, red, green, deciding nothing."]'::jsonb, '{"out":"zone_mq_overpass","north":"zone_mq_amp_util"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"Ampersand Electronics","building_type":"shop","world_exit_zone":"zone_mq_overpass"}'::jsonb, NULL, '1782964407', 'map_int_mq_amp', 'zone_mq_overpass', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_unit_401', 'Unit 401', 'Unit 401 on the fourth floor of The Meridian. A compact studio: four concrete walls, a drop ceiling with a suspect water stain developing in one corner, bare cable hookups where a previous tenant''s life used to plug in. A single window faces the interior airshaft — the view is another wall, close enough to touch if you lean out. Old picture hooks mark where someone made this home once. The bones are all here. Whether it qualifies as livable depends entirely on what you''re used to.', 'safe', 0, 0, 0, '[]'::jsonb, '{"south":"zone_meridian_floor_4"}'::jsonb, '{"is_interior":true,"is_apartment":true}'::jsonb, NULL, '1782898110', 'map_int_meridian', 'zone_meridian_floor_4', 0, -1, 4, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
