INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_202', 'Unit 202', 'A studio that still has its original built-in cabinetry, half the doors missing, the rest painted shut. A mattress on a pallet, a chair, a view of the square if you press your face to the glass. Home.', 'safe', 0, 0, 1, '["Pipes knock somewhere in the walls. The building is old but it holds."]'::jsonb, '{"west":"zone_mq_chrome_f2"}'::jsonb, '{"is_apartment":true}'::jsonb, NULL, '1782964409', 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 1, 0, 2, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_204', 'Unit 204', 'A corner unit, which here means two windows instead of one and a draft to match. A bed, a footlocker, a sink that runs brown for a ten-count before it clears. The door is steel. The door is the point.', 'safe', 0, 0, 1, '["Pipes knock somewhere in the walls. The building is old but it holds."]'::jsonb, '{"east":"zone_mq_chrome_f2"}'::jsonb, '{"is_apartment":true}'::jsonb, NULL, '1782964409', 'map_int_mq_chrome', 'zone_mq_chrome_lobby', -1, 0, 2, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_skid', 'Skid Row', 'A lane of skids and dunnage where the truly unwanted freight ends up — water-damaged, mislabelled, or simply forgotten until it becomes salvage by default.', 'low', 0, 0, 1, '["A skid of ruined cargo sags in the wet and gives up another inch.","A picker works down Skid Row, tapping crates, listening for anything worth the crowbar."]'::jsonb, '{"east":"zone_yard_interchange","west":"zone_meat_carrion","north":"zone_yard_bonded"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 6, 3, 0, 'Sk', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_residential_lobby', 'Embassy Hotel & Bar — Lobby', 'A converted hotel lobby, marble floors gone dull under a permanent film of dust, repurposed into the basin''s closest thing to real estate. A corkboard by the door — bolted over what used to be the concierge desk — is covered in handwritten unit listings, half of them crossed out. Along one wall, a bar still operates under a brass sign reading THE EMBASSY LOUNGE — a half-dozen cracked vinyl stools lined up at the counter, free to sit if you don''t mind the wobble. Lowry stands behind it, polishing a glass that was already clean. The building still has working locks upstairs, which around here makes it valuable.', 'safe', 0, 0, 1, '["Someone argues with the building''s old intercom system, which only ever says \"PLEASE HOLD.\"","A hand-written sign reads: UNITS AVAILABLE. ASK ABOUT OUR LOCKS."]'::jsonb, '{"up":"zone_embassy_floor2","out":"zone_city_west","down":"zone_residential_lobby_z-1_1782105292491","east":"zone_apt_3","west":"zone_apt_4","north":"zone_apt_1","south":"zone_apt_2"}'::jsonb, '{"is_building":true,"is_interior":true,"is_apartment":false,"building_name":"Embassy Hotel & Bar","building_type":"hotel","world_exit_zone":"zone_city_west"}'::jsonb, NULL, '1782356877', 'map_interior_zone_residential_lobby', NULL, 0, 0, 0, 'FS', NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_sump_bar', 'Sump', 'The kind of bar that doesn''t need a name over the door because if you''re here, you already knew where you were going. SUMP is scratched into the paint anyway. It is one narrow room, a plank bar, and a floor that slopes toward a literal drain in the center — hence the name, and hence the smell. The regulars are fixtures, welded to their stools by decades of gravity and grievance. Drinks are cheap, strong, and served without conversation.', 'safe', 0, 0, 1, '["Something unspeakable gurgles down the floor drain and is not discussed.","A regular knocks the bar twice; the bartender pours without looking.","The single TV shows horse racing from a track that no longer exists.","A fly, impossibly, in this cold, orbits the room in slow figure-eights."]'::jsonb, '{"out":"zone_mq_ember","down":"zone_mq_sump_cellar"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"Sump","building_type":"bar","world_exit_zone":"zone_mq_ember"}'::jsonb, NULL, '1782964407', 'map_int_mq_sump', 'zone_mq_ember', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_furniture_util', 'Dead Space Interiors — Utility Room', 'The showroom''s backroom: plastic-shrouded sofas stacked to the ceiling, a graveyard of flat-pack and packing foam. Wedged between two wardrobes, the building''s junction box hums, warm to the touch, its cabinet door held shut with a bungee cord. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]'::jsonb, '{"south":"zone_furniture_store"}'::jsonb, '{"is_building":false,"is_interior":true}'::jsonb, NULL, '1783023537', 'map_int_furniture', 'zone_furniture_store', 0, -1, 0, NULL, NULL, '#e08a4a', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_ext_1782953094650', 'Limelight Lot', 'A fenced service yard behind the broadcast blocks, floodlit at all hours by lights nobody remembers installing. Coax and power run overhead in fat looms, stapled to anything that will hold them, humming faintly in the wet. KSAB-TV''s stage door sits under a dead awning, its ON AIR bulb burned out mid-word so it reads only ON. A satellite dish the size of a paddling pool tilts drunkenly on the roofline, still tracking a bird that stopped answering years ago.', 'safe', 0, 0, 1, '[]'::jsonb, '{"in":"zone_studio_1782953094650","south":"zone_city_north"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 0, -2, 0, 'KS', '#111111', '#efe8a4', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_interchange', 'The Interchange', 'The road-and-rail interchange at the Yards'' back gate, a snarl of level crossings and truck lanes where everything meets and nothing has right of way.', 'low', 0, 0, 1, '["A crossing bell rings for a train that takes four full minutes to not arrive.","A truck and a flatcar reach the interchange at once and simply... negotiate."]'::jsonb, '{"east":"zone_yard_bulk","west":"zone_yard_skid","north":"zone_yard_tare"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 7, 3, 0, 'IX', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meat_ashpit', 'Ashpit', 'A soot-black yard behind the market where the day''s unsold and unsellable meat goes to the fire. The smoke is greasy and the smell gets into everything you own.', 'medium', 1, 0, 1, '["The ashpit fire flares as something wet goes in, and the smoke thickens.","A stray dog is driven off from the ashpit''s edge, and comes straight back."]'::jsonb, '{"east":"zone_meat_slaughter","west":"zone_weapons_exterior","north":"zone_mq_overpass","south":"zone_meat_offal"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 4, 2, 0, 'Ap', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_open', 'The Open Bay', 'The end of the last jetty, where the pilings give out and the grey water of Coldwater Bay just goes on. Something big moves out there, unhurried, patient.', 'low', 0, 0, 1, '["Far out on the bay, a wake rises, crosses, and sinks without a source.","The jetty ends here in splintered wood and open, indifferent water."]'::jsonb, '{"east":"zone_bay_fog","west":"zone_bay_sound","north":"zone_bay_mid","south":"zone_bay_shallows"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 2, -5, 0, 'OB', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_grocery_stock', 'Ration Nine — Stockroom', 'A cramped stockroom walled with wire shelving and stacked pallets, the cold-store humming behind a heavy insulated door. Inventory sheets curl on a clipboard nobody has updated in weeks. It smells of cardboard, cold, and the sweetish edge of something in the back that turned before it sold. A fire exit is chained shut in flagrant violation of several dead safety codes.', 'low', 0, 0, 0, '["The cold-store door seals shut with a sucking thud.","A pallet of cans ticks and shifts under its own weight.","The chained fire exit rattles as wind finds the gap beneath it."]'::jsonb, '{"north":"zone_mq_grocery_util","south":"zone_mq_grocery"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782964407', 'map_int_mq_grocery', 'zone_mq_grocery', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_precinct_util', 'Precinct 9 — Electrical Room', 'A municipal-grey utility room off the bullpen, breaker panel plastered with faded safety notices and one evidence tag nobody ever filed. This box backs the holding cells and the front desk both — a fact stencilled in stern red beside a hacking port sealed below the latch.', 'low', 0, 0, 0, '[]'::jsonb, '{"south":"zone_mq_precinct_bullpen"}'::jsonb, '{"is_building":false,"is_interior":true}'::jsonb, NULL, '1783023541', 'map_int_mq_precinct', 'zone_mq_precinct_bullpen', 0, -2, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_sump_util', 'Sump — Utility Nook', 'A dank corner of the cellar where the floor never dries. A sump pump gurgles somewhere below, and a rust-streaked junction cabinet drips condensation down its breaker faces, sparks of corrosion blooming at every bolt. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]'::jsonb, '{"south":"zone_mq_sump_cellar"}'::jsonb, '{"is_building":false,"is_interior":true}'::jsonb, NULL, '1783023536', 'map_int_mq_sump', 'zone_mq_sump_cellar', 0, -1, -1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cage_util', 'The Cage — Utility Room', 'A steel-walled back room stinking of gun oil and solvent. The junction box hangs behind a padlocked expanded-metal grille, as caged as everything else in this shop, its breakers throwing a faint amber glow across racked ammo tins. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]'::jsonb, '{"south":"zone_mq_cage_shop"}'::jsonb, '{"is_building":false,"is_interior":true}'::jsonb, NULL, '1783023540', 'map_int_mq_cage', 'zone_mq_cage_shop', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_pigeon_util', 'The Dead Pigeon — Utility Closet', 'A cramped closet off the back booth, walls furred with condensation and old beer-line runs. A grey junction cabinet hums between a stack of empty kegs and a mop bucket, breathing warm ozone into the smell of stale hops. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]'::jsonb, '{"south":"zone_mq_pigeon_back"}'::jsonb, '{"is_building":false,"is_interior":true}'::jsonb, NULL, '1783023534', 'map_int_mq_pigeon', 'zone_mq_pigeon_back', 0, -1, -1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cherry_util', 'The Cherry Pit — Utility Room', 'Past a beaded curtain behind the office, a windowless room of dead neon tubes, a cracked mirror-ball, and coils of stage cable. The building''s junction box hums against the far wall, its indicator lights winking through the sticky dark like the club never really closes. A small sealed hacking port sits below its latch.', 'low', 0, 0, 0, '[]'::jsonb, '{"south":"zone_mq_cherry_office"}'::jsonb, '{"is_building":false,"is_interior":true}'::jsonb, NULL, '1783023535', 'map_int_mq_cherry', 'zone_mq_cherry_office', 0, -1, -1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cherry_floor', 'The Cherry Pit', 'A strip club that leans hard on the one gimmick it can afford: a single working spotlight and a stage of scuffed acrylic lit cherry-red from beneath. Vinyl banquettes ring the room in various states of split and repair. The music is a heartbeat of bass you feel in your fillings. Dancers work the pole with the flat professionalism of people counting the minutes, and the bar sells watered drinks at armed-robbery prices. Everyone is watching everyone, and pretending not to.', 'safe', 0, 0, 1, '["The bass drops and the spotlight swings to catch the stage.","A bouncer folds his arms in the doorway and studies you without warmth.","Someone tucks a bill into a garter without making eye contact.","The cherry underlight flickers, tinting the whole room arterial red."]'::jsonb, '{"out":"zone_mq_cathode","down":"zone_mq_cherry_office","north":"zone_mq_cherry_vip"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"The Cherry Pit","building_type":"club","world_exit_zone":"zone_mq_cathode"}'::jsonb, NULL, '1783019924', 'map_int_mq_cherry', 'zone_mq_cathode', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_floor_6', 'The Meridian — Floor 6 Hallway', 'Floor 6 of The Meridian. A narrow corridor stretches between four unit doors — numbers 601, 602, 603, 604 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_meridian_roof","down":"zone_meridian_floor_5","east":"zone_meridian_unit_602","west":"zone_meridian_unit_604","north":"zone_meridian_unit_601","south":"zone_meridian_unit_603"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783112081', 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 6, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_lobby', 'Chrome Court — Lobby', 'The ground-floor lobby of Chrome Court: a bank of tenant mailboxes, most jimmied, and an elevator with a hand-lettered OUT OF ORDER SINCE sign where the date has been scratched out and re-guessed by successive residents. A stairwell climbs into the amber gloom of the upper floors behind a fire door that no longer latches. A resident''s bicycle is chained to the radiator with more security than the front door offers. It is quiet, and locked, and warm, and that is enough.', 'safe', 0, 0, 1, '["The stairwell fire door drifts open an inch and settles.","A mailbox door hangs open, ticking against its frame in the draft.","Somewhere above, a TV murmurs through a floor.","The dead elevator''s call button glows, hopeful and useless."]'::jsonb, '{"up":"zone_mq_chrome_f1","out":"zone_mq_chrome_court","down":"zone_mq_chrome_util"}'::jsonb, '{"is_building":true,"is_interior":true,"building_name":"Chrome Court","building_type":"apartment","world_exit_zone":"zone_mq_chrome_court"}'::jsonb, NULL, '1782964408', 'map_int_mq_chrome', 'zone_mq_chrome_court', 0, 0, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_floor_3', 'The Meridian — Floor 3 Hallway', 'Floor 3 of The Meridian. A narrow corridor stretches between four unit doors — numbers 301, 302, 303, 304 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_meridian_floor_4","down":"zone_meridian_floor_2","east":"zone_meridian_unit_302","west":"zone_meridian_unit_304","north":"zone_meridian_unit_301","south":"zone_meridian_unit_303"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783112361', 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 3, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_apt_8', 'Unit 2D', 'Unit 2D, narrow as a coffin and about as bright. The previous tenant left in a hurry: a chair on its side, a ring of candle stubs on the floor, initials keyed into the doorframe. There''s a real bed, though, and a deadbolt, and the walls are thick enough that the neighbours'' business stays theirs.', 'safe', 0, 0, 0, '["The overturned chair settles with a faint creak."]'::jsonb, '{"east":"zone_embassy_floor2"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":true,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783111686', 'map_interior_zone_residential_lobby', NULL, -1, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_apt_7', 'Unit 2C', 'Number 2C. Someone painted this one, once — a hopeful yellow now gone the colour of a smoker''s teeth, peeling in long tongues off the plaster. A kitchenette with two working burners, a fold-down table, and a bathtub in the main room because the plumbing never reached the back. The window looks onto a brick wall an arm''s length away.', 'safe', 0, 0, 0, '["A tongue of old paint peels a little further from the wall."]'::jsonb, '{"west":"zone_embassy_floor2"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":true,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783111686', 'map_interior_zone_residential_lobby', NULL, 1, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_apt_6', 'Unit 2B', 'Unit 2B, tucked at the back over the alley. It smells of the dumpsters three floors down and whatever the last tenant fried. A single bulb on a string, a closet with its door removed to serve as a shelf, and a radiator that either roars or freezes — never anything between. Cheap, and it shows, but the door bolts from the inside.', 'safe', 0, 0, 0, '["The radiator bangs twice and falls silent."]'::jsonb, '{"north":"zone_embassy_floor2"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":true,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783111686', 'map_interior_zone_residential_lobby', NULL, 0, 1, 1, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_apt_5', 'Unit 2A', 'A corner unit, Number 2A, riding the front of the building. Two windows face the street, one boarded, one still glassed and grimy enough to filter the neon into a permanent bruise-purple. A mattress on a bent steel frame, a hotplate wired straight into the wall, and a water stain on the ceiling shaped uncannily like a hanged man. The lock, at least, is real.', 'safe', 0, 0, 0, '["Neon light through the grimy window pulses, dims, holds."]'::jsonb, '{"south":"zone_embassy_floor2"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":true,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783111686', 'map_interior_zone_residential_lobby', NULL, 0, -1, 1, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_f2', 'Chrome Court — Floor 2', 'The second-floor hallway of Chrome Court, a tunnel of amber emergency light and doors painted so many times the numbers are just suggestions. The carpet is worn to jute down the center where every tenant walks the identical line. Four units open off the hall. A window at the end looks out over the district''s neon, which from up here almost looks like a city that works.', 'safe', 0, 0, 1, '["A door down the hall closes with the finality of a lock turning.","The amber emergency light hums and dims by a shade.","Something is cooking behind one of the doors; the smell almost reaches you.","The end-of-hall window rattles as the wind leans on it."]'::jsonb, '{"up":"zone_mq_chrome_f3","down":"zone_mq_chrome_f1","east":"zone_mq_chrome_202","west":"zone_mq_chrome_204","north":"zone_mq_chrome_201","south":"zone_mq_chrome_203"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782964408', 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, 2, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meat_carrion', 'Carrion Way', 'The far end of the market, where the meat is cheapest and the questions fewest. A dead-end way, which the scavengers and the desperate both find convenient for different reasons.', 'medium', 1, 0, 1, '["Something changes hands fast at the end of Carrion Way, and both parties leave quickly.","A crow the size of a cat works at a scrap in the gutter, unbothered by you."]'::jsonb, '{"east":"zone_yard_skid","west":"zone_meat_offal","north":"zone_meat_slaughter"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 5, 3, 0, 'Cy', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_drum_exterior', 'Bobbin Cut', 'A slim pedestrian cut that somehow keeps its dignity in a city this far gone — swept, even, the puddles smaller here than they have any right to be. Storefront glass runs its length, most of it soaped over, one window still dressed and lit. Drum''s Fits shows two mannequins in loud, layered outfits that dare you to walk past without looking, a neon thread-spool buzzing pink above the door. The rest of the frontage waits for tenants who aren''t coming.', 'low', 0, 0, 1, '[]'::jsonb, '{"in":"zone_drum_shop","north":"zone_velk_exterior"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":"zone_deep_waste","scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 2, 1, 0, 'Cl', '#eeeeee', '#42c96a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_apt_10', 'Unit 3B', 'Number 3B, back corner under the roof. The ceiling slopes where the building''s cornice cuts in, low enough to crack your skull if you sit up wrong in the night. A camp bed, a footlocker, a hole in the plaster patched with a road sign. When it rains, the stain on the landing ceiling isn''t the only one — you''ll hear it here first, tapping the bucket someone thoughtfully left behind.', 'safe', 0, 0, 0, '["A single drip finds the bucket with a flat metallic tap."]'::jsonb, '{"north":"zone_embassy_floor3"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":true,"building_name":null,"building_type":null,"world_exit_zone":null}'::jsonb, NULL, '1783045464', 'map_interior_zone_residential_lobby', 'zone_embassy_floor3', 0, 1, 2, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_apt_9', 'Unit 3A', 'Unit 3A, top floor, street-facing. Best light in the building up here — what little the smog lets through comes in clean and level through a window that actually opens. A proper bed, a desk someone bolted to the wall, and a hook in the ceiling that used to hold a fan and now holds nothing, turning slowly in the draft. Quiet. Expensive-feeling, for the Embassy.', 'safe', 0, 0, 0, '["The empty ceiling hook turns a slow half-circle in the draft."]'::jsonb, '{"south":"zone_embassy_floor3"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":true,"building_name":null,"building_type":null,"world_exit_zone":null}'::jsonb, NULL, '1783045464', 'map_interior_zone_residential_lobby', 'zone_embassy_floor3', 0, -1, 2, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_apt_11', 'Unit 3C', 'Unit 3C. The realtor — the corkboard downstairs, really — calls this one ''cozy.'' It''s small. A single room with a curtained-off toilet, a sink that runs rust for a minute before it runs clear, and a window painted shut and then painted again. But the lock is new, the floor is solid, and nobody up here asks questions.', 'safe', 0, 0, 0, '["Behind the curtain, the sink drips rust-brown, then stops."]'::jsonb, '{"west":"zone_embassy_floor3"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":true,"building_name":null,"building_type":null,"world_exit_zone":null}'::jsonb, NULL, '1783045464', 'map_interior_zone_residential_lobby', 'zone_embassy_floor3', 1, 0, 2, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_precinct_bullpen', 'Precinct 9 — Bullpen', 'A room of mismatched desks shoved together, each buried under case files no one will close and coffee cups fossilizing into archaeology. A corkboard maps the district''s gangs in red string that has long since become its own conspiracy. Half the overhead lights are dead and no one has requisitioned bulbs. The officers who work here have the specific exhaustion of people paid to hold a line that moved years ago.', 'safe', 0, 0, 1, '["A desk phone rings four times and kicks to a full voicemail box.","Red string sags off the corkboard and dangles, tracing nothing.","A dead overhead light ticks as it tries and fails to warm up.","Someone''s coffee has grown a skin; it wrinkles as the AC breathes on it."]'::jsonb, '{"north":"zone_mq_precinct_util","south":"zone_mq_precinct_lobby"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782964407', 'map_int_mq_precinct', 'zone_mq_precinct_lobby', 0, -1, 0, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slag_catalyst', 'Catalyst Row', 'A row of distillation towers, each one cracked open like a spent shell casing. The catalyst beds inside have gone to a fine iridescent grit that hangs in the air and glitters when it catches the light. It is very pretty, and very bad for you.', 'medium', 1, 0, 0, '["The grit in the air fluoresces faintly, painting everything a sick green for a heartbeat.","A tower groans as the wind leans on it, shedding a slow curtain of rust."]'::jsonb, '{"west":"zone_slag_flarestack","north":"zone_waste_fumealley","south":"zone_slag_yard"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -9, -1, 0, 'CR', '#111111', '#e9b282', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slag_sump', 'The Effluent Sump', 'Settling ponds step down the slope, their surfaces skinned over in oily rainbows that don''t move even when the wind does. Whatever the works couldn''t burn, it dumped here. The smell gets into your clothes and stays for days.', 'medium', 1, 0, 0, '["A bubble the size of your head rises through the sludge and pops with a flat, wet cough.","Something breaks the surface of the far pond, then thinks better of it."]'::jsonb, '{"west":"zone_slag_drums","north":"zone_slag_yard","south":"zone_waste_ashencut"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -9, 1, 0, 'ES', '#111111', '#e9b282', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_ashway_ashfall', 'Ashfall Mile', 'The road gives up and the flats take over — a grey plain of settled ash that swallows your bootprints and hands them back to the wind. Somewhere upwind a stack is still venting; the sky here is the colour of an old bruise.', 'low', 1, 0, 0, '["Ash sifts down like dirty snow and coats your lips with the taste of burnt plastic.","The wind drops for a moment, and the silence has a weight to it."]'::jsonb, '{"east":"zone_ashway_road","west":"zone_ashway_wash"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -6, 0, 0, 'AF', '#111111', '#b1bccd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_court', 'Foundry Cut', 'A short cut between two boom-era towers, narrow enough that the wind funnels through hard enough to sting. Brushed-metal cladding sheets the walls, half of it peeled back to the rust beneath. Chrome Court''s entrance stands at the far end — steel letters over the doors, three fallen and re-inked on cardboard — beside a solid brick of painted-over intercoms. The gutter runs with something that was recently oil.', 'safe', 0, 0, 1, '[]'::jsonb, '{"in":"zone_mq_chrome_lobby","east":"zone_yard_depot","north":"zone_up_chrome","south":"zone_mq_battery"}'::jsonb, '{"is_building":true,"is_interior":false,"is_apartment":false,"building_name":"Chrome Court","building_type":"apartment","world_exit_zone":"zone_mq_cathode","scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 4, -1, 0, 'CC', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_f3', 'Chrome Court — Floor 3', 'The third-floor hallway of Chrome Court, a tunnel of amber emergency light and doors painted so many times the numbers are just suggestions. The carpet is worn to jute down the center where every tenant walks the identical line. Four units open off the hall. A window at the end looks out over the district''s neon, which from up here almost looks like a city that works.', 'safe', 0, 0, 1, '["A door down the hall closes with the finality of a lock turning.","The amber emergency light hums and dims by a shade.","Something is cooking behind one of the doors; the smell almost reaches you.","The end-of-hall window rattles as the wind leans on it."]'::jsonb, '{"up":"zone_mq_chrome_roof","down":"zone_mq_chrome_f2","east":"zone_mq_chrome_302","west":"zone_mq_chrome_304","north":"zone_mq_chrome_301","south":"zone_mq_chrome_303"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783111944', 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, 3, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_corp_argent', 'Argent Row', 'A silver-fronted terrace of freight-finance offices overlooking the Yards, where the people who own the cargo watch it move without once touching it. The view is of money becoming more money.', 'safe', 0, 0, 1, '["A ticker crawls silver figures across a frontage, up, always up.","A financier watches a container swing across the yard and mentally spends it twice."]'::jsonb, '{"west":"zone_waste_downwind","north":"zone_nc_chancery","south":"zone_yard_gantry"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 8, -4, 0, 'Ar', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_ashway_wash', 'The Dry Wash', 'A concrete drainage channel cuts across the flats, its floor crazed and stained the rust-black of old runoff. A collapsed checkpoint booth leans over the lip, its boom gate frozen halfway down like it''s still trying to stop you.', 'low', 1, 0, 0, '["Something skitters along the channel floor and is gone before you can place it.","Water you can''t see drips steadily from the culvert mouth, each drop echoing."]'::jsonb, '{"east":"zone_ashway_ashfall","west":"zone_slag_gate"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -7, 0, 0, 'DW', '#111111', '#b1bccd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_sound', 'The Sound', 'A sheltered sound between the wreck and the cold-store pilings, calm enough that the fishing skiffs tie up here. It is the last friendly water before the bay stops pretending.', 'low', 0, 0, 1, '["A moored skiff knocks gently against a piling, over and over.","A fisher hauls a net over the sound''s edge, sees the catch, and swears."]'::jsonb, '{"east":"zone_bay_open","north":"zone_bay_wreck","south":"zone_dock_coldstore"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 1, -5, 0, 'SD', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_ashway_road', 'The Haul Road', 'Six lanes of freight road run west out of Old Coldwater, expansion joints heaved into knee-high ridges by decades of frost. Dead haulers sit nose-to-tail in the breakdown lane, cabs stripped to the frame, waiting on a shift change that never came.', 'low', 1, 0, 0, '["A tanker''s air-brake lets go somewhere down the line with a hiss, though nothing has moved here in years.","Grit pings off the guardrail in a gust, then goes still."]'::jsonb, '{"east":"zone_ruins","west":"zone_ashway_ashfall"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -5, 0, 0, 'HR', '#111111', '#b1bccd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slag_flarestack', 'Flarestack Field', 'A field of flare stacks stands dead against the sky, each tipped with a burner that hasn''t lit in a lifetime. The ground between them is glassed in patches where the flares used to rain fire, and the glass is full of things that got caught when it cooled.', 'low', 1, 0, 0, '["The wind moans across the mouth of a dead flare stack like breath over a bottle.","Underfoot the glassed ground crunches, and something small and fused stares up at you."]'::jsonb, '{"east":"zone_slag_catalyst","west":"zone_red_dreadfurnace","north":"zone_waste_cokeyard","south":"zone_slag_rail"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -10, -1, 0, 'FF', '#111111', '#e9b282', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_drum_shop', 'Second Skin', 'The shop is narrow but makes good use of vertical space — racks of clothing climb toward the ceiling, organized by some colour-logic that only Cassius understands. The walls are covered in polaroid-style printouts of outfits, annotated in marker. A tailoring station dominates one corner: cutting mat, shears, a half-dressed mannequin with pins in unfortunate places.', 'safe', 0, 0, 1, '["Fabric rustles softly on a rack as air moves through the shop.","The spool-shaped sign outside buzzes faintly through the wall.","A mannequin slowly loses a pin to gravity. It hits the floor without drama.","The squeak of a hanger being slid along a rail.","Scissors catch the light from somewhere in the back."]'::jsonb, '{"out":"zone_drum_exterior","down":"zone_drum_basement"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1783059649', 'map_int_drum', 'zone_drum_exterior', 0, 0, 0, NULL, NULL, '#e08a4a', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_gutter', 'Gutter Market', 'Trestle tables of salvaged meat, bruised pills, and dead men''s boots. The vendors don''t make eye contact and neither should you.', 'medium', 1, 0, 1, '["A butcher slaps down a cut you decide not to identify.","A vendor sweeps a tarp over her table the instant a patrol light sweeps the row."]'::jsonb, '{"east":"zone_weapons_exterior","south":"zone_deep_gasp"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 2, 2, 0, 'GM', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_wormtown', 'Wormtown', 'Tunnelled into a collapsed parkade, Wormtown is all dripping concrete and squatter-cant scrawled on every pillar.', 'medium', 1, 0, 1, '["A squatter recites directions to nowhere in a sing-song cant.","Water finds a new path through the concrete overhead and chooses your collar."]'::jsonb, '{"west":"zone_deep_rotrow","north":"zone_deep_cardboard"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, -1, 3, 0, 'WT', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_rotrow', 'Rot Row', 'The smell arrives before you do — a terrace of failed refrigeration and the produce it couldn''t save. Flies the size of thumbnails work the air.', 'medium', 1, 0, 1, '["A drift of flies lifts, resettles, lifts again.","Something drips steadily from an awning that has no business being wet."]'::jsonb, '{"east":"zone_deep_wormtown","north":"zone_deep_warrens"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, -2, 3, 0, 'RR', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_scab', 'Scab Alley', 'A knife-narrow cut between tenements, the floor slick with things best not named. Deals happen fast here, and so does everything else.', 'medium', 1, 0, 1, '["A deal goes wrong two doorways down. Then very quiet.","Fresh graffiti drips over old graffiti over older blood."]'::jsonb, '{"west":"zone_slums","south":"zone_deep_bonepicker"}'::jsonb, '{"lawless":true,"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 1, 2, 0, 'SC', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_gasp', 'Gasp Hollow', 'A sunken hollow where the air goes thin and chemical. Regulars breathe through rags; newcomers cough up their welcome.', 'high', 1, 0, 1, '["Your throat closes for a second on a lungful of something sweet and wrong.","A regular offers you a rag for a price, already knowing you''ll pay it."]'::jsonb, '{"east":"zone_deep_deepmaw","west":"zone_deep_bonepicker","north":"zone_deep_gutter"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 2, 3, 0, 'GH', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_deepmaw', 'The Deep Maw', 'The bottom of the bottom. Past here the Sprawl stops pretending to be a city and starts being a wound.', 'high', 1, 0, 1, '["Far below, something large shifts its weight and settles.","The dark down here has a grain to it, like it''s watching back."]'::jsonb, '{"east":"zone_meat_offal","west":"zone_deep_gasp"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 3, 3, 0, 'DM', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_maw', 'The Maw', 'The Sprawl opens its throat here: a downward-sloping plaza where the Undermarket swallows anyone with nothing left to trade but themselves.', 'medium', 1, 0, 1, '["The crowd parts around something on the ground and closes again without looking.","A busker plays a gutted keyboard, three keys, over and over."]'::jsonb, '{"north":"zone_slums"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 0, 3, 0, 'MW', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_bonepicker', 'Bonepicker''s End', 'A dead-end court where the scavengers sort their hauls — piles of picked-clean chassis and, now and then, picked-clean people.', 'medium', 1, 0, 1, '["A picker weighs a fistful of teeth on a hanging scale.","Someone whistles a warning and the whole court goes still."]'::jsonb, '{"east":"zone_deep_gasp","north":"zone_deep_scab"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 1, 3, 0, 'BP', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_util_zone_meridian_lobby', 'The Meridian - Lobby — Utility Room', 'A cramped below-grade utility room: bare concrete, sweating pipes, and the building junction box humming in its steel cabinet.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_meridian_lobby"}'::jsonb, '{"is_interior":true,"utility_room":true,"world_exit_zone":"zone_meridian"}'::jsonb, NULL, '1783116355', 'map_int_meridian', NULL, 0, 0, -1, NULL, NULL, '#8e6fd0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
