INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_civ_sortation', 'Sortation Yard', 'A dead-letter depot where a sorting belt still crawls, shuffling parcels to addresses that burned down years ago. The bot at the end never stops stamping.', 'low', 0, 0, 1, '["The belt delivers a parcel addressed to a building that is now a crater.","The sorting bot stamps RETURN TO SENDER on a rat and moves on."]'::jsonb, '{"east":"zone_warehouse"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -3, -1, 0, 'SY', '#111111', '#7fda9a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_gravel', 'Gravel Throat', 'A choked culvert of crushed concrete and rebar, funnelling the wind into a low continuous growl. Footing is bad and getting worse.', 'low', 0, 0, 1, '["A slab shifts underfoot and settles with a stony grunt.","The throat exhales a gust that carries the smell of old rain and rust."]'::jsonb, '{"south":"zone_waste_endcut"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -4, -2, 0, 'GV', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_up_chrome', 'Chrome Heights', 'Mirror-glass frontages and valet drones. The Heights look down on the Marquee''s neon like it''s a stain they''ve already hired someone to remove.', 'safe', 0, 0, 1, '["A valet drone waits by a car you could never afford to breathe on.","Your reflection follows you across a dozen panes, each a little more judged."]'::jsonb, '{"east":"zone_corp_investor","south":"zone_mq_chrome_court"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 4, -2, 0, 'CH', '#eeeeee', '#42c96a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_civ_steps', 'Civic Steps', 'A broad municipal stair that once led somewhere that mattered. Now it just connects the records office to the water, and the pigeons have claimed the landings.', 'safe', 0, 0, 1, '["A gull and a pigeon dispute a chip wrapper on the steps.","Wind off the bay carries the smell of salt and diesel up the stair."]'::jsonb, '{"east":"zone_media_plaza","west":"zone_civ_ledger","north":"zone_up_vellum"}'::jsonb, '{"artery":["Quay Road"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, -1, -3, 0, 'ST', '#111111', '#7fda9a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_grit', 'Grit Row', 'A row of half-buried machine shells, their guts long picked over, their shadows the only shade for a mile. Something dens in the biggest of them.', 'medium', 0, 0, 1, '["Metal groans inside a machine shell, then thinks better of it.","A grit-devil spins up, wanders the row, and collapses."]'::jsonb, '{"east":"zone_deep_waste","west":"zone_waste_verge"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -4, 1, 0, 'GT', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_cardboard', 'Cardboard Row', 'A gutter of flattened appliance boxes and pallet-wood shanties. Cook-fires gutter in oil drums and the greasy smoke never quite clears.', 'medium', 1, 0, 1, '["A child watches you from a refrigerator-box doorway and does not blink.","Something in an oil drum pops and sends up a gout of blue flame."]'::jsonb, '{"south":"zone_deep_wormtown"}'::jsonb, '{"lawless":true,"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, -1, 2, 0, 'CD', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_up_aid', 'Aid Station', 'A pre-Handoff triage kiosk someone keeps running out of pure spite and expired supplies. A medibot with one working arm sorts the walking wounded by who can pay.', 'safe', 0, 0, 1, '["The medibot''s good arm gestures NEXT to no one in particular.","A vending machine offers bandages, saline, and, inexplicably, cologne."]'::jsonb, '{"west":"zone_civ_meltwater","north":"zone_civ_ledger","south":"zone_warehouse"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, -2, -2, 0, 'AD', '#eeeeee', '#42c96a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_up_skyway', 'Skyway Landing', 'Where an elevated skyway touches down among planters of engineered ferns. The air is filtered; you can tell because it tastes like nothing at all.', 'safe', 0, 0, 1, '["A skyway car sighs past overhead, full of faces that don''t look down.","A planter mists itself on a schedule indifferent to the weather."]'::jsonb, '{"north":"zone_dock_fishmarket","south":"zone_mq_cathode"}'::jsonb, '{"artery":["Cathode Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 3, -2, 0, 'SK', '#eeeeee', '#42c96a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_verge', 'The Verge', 'The lip of the wastes proper, where the Haul Road''s shoulder crumbles into scree. Beyond, the grey goes on longer than seems fair.', 'low', 0, 0, 1, '["Scree hisses down the verge, dislodged by nothing you can see.","A haul truck''s ghost-glare sweeps the road above and is gone."]'::jsonb, '{"east":"zone_waste_grit","west":"zone_waste_deadflat"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -5, 1, 0, 'VG', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_windrow', 'The Windrow', 'Wind has heaped the district''s garbage into a long grey dune here, a windrow of ash and packaging that shifts and mutters.', 'low', 0, 0, 1, '["The windrow slumps with a sigh and buries something that was showing.","Grit ticks against your teeth on a gust off the dune."]'::jsonb, '{"east":"zone_civ_commons","west":"zone_waste_molten"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -4, -3, 0, 'WD', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_nadir', 'The Nadir', 'The low point of the whole basin, where every runoff eventually arrives. A crust of dried chemistry cracks under your boots in bright, wrong colours.', 'medium', 0, 1, 1, '["The crust cracks in a colour that has no honest name.","Something half-dissolved twitches in a puddle and goes still."]'::jsonb, '{"east":"zone_deep_tarpit","west":"zone_waste_coalsack","south":"zone_waste_bailey"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -4, 2, 0, 'ND', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_coalsack', 'Coalsack', 'A slag pit gone black and glassy, so dark it drinks the light. The counter on anything you carry ticks a little faster here.', 'medium', 0, 1, 1, '["The black glass underfoot crunches like frozen tar.","A dry heat rises off the pit though there is nothing burning."]'::jsonb, '{"east":"zone_waste_nadir","west":"zone_waste_tipple","south":"zone_waste_grime"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -5, 2, 0, 'CK', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_tarpit', 'Tarpit Edge', 'Where the Undermarket''s runoff meets the wastes — a black seep of tar and worse, worked by pickers who answer to the gangs uphill.', 'medium', 1, 0, 1, '["A picker sinks a pole into the seep and hauls up something that drips.","A gang tag, still wet, claims the tarpit for the week."]'::jsonb, '{"east":"zone_deep_warrens","west":"zone_waste_nadir","north":"zone_deep_waste","south":"zone_deep_sink"}'::jsonb, '{"lawless":true,"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -3, 2, 0, 'TP', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_dock_wharf', 'The Wharf', 'The working face of Coldwater Docks: bollards worn smooth, cargo nets stiff with salt, and the whole thing groaning gently on its pilings with the swell.', 'low', 0, 0, 1, '["A crane somewhere lowers a pallet with a shriek of unoiled cable.","The wharf shifts underfoot as a swell rolls in, and settles."]'::jsonb, '{"east":"zone_dock_quays","west":"zone_media_plaza","north":"zone_dock_coldstore","south":"zone_up_gate"}'::jsonb, '{"artery":["Quay Road"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 1, -3, 0, 'WH', '#111111', '#50e0d5', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_rebar', 'Rebar Field', 'A cleared lot bristling with the rebar stubs of buildings that never got past their foundations. The bay wind whistles through the iron like a bad flute.', 'low', 0, 0, 1, '["Wind draws a low tuneless note from a forest of rebar.","Rust flakes drift off the iron and settle on everything, including you."]'::jsonb, '{"south":"zone_media_plaza"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 0, -4, 0, 'RF', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_bailey', 'The Bailey', 'The broken ring-wall of some old containment yard, its bailey now a killing-floor of blind corners and drifted ash. Things nest in the wall.', 'medium', 0, 1, 1, '["Ash sifts from a murder-hole overhead in a thin grey thread.","Down a blind corner, something exhales and waits to see if you follow."]'::jsonb, '{"east":"zone_deep_sink","west":"zone_waste_grime","north":"zone_waste_nadir"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -4, 3, 0, 'BY', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_grime', 'Grime Row', 'A sunken lane filmed in decades of industrial grime, every surface tacky to the touch. The husks out here don''t rust so much as fester.', 'medium', 0, 1, 1, '["A husk in the grime shifts its weight with a wet, deliberate creak.","Your handprint stays on the wall behind you, glistening."]'::jsonb, '{"east":"zone_waste_bailey","west":"zone_waste_runoff","north":"zone_waste_coalsack"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -5, 3, 0, 'GR', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_sink', 'The Sink', 'The lowest drain of the Sprawl, where everything the Undermarket can''t sell finally settles. The smell has a shape you can lean on.', 'medium', 1, 0, 1, '["The sink glugs, swallows, and belches up a shoe.","A rat the size of a loaf regards you, unimpressed, and dog-paddles on."]'::jsonb, '{"west":"zone_waste_bailey","north":"zone_deep_tarpit"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -3, 3, 0, 'SK', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_util_zone_drum_basement', 'Second Skin — Utility Room — Utility Room', 'A cramped below-grade utility room: bare concrete, sweating pipes, and the building junction box humming in its steel cabinet.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_drum_basement"}'::jsonb, '{"is_interior":true,"utility_room":true,"world_exit_zone":"zone_drum_exterior"}'::jsonb, NULL, '1783116358', 'map_int_drum', 'zone_drum_exterior', 0, 0, -2, NULL, NULL, '#8e6fd0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_rustmarsh', 'Rust Marsh', 'Runoff has pooled into a shallow marsh the colour of old blood, reeds of rebar standing in water that stains everything it touches. Something big moves in the deeper channels.', 'medium', 0, 0, 1, '["A wake crosses the rust-marsh between the rebar reeds and is gone.","Orange water laps at your boots and leaves a tidemark that won''t wash out."]'::jsonb, '{"east":"zone_waste_palings"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -7, -1, 0, 'RM', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_dross', 'Dross Flat', 'An open flat carpeted in dross — the skimmed scum of a thousand melts, light as pumice and sharp as spite. It crunches, endlessly, wherever you step.', 'low', 0, 0, 1, '["The dross crunches underfoot in a way that carries too far.","A dust-devil of grey skim spins up, wanders the flat, and dies."]'::jsonb, '{"east":"zone_waste_smoulder","west":"zone_waste_cindersteps"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -6, -2, 0, 'DR', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_barges', 'Moored Barges', 'A raft of dead barges lashed together into a floating slum-annex, rising and falling as one. You cross the harbour here by stepping from deck to swaying deck.', 'low', 0, 0, 1, '["A barge deck tilts under your weight and rights itself, unbothered.","Washing strung between two barges drips into the black water below."]'::jsonb, '{"north":"zone_bay_fog"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 3, -4, 0, 'MB', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_civ_ledger', 'Ledger Hall', 'A municipal records office running on one flickering terminal and a clerk who outlived the department. Filing cabinets tower into the dark, alphabetised by a system since lost.', 'safe', 0, 0, 1, '["A cabinet drawer rolls open on its own and hangs there, accusing.","The lone terminal chirps, prints a single blank slip, and sleeps again."]'::jsonb, '{"east":"zone_civ_steps","west":"zone_civ_commons","south":"zone_up_aid"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -2, -3, 0, 'LG', '#111111', '#7fda9a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_dock_quays', 'The Quays', 'A run of stone quays where the fishing boats tie up and the cargo dhows unload after dark. Everything smells of tar, brine, and old fish.', 'low', 0, 0, 1, '["A mooring line creaks taut, then slack, then taut.","A stevedore spits into the water and watches it a while."]'::jsonb, '{"east":"zone_dock_fishmarket","west":"zone_dock_wharf","south":"zone_up_approach"}'::jsonb, '{"artery":["Quay Road"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 2, -3, 0, 'QY', '#111111', '#50e0d5', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_dock_boatyard', 'The Boat Yard', 'A slipway of half-built and half-scrapped hulls, propped on stands, ribs bared to the weather. A shipwright works one of them with a heat-gun and a grudge.', 'low', 0, 0, 1, '["A hull rings like a bell as the shipwright drives a rivet home.","A skeletal boat on its stand casts a cage of shadow across the yard."]'::jsonb, '{"east":"zone_nc_manifold","north":"zone_bay_breakwater","south":"zone_dock_slip"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 4, -4, 0, 'BY', '#111111', '#50e0d5', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_cindersteps', 'Cinder Steps', 'A flight of fused-cinder terraces climbs the spoil-heap, each step a strata of a different bad decade. Your boots grind glass with every stride.', 'low', 0, 0, 1, '["A terrace edge crumbles to cinder-glass and slides away downslope.","Ash lifts off the steps in a low sheet and resettles behind you."]'::jsonb, '{"east":"zone_waste_dross","west":"zone_waste_blight"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -7, -2, 0, 'CN', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_smoulder', 'The Smoulder', 'A seam of buried refuse that has been smouldering underground for years, venting thin acrid smoke through cracks in the crust. The ground is warm and wrong.', 'low', 0, 0, 1, '["Warm smoke threads up through a crack and coils around your ankles.","The crust flexes underfoot, warm as a living thing, and settles."]'::jsonb, '{"west":"zone_waste_dross","south":"zone_waste_slake"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -5, -2, 0, 'SM', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_molten', 'Molten Row', 'A row of tapped-out smelter troughs, the slag in them cooled to glassy rope decades ago. Heat-ghosts still shimmer off the metal on the worst afternoons.', 'low', 0, 0, 1, '["Cooled slag ticks and settles in a trough as if remembering being poured.","A heat-shimmer rises off dead metal though there is nothing to make it."]'::jsonb, '{"east":"zone_waste_windrow","west":"zone_waste_tarseep"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -5, -3, 0, 'MR', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_tipple', 'The Tipple', 'The skeleton of an ore tipple leans over the flat, its chutes long empty, its gantries a roost for things with too many legs. Rust rains down whenever the wind leans on it.', 'medium', 0, 0, 1, '["A gantry sheds a slow rain of rust as the wind leans on the tipple.","Something with too many legs adjusts its grip on a chute overhead."]'::jsonb, '{"east":"zone_waste_coalsack","west":"zone_waste_ferro","south":"zone_waste_runoff"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -6, 2, 0, 'TT', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_ferro', 'Ferro Flat', 'A field so saturated with iron oxide that a dropped blade rusts to lace by morning. The whole flat sings a faint magnetic whine that sets your fillings buzzing.', 'medium', 0, 0, 1, '["A thin magnetic whine rises, sets your teeth on edge, and fades.","Rust blooms visibly across a scrap you pass, like a wound opening."]'::jsonb, '{"east":"zone_waste_tipple","west":"zone_waste_drossworks","south":"zone_waste_cinderway"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -7, 2, 0, 'FF', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_gantry', 'Gantry Yard', 'A forest of gantry cranes straddles the tracks here, lifting and placing with slow enormous care. Standing beneath them is a trust exercise the Yards runs on you daily.', 'low', 0, 0, 1, '["A gantry crane passes overhead, its shadow crossing you like a slow eclipse.","A load hangs, sways, and is set down a hand''s breadth from where you stand."]'::jsonb, '{"west":"zone_yard_freightworks","north":"zone_corp_argent","south":"zone_yard_crane"}'::jsonb, '{"artery":["Quay Road","Reefer Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 8, -3, 0, 'GY', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_cinderway', 'Cinderway', 'An old haul-road paved in packed cinder runs south into nothing, edged with the burnt-out shells of the trucks that used it. The way is clear; the reasons to take it are not.', 'medium', 0, 0, 1, '["A truck shell ticks as the day''s heat leaves it, settling on flat tyres.","The cinderway stretches south into a grey haze that never quite resolves."]'::jsonb, '{"east":"zone_waste_runoff","west":"zone_waste_hopper","north":"zone_waste_ferro"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -7, 3, 0, 'CW', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_media_plaza', 'Mediaform Plaza', 'A hard-surfaced plaza dominated by a three-storey media wall that loops harbour-safety propaganda to an audience of nobody. A camera drone tracks anything that moves.', 'safe', 0, 0, 1, '["The media wall cheerfully reminds you that DROWNING IS PREVENTABLE.","A camera drone swivels, fixes on you, loses interest."]'::jsonb, '{"east":"zone_dock_wharf","west":"zone_civ_steps","north":"zone_waste_rebar"}'::jsonb, '{"artery":["Quay Road"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 0, -3, 0, 'MP', '#111111', '#efe8a4', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_dock_fishmarket', 'Fishmarket Dock', 'Trestle slabs of pale bay catch under a sagging awning, worked by fishmongers who gut and call and gut without pause. The runoff makes the boards treacherous.', 'low', 0, 0, 1, '["A fishmonger splits something long and pale with a single wet stroke.","Cats gather at the edge of the market, patient as debt collectors."]'::jsonb, '{"east":"zone_dock_slip","west":"zone_dock_quays","south":"zone_up_skyway"}'::jsonb, '{"artery":["Quay Road","Cathode Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"fishing_table_id":"fish_coldwater_bay","scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 3, -3, 0, 'FM', '#111111', '#50e0d5', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_hopper', 'The Hopper', 'A collapsed loading hopper forms a steel-walled sinkhole here, its throat choked with drifted ash and the odd picked-clean bone. Things climb out of it at night.', 'medium', 0, 0, 1, '["Ash hisses down the hopper''s throat into a dark that never fills.","A bone, picked white, rolls up out of the hopper''s mouth and stops at your feet."]'::jsonb, '{"east":"zone_waste_cinderway","west":"zone_waste_dustreach","north":"zone_waste_drossworks"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -8, 3, 0, 'HP', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_endcut', 'The Endcut', 'Where the paved city simply ends — a ragged cut of exposed foundations and severed pipes bleeding rust down onto the wastes below.', 'low', 0, 0, 1, '["A severed pipe releases a slow brown weep that never quite stops.","Somewhere below, a foundation ticks as it cools into the evening."]'::jsonb, '{"west":"zone_waste_slake","north":"zone_waste_gravel"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -4, -1, 0, 'EC', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_deadwater', 'Dead Water', 'A becalmed pocket of the bay where nothing moves and sound goes flat. Boats avoid it; the ones that didn''t are still here, mostly under.', 'low', 0, 0, 1, '["The dead water swallows the sound of your own footsteps.","A mast tilts up out of the flat water, marking a boat that stayed too long."]'::jsonb, '{"east":"zone_bay_reach","west":"zone_bay_slick","south":"zone_bay_mid"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 2, -7, 0, 'DW', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_spindle', 'The Spindle', 'The base of a slender comms spindle that climbs out of sight, humming with the whole district''s data. Standing near it makes your teeth ache and your deck light up with things it shouldn''t.', 'safe', 0, 0, 1, '["The spindle''s hum steps up a semitone, then settles.","Your gear chirps at signals it has no business receiving."]'::jsonb, '{"west":"zone_nc_datum"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 0, -5, 0, 'SP', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_runoff', 'The Runoff', 'Where the flats drain, a sludge-choked culvert carries the day''s worst chemistry down into the dark. The smell has teeth. Something upstream keeps it fed.', 'medium', 0, 0, 1, '["The runoff glugs and shifts as something upstream lets more through.","A slick of colours that shouldn''t exist together slides past and is gone."]'::jsonb, '{"east":"zone_waste_grime","west":"zone_waste_cinderway","north":"zone_waste_tipple"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -6, 3, 0, 'RO', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_skyline', 'Skyline Walk', 'A glass promenade cantilevered out over the drop, the whole grey city and greyer bay laid out beneath your feet through the floor. Vertigo is included in the rent.', 'safe', 0, 0, 1, '["The glass floor creaks reassuringly and shows you the long way down.","A resident jogs past on the skyline walk, eyes forward, seeing none of it."]'::jsonb, '{"west":"zone_gov_vantage","north":"zone_nc_halcyon","south":"zone_nc_datum"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, -1, -6, 0, 'SK', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_deadflat', 'Dead Flat', 'A hardpan so lifeless the scavengers use it as a boundary: past here, nothing grows, nothing dens, nothing bothers. Which is its own kind of warning.', 'low', 0, 0, 1, '["Nothing moves on the dead flat. Nothing at all. It''s unnerving.","Your own footsteps come back off the hardpan a half-beat late."]'::jsonb, '{"east":"zone_waste_verge","west":"zone_waste_ashenverge"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -6, 1, 0, 'DF', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_embassy_floor3', 'Embassy Hotel & Bar — Third Floor Landing', 'Top of the stairwell — the third-floor landing, closer to the roof and colder for it. Water stains bloom brown across the ceiling tiles, one sagging low enough to drip when it rains. Units 3A through 3D ring the landing, their doors heavier up here, the locks newer; people who climb this far want to stay lost. A single emergency light burns a weak red over the stairwell mouth, the only bulb on the floor that still works. The iron railing ends in a broken newel post someone''s wrapped in duct tape.', 'safe', 0, 0, 1, '["The sagging ceiling tile releases a slow, deliberate drip.","The red emergency light buzzes, dims, and steadies again."]'::jsonb, '{"down":"zone_embassy_floor2","east":"zone_apt_11","west":"zone_apt_12","north":"zone_apt_9","south":"zone_apt_10"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783112361', 'map_interior_zone_residential_lobby', 'zone_residential_lobby', 0, 0, 2, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_prefect', 'Prefect Plaza', 'The plaza fronting the Prefecture, where the queue for permits, papers, and pardons wraps twice around a dry fountain. The Prefecture issues all three, at a price and a delay.', 'safe', 0, 0, 1, '["The permit queue advances one place and a small cheer goes up.","A prefecture clerk stamps a document, considers it, and stamps it again."]'::jsonb, '{"east":"zone_nc_halcyon","west":"zone_gov_assembly"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -2, -7, 0, 'PF', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_sootbank', 'Sootbank', 'A long bank of packed soot heaped against a fallen retaining wall, black and greasy and warm in patches where something still smoulders beneath.', 'low', 0, 0, 1, '["A patch of the sootbank glows dull orange, then darkens as you watch.","Your boots come away black, and stay black, no matter what you do."]'::jsonb, '{"east":"zone_waste_slaghollow","west":"zone_waste_greymile","north":"zone_waste_leachfield"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -5, -4, 0, 'SB', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_emberwaste', 'Ember Waste', 'A stretch of ground that burned so long ago and so completely that it still, on cold nights, remembers the fire — a faint orange breathing deep in the cracks.', 'low', 0, 0, 1, '["An ember-glow breathes deep in a crack, then fades, then breathes again.","Warmth rises through the sole of your boot from a fire decades dead."]'::jsonb, '{"east":"zone_waste_cull","west":"zone_waste_slaghollow"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -3, -4, 0, 'EW', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_floes', 'The Floes', 'Runoff and cold have crusted this corner of the bay with rafts of grey ice that grind together and apart. You cross by timing the floes, which is exactly as advisable as it sounds.', 'low', 0, 0, 1, '["Two ice floes grind together with a sound like a slow scream.","A floe tips under your weight, rights itself, and drifts on, unbothered."]'::jsonb, '{"east":"zone_bay_basin","west":"zone_bay_deep","north":"zone_bay_narrows","south":"zone_bay_breakwater"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 4, -6, 0, 'FL', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_102', 'Unit 102', 'A studio that still has its original built-in cabinetry, half the doors missing, the rest painted shut. A mattress on a pallet, a chair, a view of the square if you press your face to the glass. Home.', 'safe', 0, 0, 1, '["Pipes knock somewhere in the walls. The building is old but it holds."]'::jsonb, '{"west":"zone_mq_chrome_f1"}'::jsonb, '{"is_apartment":true}'::jsonb, NULL, '1782964408', 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 1, 0, 1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_chrome_f1', 'Chrome Court — Floor 1', 'The first-floor hallway of Chrome Court, a tunnel of amber emergency light and doors painted so many times the numbers are just suggestions. The carpet is worn to jute down the center where every tenant walks the identical line. Four units open off the hall. A window at the end looks out over the district''s neon, which from up here almost looks like a city that works.', 'safe', 0, 0, 1, '["A door down the hall closes with the finality of a lock turning.","The amber emergency light hums and dims by a shade.","Something is cooking behind one of the doors; the smell almost reaches you.","The end-of-hall window rattles as the wind leans on it."]'::jsonb, '{"up":"zone_mq_chrome_f2","down":"zone_mq_chrome_lobby","east":"zone_mq_chrome_102","west":"zone_mq_chrome_104","north":"zone_mq_chrome_101","south":"zone_mq_chrome_103"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782964408', 'map_int_mq_chrome', 'zone_mq_chrome_lobby', 0, 0, 1, NULL, NULL, '#e85aa0', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_slaghollow', 'Slaghollow', 'A hollow scooped from the flats where cooled slag was once dumped and forgotten. Rain has pooled in the bottom into something that reflects nothing.', 'low', 0, 0, 1, '["The pool in the hollow''s bottom holds perfectly still, reflecting no sky.","Slag glass clinks and shifts on the hollow''s slope, resettling."]'::jsonb, '{"east":"zone_waste_emberwaste","west":"zone_waste_sootbank","north":"zone_waste_ashensteppe"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -4, -4, 0, 'Sw', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_mezzanine', 'The Mezzanine', 'The half-floor between departments where the truly stalled paperwork goes to age. Interdepartmental mail carts trundle through on rails, delivering forms to forms.', 'safe', 0, 0, 1, '["A mail cart trundles across the mezzanine and delivers a form to another form.","The mezzanine''s paperwork rustles in a draught with a sound like distant applause."]'::jsonb, '{"down":"zone_under_landing","east":"zone_gov_onyx","north":"zone_gov_cobalt"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -3, -5, 0, 'MZ', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_corp_boardroom', 'Boardroom Row', 'The boardrooms of the consignment houses, glass-walled and climate-perfect, where cargo is bought, insured, and betrayed over water nobody drinks. The Yards'' grime stops precisely at the door.', 'safe', 0, 0, 1, '["A boardroom''s glass wall fogs to opaque mid-meeting, then clears, empty.","A consignment is agreed with a handshake and a look that promises litigation."]'::jsonb, '{"east":"zone_yard_container","west":"zone_dock_slip","north":"zone_nc_manifold","south":"zone_corp_investor"}'::jsonb, '{"artery":["Quay Road"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 5, -3, 0, 'Br', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_civ_meltwater', 'Meltwater Row', 'A municipal water point where a queue forms daily at a bank of hissing taps. The line has its own etiquette, its own enforcers, and a very long memory.', 'low', 0, 0, 1, '["A tap coughs, spits brown, then runs clear to a small ragged cheer.","Someone loses their place in line and does not make that mistake twice."]'::jsonb, '{"east":"zone_up_aid"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -3, -2, 0, 'MT', '#111111', '#7fda9a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_ashensteppe', 'Ashen Steppe', 'A wide grey steppe of drifted ash that runs west toward worse. The wind has combed it into long dunes that erase your trail as fast as you make it.', 'low', 0, 0, 1, '["Wind combs the ashen steppe into a new dune-line and erases your last step.","Far to the west, something red flickers on the horizon, and is gone."]'::jsonb, '{"west":"zone_waste_leachfield","south":"zone_waste_slaghollow"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -4, -5, 0, 'AE', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_cull', 'The Cull', 'The government''s unofficial dumping ground for what it would rather forget — records, machinery, and now and then people. The scavengers work it carefully; the government watches it not at all.', 'medium', 0, 0, 1, '["A picker in the cull uncovers a government seal and pockets it, fast.","A shredded drift of official documents lifts, swirls, and resettles like snow."]'::jsonb, '{"west":"zone_waste_emberwaste"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -2, -4, 0, 'CL', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_lobby', 'The Meridian - Lobby', 'The ground-floor lobby of The Meridian, a residential tower that survived the Collapse the same way most things survived it: through sheer institutional inertia. Cracked terrazzo floors carry the ghost of a geometric inlay, ground to near-invisibility by foot traffic. A bank of tenant mailboxes lines the east wall — most of them pried open decades ago, doors hanging at odd angles, contents long gone. The security desk sits unmanned, its terminal cycling a screensaver of rolling static. A brass plaque reading THE MERIDIAN — ESTABLISHED 2031 is still bolted above the entrance, which is the most optimistic thing in the building. Emergency lighting casts everything in pale amber. Stairs ascend through a fire door to the upper floors.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_meridian_floor_1","out":"zone_meridian","down":"zone_util_zone_meridian_lobby"}'::jsonb, '{"is_building":true,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":"apartment","world_exit_zone":"zone_meridian","scavenging_table_id":null}'::jsonb, NULL, '1783112116', 'map_int_meridian', NULL, 0, 0, 0, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_roof', 'The Meridian — Roof', 'Cracked tar and gravel, hemmed by a low concrete parapet stenciled with emergency contact numbers no one has answered in years. Rusted antenna masts and conduit runs crowd the edges — relics of broadcast infrastructure nobody maintained long enough to matter. The city stretches out in every direction: an unbroken plane of light pollution and industrial haze that could almost pass for a skyline at night if you let your eyes go soft. Up here the building''s recycled air ends and the real thing begins — it tastes like ozone and diesel particulate and something faintly sulphuric drifting in from the eastern refineries. Wind cuts across the gravel with nothing to stop it. A heavy-duty junction box is mounted to the stairwell housing near the hatch.', 'safe', 0, 0, 0, '[]'::jsonb, '{"down":"zone_meridian_floor_6"}'::jsonb, '{"open_sky":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783112403', 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 7, NULL, NULL, '#c9a884', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_leachfield', 'The Leachfield', 'The buried leach-beds of the old city drain here, seeping a slow chemical weep to the surface that kills the ground in bright, geometric patches.', 'medium', 0, 0, 1, '["A patch of ground fizzes gently as something leaches up through it.","The chemical weep has drawn a perfect dead circle in the ash. You step around it."]'::jsonb, '{"east":"zone_waste_ashensteppe","west":"zone_waste_scrapmesa","north":"zone_waste_scald","south":"zone_waste_sootbank"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -5, -5, 0, 'LF', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_breakwater', 'The Breakwater', 'A spine of tumbled concrete and rebar thrown out to break the bay''s temper, walkable if you mind your footing. Things nest in the gaps between the blocks.', 'low', 0, 0, 1, '["A wave slaps the breakwater and throws cold spray across the blocks.","Something withdraws into a gap in the concrete as your shadow falls on it."]'::jsonb, '{"east":"zone_nc_highwater","west":"zone_bay_fog","north":"zone_bay_floes","south":"zone_dock_boatyard"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 4, -5, 0, 'BW', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_datum', 'Datum Court', 'A survey marker set in brass declares this the city''s official datum — the point from which all heights and depths are measured. Someone has scratched YOU ARE HERE beneath it, and it feels like a threat.', 'safe', 0, 0, 1, '["The brass datum marker gleams, recently and pointlessly polished.","A tour drone recites the court''s significance to an audience of pigeons."]'::jsonb, '{"east":"zone_nc_spindle","west":"zone_gov_onyx","north":"zone_nc_skyline","south":"zone_up_vellum"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, -1, -5, 0, 'DT', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_palings', 'The Palings', 'A fence-line of scrap palings marches across the flat, warning off nobody. Rags and older things hang from the pickets, turning slowly in the wind.', 'low', 0, 0, 1, '["A rag on a paling turns to face you, then turns away.","The palings creak in sequence down the line, as if counting you past."]'::jsonb, '{"east":"zone_waste_slake","west":"zone_waste_rustmarsh"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -6, -1, 0, 'PL', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_slake', 'Slake Pond', 'The only clean-ish water for a mile, and so the only thing out here worth defending. A ragged scavenger camp rings the pond — lean-tos, a cook-fire, and eyes that track every newcomer.', 'low', 0, 0, 1, '["Someone at the camp fire looks up, weighs you, and goes back to the pot.","A scavenger fills a jug at the pond''s edge and hurries it back to the lean-tos."]'::jsonb, '{"east":"zone_waste_endcut","west":"zone_waste_palings","north":"zone_waste_smoulder"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -5, -1, 0, 'SL', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_embassy_floor2', 'Embassy Hotel & Bar — Second Floor Landing', 'The second-floor landing, where the hotel''s old carpet runner gives up entirely — bare concrete underneath, worn pale in a path between the stairs and the doors. Four units open off it, brass numbers screwed to each: 2A through 2D, a couple hanging by a single screw. The stairwell railing is cold iron, sticky where a thousand hands have gripped it. A dead vending machine hulks in the corner, its glass front spider-cracked, the snacks inside fossilised. Somewhere below, the bar''s murmur leaks up through the floor.', 'safe', 0, 0, 1, '["A door slams somewhere down the hall, and a chain rattles into place.","The dead vending machine emits a single, hopeless click."]'::jsonb, '{"up":"zone_embassy_floor3","down":"zone_residential_lobby","east":"zone_apt_7","west":"zone_apt_8","north":"zone_apt_5","south":"zone_apt_6"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null}'::jsonb, NULL, '1783020605', 'map_interior_zone_residential_lobby', 'zone_residential_lobby', 0, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_floor_1', 'The Meridian — Floor 1 Hallway', 'Floor 1 of The Meridian. A narrow corridor stretches between four unit doors — numbers 101, 102, 103, 104 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_meridian_floor_2","down":"zone_meridian_lobby","east":"zone_meridian_unit_102","west":"zone_meridian_unit_104","north":"zone_meridian_unit_101","south":"zone_meridian_unit_103"}'::jsonb, '{"is_interior":true}'::jsonb, NULL, '1782898109', 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 1, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian_floor_5', 'The Meridian — Floor 5 Hallway', 'Floor 5 of The Meridian. A narrow corridor stretches between four unit doors — numbers 501, 502, 503, 504 — stamped in adhesive metal letters, most of which have survived. The walls are poured concrete behind a skim of paint that went off-white long ago, old marker tags bleeding through where the building manager gave up trying to buff them out. Synthetic carpet the color of old claret muffles every footfall. Sodium-orange emergency strips trace the baseboards. The recycled air carries the mingled residue of a dozen private lives: synthetic tobacco, mystery cooking, and the faint ionised bite of an ageing HVAC system.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_meridian_floor_6","down":"zone_meridian_floor_4","east":"zone_meridian_unit_502","west":"zone_meridian_unit_504","north":"zone_meridian_unit_501","south":"zone_meridian_unit_503"}'::jsonb, '{"is_building":false,"is_interior":true,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783111944', 'map_int_meridian', 'zone_meridian_lobby', 0, 0, 5, NULL, NULL, '#c9a884', 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_dray', 'Dray Street', 'The haulers'' street, lined with idling trucks and the cafes and card games that spring up wherever drivers wait. The engine-fug never lifts and the coffee is, somehow, worse than the fug.', 'low', 0, 0, 1, '["A trucker leans on their horn out of boredom and three others answer.","A card game folds abruptly as a dispatcher''s voice barks a load number."]'::jsonb, '{"east":"zone_yard_weighbridge","west":"zone_yard_loadout","south":"zone_yard_transfer"}'::jsonb, '{"artery":["Grand Avenue"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 7, 0, 0, 'Dy', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_marshalling', 'The Marshalling Yard', 'The great marshalling yard where trains are assembled car by car, a slow ballet of shunting and coupling conducted by a lone yard pilot with a flag and a death wish.', 'low', 0, 0, 1, '["Cars couple somewhere down the yard with a crash that rolls along the line.","The yard pilot waves a flag at a locomotive and, incredibly, is obeyed."]'::jsonb, '{"in":"zone_hangar_yard_marshalling","north":"zone_yard_pallet"}'::jsonb, '{"airfield_id":"af_marshalling","is_building":false,"is_interior":false,"is_apartment":false,"airfield_fuel":true,"airfield_name":"Marshalling Field","building_name":"","building_type":null,"airfield_fuels":["avgas","jet"],"airfield_dealer":false,"airfield_charter":true,"airfield_lawless":false,"scavenging_table_id":"scav_roadside_junk","hangar_interior_zone":"zone_hangar_yard_marshalling"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 7, -1, 0, 'Ma', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_halcyon', 'Halcyon Heights', 'The literal top of the city: a wind-scoured roof-plaza of glass and engineered calm, where the arcology''s owners take the air and look down on everything they own, which is everything.', 'safe', 0, 0, 1, '["A private drone escorts someone important across the plaza and away.","The wind up here is clean, cold, and somehow billed to your account."]'::jsonb, '{"east":"zone_nc_sable","west":"zone_gov_prefect","south":"zone_nc_skyline"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, -1, -7, 0, 'HH', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_bourse', 'The Bourse', 'Coldwater''s exchange floor, where cargo, debt, territory, and the occasional person are bought and sold by shouting at screens. The noise is a kind of weather.', 'safe', 0, 0, 1, '["A trader on the Bourse floor screams a number and a fortune changes hands.","The big board flickers red across the floor and the shouting climbs an octave."]'::jsonb, '{"west":"zone_nc_glass","south":"zone_nc_tessellate"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 8, -7, 0, 'Bo', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_crane', 'Crane Alley', 'A narrow service alley threaded between the crane bases, hung with control cables and the occasional operator''s washing. The machinery here is always warm and always listening.', 'low', 0, 0, 1, '["A crane base ticks with heat as its motors idle down.","A control cable overhead twitches as someone, somewhere, takes the sticks."]'::jsonb, '{"north":"zone_yard_gantry","south":"zone_yard_reefer"}'::jsonb, '{"artery":["Reefer Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 8, -2, 0, 'Cr', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_reefer', 'Reefer Row', 'A row of refrigerated cars humming on stolen power, breathing fog into the yard. What''s kept cold here ranges from legitimate to the kind of thing you smell before you see.', 'low', 0, 0, 1, '["A reefer car''s compressor kicks in with a shudder and a gout of fog.","Something in a reefer car has stopped being kept cold enough. The row knows."]'::jsonb, '{"north":"zone_yard_crane","south":"zone_yard_weighbridge"}'::jsonb, '{"artery":["Reefer Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 8, -1, 0, 'Rf', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_pallet', 'Pallet Row', 'Wooden pallets stacked into unstable ziggurats, splintered, stained, and endlessly recirculated. The whole row smells of wet timber and the ghost of whatever they last carried.', 'low', 0, 0, 1, '["A pallet ziggurat sheds a plank from its summit and no one flinches.","The wet-timber smell of Pallet Row gets into the back of your throat."]'::jsonb, '{"north":"zone_yard_freightworks","south":"zone_yard_marshalling"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 7, -2, 0, 'Pl', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_depot', 'The Depot', 'The Yards'' main depot and muster point, where crews clock on, trucks queue, and the day''s chaos is dispatched from a whiteboard nobody can read. The gateway between the yards and the city proper.', 'low', 0, 0, 1, '["A crew clocks on at the depot, reads the whiteboard, and gives up interpreting it.","A dispatcher shouts a truck number into the din and something, eventually, moves."]'::jsonb, '{"west":"zone_mq_chrome_court","north":"zone_corp_investor"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 5, -1, 0, 'Dp', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_boxcar', 'Boxcar Lane', 'A lane of derelict boxcars long since shunted off the rails and repurposed — into stores, squats, and the occasional very private meeting. Their doors are all differently, deliberately locked.', 'low', 0, 0, 1, '["A boxcar door slides shut from the inside as you pass.","Cook-smoke rises from a boxcar''s jury-rigged flue and hangs in the still air."]'::jsonb, '{"north":"zone_yard_sidings","south":"zone_yard_loadout"}'::jsonb, '{"artery":["Boxcar Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 6, -1, 0, 'Bx', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_consulate', 'The Consulate', 'A cluster of corporate consulates flying flags that are really just logos, where the great powers of the city keep missions to one another and pretend at diplomacy between raids.', 'safe', 0, 0, 1, '["A consular flag — a logo, really — is lowered and a subtly different one raised.","Two rival consuls pass on the steps and exchange smiles like drawn blades."]'::jsonb, '{"east":"zone_nc_ivory","west":"zone_bay_basin","north":"zone_nc_meridianheights","south":"zone_nc_palisade"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 6, -6, 0, 'Cs', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_ivory', 'Ivory Deck', 'An open deck of pale stone where the quarter takes its meetings in the open air, on the theory that it''s harder to bug a conversation held over a two-hundred-metre drop.', 'safe', 0, 0, 1, '["A meeting on the Ivory Deck breaks up the instant you come into earshot.","The wind off the deck snatches a document from a manicured hand and is thanked for it."]'::jsonb, '{"east":"zone_nc_tessellate","west":"zone_nc_consulate","north":"zone_nc_glass","south":"zone_nc_beacon"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 7, -6, 0, 'Id', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_loadout', 'The Loadout', 'The southern loadout bays where trucks back up to the docks and freight crosses from rail to road under the eye of a tally clerk who trusts absolutely no one, correctly.', 'low', 0, 0, 1, '["A truck backs to the loadout bay with a warning beep and a grinding stop.","The tally clerk counts a load twice, frowns, and counts it a third time."]'::jsonb, '{"east":"zone_yard_dray","west":"zone_mq_precinct","north":"zone_yard_boxcar","south":"zone_yard_chassis"}'::jsonb, '{"artery":["Grand Avenue","Boxcar Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 6, 0, 0, 'Lo', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_downwind', 'The Downwind', 'Set deliberately downwind of the heights so its stink never troubles them, this is where the quarter''s waste and worse is quietly let go. Things thrive here that the district denies exist.', 'medium', 0, 0, 1, '["A gust carries the Downwind''s stink briefly uphill, and a dozen windows shut.","Something feeds in the Downwind''s tip and does not look up as you pass."]'::jsonb, '{"east":"zone_corp_argent","west":"zone_waste_oxide","north":"zone_nc_beacon","south":"zone_yard_freightworks"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 7, -4, 0, 'Dw', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_palisade', 'The Palisade', 'A rampart-walk along the district''s edge, all defensive posturing and excellent sightlines, where private security patrol a wall that keeps out a threat the residents can''t name.', 'safe', 0, 0, 1, '["A security operator paces the palisade, watching the yards below like weather.","The palisade wall is being raised another course, against nothing in particular."]'::jsonb, '{"east":"zone_nc_beacon","west":"zone_nc_highwater","north":"zone_nc_consulate","south":"zone_waste_oxide"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 6, -5, 0, 'Pa', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_meridianheights', 'Meridian Heights', 'The most expensive address in Coldwater, where the residences have no numbers because everyone who matters already knows where they are. The air is filtered twice and billed once.', 'safe', 0, 0, 1, '["A private lift disgorges someone important into a lobby that closes behind them.","The filtered air here smells faintly of nothing, aggressively maintained."]'::jsonb, '{"east":"zone_nc_glass","west":"zone_nc_concordat","south":"zone_nc_consulate"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 6, -7, 0, 'MH', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_tessellate', 'Tessellate Plaza', 'A plaza floored in a shifting tessellated pattern that is, allegedly, load-bearing corporate art. Standing on it too long gives you the distinct sense of being solved.', 'safe', 0, 0, 1, '["The tessellated floor seems to shift its pattern when you look away from it.","A tour group is told the plaza''s meaning and quietly declines to believe it."]'::jsonb, '{"west":"zone_nc_ivory","north":"zone_nc_bourse","south":"zone_nc_chancery"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 8, -6, 0, 'Te', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_concordat', 'The Concordat', 'The treaty hall where the corporations that own Coldwater sign the accords that carve it up, beneath a mural of a handshake so large and so insincere it loops in the mind for hours.', 'safe', 0, 0, 1, '["A delegation sweeps through the Concordat, flanked by lawyers like an honour guard.","The great handshake mural is being repainted, slightly, to reflect the new terms."]'::jsonb, '{"east":"zone_nc_meridianheights","west":"zone_bay_narrows","south":"zone_bay_basin"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 5, -7, 0, 'Co', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_highwater', 'Highwater Court', 'A residential court set at the district''s high-water mark, named for a flood that the owners have been assured, at great expense, will never reach them. The assurance is framed on a wall.', 'safe', 0, 0, 1, '["A resident of Highwater Court checks the bay''s level and, reassured, checks it again.","The framed flood-assurance gleams under a light that never goes off."]'::jsonb, '{"east":"zone_nc_palisade","west":"zone_bay_breakwater","north":"zone_bay_basin","south":"zone_nc_manifold"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 5, -5, 0, 'HC', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_glass', 'Glass Terrace', 'A terrace of mirror-glass towers that reflect only each other, so that from any point you see the district endlessly, and the grey city beyond it not at all.', 'safe', 0, 0, 1, '["Your reflection is handed off from one glass face to the next across the terrace.","A window-drone squeegees a pane that is already, impossibly, perfect."]'::jsonb, '{"east":"zone_nc_bourse","west":"zone_nc_meridianheights","south":"zone_nc_ivory"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 7, -7, 0, 'GT', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_chancery', 'Chancery Walk', 'The legal spine of the quarter, a colonnade of chanceries and notaries where the accords signed in the Concordat are rendered into language designed never to be read.', 'safe', 0, 0, 1, '["A notary seals a document with a stamp that costs more than a life down in the yards.","A clerk carries a contract down Chancery Walk with both hands, like a relic."]'::jsonb, '{"west":"zone_nc_beacon","north":"zone_nc_tessellate","south":"zone_corp_argent"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 8, -5, 0, 'Cy', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_ashreach', 'Ash Reach', 'An open reach of drifted ash that the wind sculpts into low dunes and then, bored, flattens again. Old machine-bones surface and submerge in it like the tide has teeth.', 'low', 0, 0, 0, '["The wind reshapes an ash dune and reveals the rusted ribs of a machine.","Ash lifts off the reach in a long grey sheet and settles a field over."]'::jsonb, '{"east":"zone_waste_rusthollow","west":"zone_waste_cinderflat","south":"zone_waste_tailings"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -6, -7, 0, 'AR', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_beacon', 'Beacon Row', 'A row crowned by an old harbour beacon, relit as a status symbol, that now warns ships away from a port that no longer wants them. The light sweeps the district all night.', 'safe', 0, 0, 1, '["The beacon sweeps its cold light across Beacon Row and moves on.","A resident closes their blinds against the beacon they paid extra to live beside."]'::jsonb, '{"east":"zone_nc_chancery","west":"zone_nc_palisade","north":"zone_nc_ivory","south":"zone_waste_downwind"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 7, -5, 0, 'Be', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_cinderflat', 'Cinder Flat', 'A flat of grey cinder that crunches underfoot like frozen ground, except it is not frozen — it is the cooled skin over heat that never fully left. In places the crust gives, and glows.', 'medium', 0, 1, 0, '["The cinder crust crunches under you and, somewhere, exhales a curl of heat.","A patch of the flat glows dull orange for a moment and then thinks better of it."]'::jsonb, '{"east":"zone_waste_ashreach","west":"zone_waste_slagverge","south":"zone_waste_clinkerrow"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -7, -7, 0, 'CF', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_up_vellum', 'Vellum Court', 'A pocket of would-be gentility at the water''s edge — planters, a dry ornamental basin, and frontages that face away from the docks as if embarrassed by them. A security checkpoint straddles The Steps here — a scanner arch and a pair of unimpressed guards vetting everyone who climbs up into the government quarter.', 'safe', 0, 0, 1, '["A planter mists itself and the ornamental basin, uselessly.","A resident hurries through, not looking at the water."]'::jsonb, '{"north":"zone_nc_datum","south":"zone_civ_steps"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"gov_checkpoint":true,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, -1, -4, 0, '⛩', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_tailings', 'The Tailings', 'The tailings pile of some long-dead operation, a grey-green mound of what was left after everything worth having was taken out. Whatever''s still in it is what nobody wanted, which is not the same as nothing.', 'low', 0, 0, 0, '["The tailings pile weeps a thin grey-green trickle from somewhere inside itself.","A scavenger works the tailings with a bent rake and does not acknowledge you."]'::jsonb, '{"east":"zone_waste_scald","west":"zone_waste_clinkerrow","north":"zone_waste_ashreach","south":"zone_waste_scrapmesa"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -6, -6, 0, 'TT', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_scrapmesa', 'Scrap Mesa', 'A flat-topped mesa built entirely of compacted scrap, layer on crushed layer, that the wastes have folded back into something almost geological. Salvagers mine it like a seam. It bites back.', 'low', 0, 0, 0, '["A slab calves off the scrap mesa''s flank and comes down in a slow avalanche of rust.","A salvager on the mesa''s rim waves once — warning or greeting, impossible to tell — and goes back to digging."]'::jsonb, '{"east":"zone_waste_leachfield","west":"zone_waste_ferrouswash","north":"zone_waste_tailings","south":"zone_waste_greymile"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -6, -5, 0, 'SM', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_vexhollow', 'Vex Hollow', 'A sunken hollow just inside the Redline where the air sits still and hums, and the few plants are the wrong colours and the wrong sizes. Things den here. They come out changed, and hungry, and toward you.', 'high', 0, 3, 0, '["The air in Vex Hollow hums at a pitch you feel in your fillings.","Something the wrong size for its shape shifts in a den at the hollow''s edge and fixes on you."]'::jsonb, '{"east":"zone_waste_brokenkiln","west":"zone_red_slaughterworks","north":"zone_waste_deadfurnace"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -8, -4, 0, 'VH', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_manifold', 'The Manifold', 'The junction where the diplomatic quarter''s clean marble finally meets the working city — the boat yard below, the boardrooms beside. A checkpoint here decides, quietly, who ascends.', 'safe', 0, 0, 1, '["A checkpoint at the Manifold turns someone back with a smile and a raised palm.","From the Manifold you can see the yards'' grime start, one clean step down."]'::jsonb, '{"east":"zone_waste_oxide","west":"zone_dock_boatyard","north":"zone_nc_highwater","south":"zone_corp_boardroom"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 5, -4, 0, 'Mf', '#eeeeee', '#8e8edd', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_freightworks', 'The Freightworks', 'The mechanised heart of the Yards, a shed of conveyors and sorting arms that route freight by a logic no living person fully understands and nobody dares reboot.', 'low', 0, 0, 1, '["A sorting arm swings a crate down a chute chosen by nothing you can see.","The conveyors change direction all at once, for reasons, and change back."]'::jsonb, '{"east":"zone_yard_gantry","west":"zone_yard_container","north":"zone_waste_downwind","south":"zone_yard_pallet"}'::jsonb, '{"artery":["Quay Road"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 7, -3, 0, 'FW', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_greymile', 'The Grey Mile', 'The featureless grey mile that everyone crosses and nobody remembers, a long flat nothing of ash and grit between the city''s edge and the killing ground beyond. Its only landmark is that it has none.', 'low', 0, 0, 0, '["The grey mile stretches ahead and behind, identical in both directions.","A bootprint in the grit ahead of you fills slowly with drifting ash and is gone."]'::jsonb, '{"east":"zone_waste_sootbank","west":"zone_waste_brokenkiln","north":"zone_waste_scrapmesa"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -6, -4, 0, 'GM', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_clinkerrow', 'Clinker Row', 'A row of heaped clinker — the hard, glassy dregs raked from furnaces that died before anyone here was born — stacked into a wall that someone, at some point, decided to hide behind.', 'medium', 0, 1, 0, '["A heap of clinker shifts and rattles down its own slope with a sound like held breath.","Behind the clinker wall, briefly, a shape ducks out of sight."]'::jsonb, '{"east":"zone_waste_tailings","west":"zone_red_meltline","north":"zone_waste_cinderflat","south":"zone_waste_ferrouswash"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -7, -6, 0, 'CR', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_fumealley', 'Fume Alley', 'A narrow alley between spoil-banks where the Slagworks'' fumes pool when the wind drops, thick enough to lean on and yellow enough to taste. Nobody lingers in Fume Alley by choice, and few by accident survive it.', 'medium', 0, 1, 0, '["Yellow fume pools in the alley and stirs, reluctantly, as you pass through it.","The air in Fume Alley thickens; your eyes water and the far end swims and vanishes."]'::jsonb, '{"west":"zone_waste_cokeyard","north":"zone_red_marrowrow","south":"zone_slag_catalyst"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -9, -2, 0, 'FA', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_deadfurnace', 'Dead Furnace', 'The husk of a smelting furnace big enough to stand inside, cold now for decades, its throat choked with debris. People shelter in its belly and swear the walls are still, very faintly, warm.', 'medium', 0, 1, 0, '["The dead furnace''s iron throat funnels the wind into a low, mournful note.","Someone''s cold camp sits in the furnace''s belly; the ashes are still warm, but they are gone."]'::jsonb, '{"east":"zone_waste_ferrouswash","west":"zone_red_cullrow","north":"zone_red_meltline","south":"zone_red_vexhollow"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -8, -5, 0, 'DF', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_ferrouswash', 'Ferrous Wash', 'A wash where iron-rich runoff braids across the flat in rust-red rivulets, staining a delta that spreads a little wider each year. Drinking it kills you slowly; standing in it, only slightly faster.', 'medium', 0, 1, 0, '["A ferrous rivulet finds a new path across the wash and stains it in seconds.","The rust-red delta glistens, and the air above it tastes of blood you didn''t shed."]'::jsonb, '{"east":"zone_waste_scrapmesa","west":"zone_waste_deadfurnace","north":"zone_waste_clinkerrow","south":"zone_waste_brokenkiln"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -7, -5, 0, 'FW', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_dreadfurnace', 'Dread Furnace', 'The last hard step of the neck before it meets the Reclaimer below — the cold hulk of a furnace so large it has its own weather inside, a slow red haze that never clears. What dens in it came down from the Redline, and stayed.', 'high', 0, 3, 0, '["The dread furnace breathes its red haze out through a hundred cracks and draws it back in.","Deep in the furnace''s throat, far up in the dark, something shifts its weight and settles."]'::jsonb, '{"east":"zone_slag_flarestack","north":"zone_red_flensing","south":"zone_slag_reclaimer"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -11, -1, 0, 'DF', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_cokeyard', 'Coke Yard', 'A yard heaped with spent coke, the grey-black char raked out of the Slagworks'' furnaces and dumped uphill to cool. It never fully does; deep in the piles a red heart still glows, and breathes.', 'medium', 0, 1, 0, '["A coke pile settles with a soft crunch and exhales a breath of sulphurous heat.","Deep in the char a red glow pulses once, like something down there is still awake."]'::jsonb, '{"east":"zone_waste_fumealley","west":"zone_red_flensing","north":"zone_waste_chargully","south":"zone_slag_flarestack"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -10, -2, 0, 'CY', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_blight', 'The Blight', 'A blighted flat above the Slagworks Gate where nothing that tries to grow gets past a hand''s height before it blackens and gives up. The salvage here is good; the ground insists you earn it.', 'low', 0, 1, 0, '["A blackened stalk in the Blight crumbles to soot at the touch of the wind.","Something worth having glints in the dead ground, and the dead ground does not want to give it up."]'::jsonb, '{"east":"zone_waste_cindersteps","south":"zone_waste_sinter"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -8, -2, 0, 'BL', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_flensing', 'The Flensing', 'The neck of the Redline — a single hard column of poisoned ground threading down out of the killing floor in the north toward the Slagworks below. It earned its name honestly; things that come through it arrive short of skin.', 'high', 0, 3, 0, '["The wind funnels down the Flensing''s neck, and it carries a fine red grit that stings where it lands.","Something drags itself down the neck from the north, leaving a wet trail, and does not slow when it sees you."]'::jsonb, '{"east":"zone_waste_cokeyard","north":"zone_red_gnash","south":"zone_red_dreadfurnace"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -11, -2, 0, 'FL', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_feralyard', 'Feral Yard', 'A yard where the packs den — the fast, four-legged, wrong-eyed things the Redline makes of what were once dogs, and of what were once other things. They hunt in the open here because here, at last, they are the ones being avoided.', 'lethal', 0, 4, 0, '["Something paces the Feral Yard''s perimeter just out of sight, patient, unhurried, closing.","A chorus of wrong-pitched howls goes up across the yard and is answered from every side."]'::jsonb, '{"east":"zone_red_screaminglot","north":"zone_red_mutiewarren","south":"zone_red_bonepit"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -11, -5, 0, 'FY', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_radsink', 'The Rad Sink', 'The lowest point of the Redline, where every poison the frontier produces drains and pools and concentrates into a sump so hot the air above it shimmers. Nothing lives in the Rad Sink. Things merely pass through it, and are lessened.', 'lethal', 0, 5, 0, '["The air over the Rad Sink shimmers and warps the ruin behind it into something molten.","Your counter, if you carry one, stops ticking and simply screams a single unbroken note."]'::jsonb, '{"east":"zone_red_hazardnine","west":"zone_red_mutiewarren","north":"zone_red_glowfield","south":"zone_red_screaminglot"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -10, -6, 0, 'RS', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_killingfloor', 'The Killing Floor', 'The killing floor — a flat, open expanse swept clear of everything but bones and the things that made them, where whatever apex the Redline has bred holds court over a court of the dead. People come here to prove something. Their proof is usually their absence.', 'lethal', 0, 5, 0, '["The killing floor is silent in the way a held breath is silent, waiting to be let out.","Bones crunch somewhere out on the floor under a weight far larger than yours, and stop."]'::jsonb, '{"east":"zone_waste_slagverge","west":"zone_red_glowfield","south":"zone_red_hazardnine"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -9, -7, 0, 'KF', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_mutiewarren', 'Mutie Warren', 'A warren of tunnels and burrows clawed into the poisoned ground by generations of the changed, who breed here in the dark faster than anything can cull them. To enter the Warren is to be outnumbered by definition and outmatched by the second turning.', 'lethal', 0, 4, 0, '["A pale, wrong-jointed shape watches from a burrow-mouth and then draws silently back in.","The ground underfoot is undermined by the Warren; it gives a little, and something below resents it."]'::jsonb, '{"east":"zone_red_radsink","north":"zone_red_redline","south":"zone_red_feralyard"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -11, -6, 0, 'MW', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_hazardnine', 'Hazard Nine', 'A containment zone from the old world, numbered nine, breached decades ago and never resealed because no one who went to reseal it came back. The signage still insists, politely and in three languages, that you should not be reading it.', 'lethal', 0, 4, 0, '["A breached containment door hangs open on Hazard Nine, and the dark inside it breathes out.","Faded trefoil signs march away into the ruin, each one more emphatic and less obeyed than the last."]'::jsonb, '{"east":"zone_red_meltline","west":"zone_red_radsink","north":"zone_red_killingfloor","south":"zone_red_cullrow"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -9, -6, 0, 'HN', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_glowfield', 'Glowfield', 'A field where the ground gives off a sick green-white light strong enough to read by, pooling in the low places like luminous water. The salvage here is fabulous and the price for taking it is measured in the years it quietly subtracts.', 'lethal', 0, 5, 0, '["The glowfield casts your shadow in three directions at once, all of them wrong.","A pool of luminance shifts as something moves through it below the surface, unseen, unhurried."]'::jsonb, '{"east":"zone_red_killingfloor","west":"zone_red_redline","south":"zone_red_radsink"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -10, -7, 0, 'GL', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_drossworks', 'The Drossworks', 'The dross-works, where the skimmings off molten metal were once cast into pigs and stacked to sell. The stacks are still here, grown over with rust, a maze of worthless iron that squatters and worse have made a warren of.', 'low', 0, 0, 0, '["A stack of dross pigs shifts in the maze and someone, unseen, curses it quietly.","The rusted iron of the Drossworks funnels the wind into a low, resentful hum."]'::jsonb, '{"east":"zone_waste_ferro","west":"zone_waste_ashencut","south":"zone_waste_hopper"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -8, 2, 0, 'DK', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_gnash', 'The Gnash', 'The southern jaw of the Redline, where the killing floor narrows into the neck that drops toward the Slagworks. Everything the core spits out comes through the Gnash on its way down, and the Gnash takes its toll on the way past.', 'lethal', 0, 4, 0, '["The Gnash funnels a cold, ticking wind down the neck toward the Slagworks far below.","Something comes down through the Gnash from the killing floor above, and does not stop for you."]'::jsonb, '{"east":"zone_waste_chargully","north":"zone_red_bonepit","south":"zone_red_flensing"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -11, -3, 0, 'GN', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_slaughterworks', 'The Slaughterworks', 'An old automated abattoir whose machines never received the order to stop and so, powered by something that will not die, still run — hooks and blades and conveyors cycling endlessly through an empty line that is not, if you listen, always empty.', 'lethal', 0, 5, 0, '["A meat-hook conveyor cycles past overhead, empty, and then not empty, and then empty again.","The Slaughterworks'' blades reset with a wet mechanical sigh, ready for a line that never ends."]'::jsonb, '{"east":"zone_red_vexhollow","west":"zone_red_rictusalley","north":"zone_red_cullrow","south":"zone_red_marrowrow"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -9, -4, 0, 'SW', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_slagverge', 'Slag Verge', 'The western verge of the wastes, where the ground goes from merely poisoned to something worse a few strides further on. A hand-painted sign, riddled and unreadable, still manages to communicate: no further.', 'medium', 0, 1, 0, '["A dry wind off the west carries a taste of hot metal and rot.","The unreadable warning sign creaks on its post and points, more or less, at nothing good."]'::jsonb, '{"east":"zone_waste_cinderflat","west":"zone_red_killingfloor","south":"zone_red_meltline"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -8, -7, 0, 'SV', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_chargully', 'Char Gully', 'A charred gully at the very foot of the Redline, the last scrap of merely-poisoned ground before the lethal core proper. Scavengers work its edges for what the core discards, one eye always uphill, on the red glow that never quite goes out.', 'medium', 0, 1, 0, '["Char crunches underfoot in the gully, and uphill the red glow of the core pulses, slow.","A scavenger works the gully''s edge with one eye uphill and bolts the moment you appear."]'::jsonb, '{"east":"zone_red_marrowrow","west":"zone_red_gnash","north":"zone_red_rictusalley","south":"zone_waste_cokeyard"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -10, -3, 0, 'CG', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_bonepit', 'The Bonepit', 'A pit into which the Redline''s dead have been dragged, or have dragged themselves, for longer than anyone remembers — a slow midden of bone gone grey and soft. Things nest in the Bonepit that find the bones convenient, and the visitors more so.', 'lethal', 0, 4, 0, '["The bone-midden shifts and settles with a dry clatter that goes on too long to be settling.","Something rises out of the Bonepit wearing the bones it nested in, and turns its head toward you."]'::jsonb, '{"east":"zone_red_rictusalley","north":"zone_red_feralyard","south":"zone_red_gnash"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -11, -4, 0, 'BP', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_redline', 'The Redline', 'The Redline itself, the top-left corner of the known world, where a line of rusted stakes and warning-skulls marks the place past which the maps simply stop and the living are simply advised not to. Everything here glows faintly, including, after a while, you.', 'lethal', 0, 5, 0, '["A warning-skull on its stake turns its empty sockets toward you as the wind shifts it.","The air itself has a red cast here, and your skin prickles with a heat that has no source."]'::jsonb, '{"east":"zone_red_glowfield","south":"zone_red_mutiewarren"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -11, -7, 0, 'RL', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_railhead', 'The Railhead', 'The Yards'' rail terminus, where a single working locomotive shunts flatcars of scrap and cargo out to wherever rails still run. The yardmaster keeps his office in a dead signal box here.', 'low', 0, 0, 1, '["The shunting loco couples up with a crash and a hiss of ancient brakes.","A flatcar of scrap rolls past, loaded past any sane limit, and slows to a stop."]'::jsonb, '{"north":"zone_yard_forklift","south":"zone_yard_bulk"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 8, 2, 0, 'RH', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_battery', 'Battery Square', 'The civic heart of the district, such as it is — a paved square built around a dry fountain someone has repurposed as a communal firepit. A grocery holds down one side, a police precinct scowls from another, and a public notice pillar wears a thick scab of flyers: rooms to let, people gone missing, curfews rescinded and reinstated. It is, by local standards, safe. The precinct''s floodlights see to that.', 'safe', 0, 0, 1, '["The precinct floodlights sweep the square in a slow, bored arc.","Someone feeds a broken chair to the fountain fire and warms their hands.","A public-address speaker crackles: \"CITIZENS ARE REMINDED—\" then gives up.","A flyer tears loose from the notice pillar and cartwheels across the paving."]'::jsonb, '{"in":"zone_mq_grocery","east":"zone_mq_precinct","west":"zone_mq_marquee","north":"zone_mq_chrome_court","south":"zone_mq_overpass"}'::jsonb, '{"artery":["Grand Avenue"],"scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 4, 0, 0, 'BS', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_basin', 'The Reflecting Basin', 'A formal basin of still bay water set into the diplomatic quarter as a gesture toward serenity. The gesture is undercut by the things that occasionally surface in it.', 'low', 0, 0, 1, '["The reflecting basin holds the towers upside-down, perfectly, until it doesn''t.","A ripple crosses the still basin, from the middle, where nothing dropped."]'::jsonb, '{"east":"zone_nc_consulate","west":"zone_bay_floes","north":"zone_nc_concordat","south":"zone_nc_highwater"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 5, -6, 0, 'Bn', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slag_yard', 'The Cracking Yard', 'The heart of the works: a maze of pipework and catwalks around the base of the great cracking columns, everything furred with rust and dripping something that eats through your soles if you stand too long. Salvage crews got the easy metal years ago. What''s left is buried, or guarded, or both.', 'low', 1, 0, 0, '["A pipe fails somewhere overhead and vents a long, hoarse sigh of stale gas.","Your boots stick, then peel free of the tar-slicked decking with a wet tear."]'::jsonb, '{"east":"zone_slag_gate","west":"zone_slag_rail","north":"zone_slag_catalyst","south":"zone_slag_sump"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -9, 0, 0, 'CY', '#111111', '#e9b282', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_pitnine', 'Pit Nine', 'A collapsed pit, numbered nine by someone who counted eight others just like it, that goes down into the dark further than a dropped stone will report back on. Its rim is the western edge of the walkable wastes.', 'medium', 0, 1, 0, '["A stone kicked into Pit Nine falls a long time and never lands, or lands too far to hear.","Cold, still air breathes up out of Pit Nine, smelling of deep earth and something metallic."]'::jsonb, '{"east":"zone_waste_overburden"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -8, -3, 0, 'PN', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slums', 'The Sprawl', 'Dense, vertical, and loud. Pre-Handoff apartment complexes have been stacked with improvised floors. The streets below are narrow tunnels of laundry lines and extension cords.', 'medium', 1, 0, 1, '["Something crashes several floors above. Then laughter.","A wall-mounted screen plays a looping corporate training video on conflict resolution."]'::jsonb, '{"down":"zone_tunnels","east":"zone_deep_scab","north":"zone_city_south","south":"zone_deep_maw"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, 0, 2, 0, 'SP', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slag_drums', 'The Drum Yard', 'Ten thousand steel drums, stacked four high and rotting from the bottom up, their contents long since wept into the soil. Most are empty. A few are not, and the labels that would tell you which are gone to rust-lace. A scavenger''s jackpot with a coin-flip attached.', 'low', 1, 0, 0, '["A drum somewhere in the stacks lets go and slumps with a long, corroded sigh.","Rusty runoff wicks up the side of your boot in a thin brown line."]'::jsonb, '{"east":"zone_slag_sump","west":"zone_waste_coldslag","north":"zone_slag_rail","south":"zone_waste_slagbar"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -10, 1, 0, 'DY', '#111111', '#e9b282', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meat_slaughter', 'Slaughter Lane', 'The killing lane of the meat market, gutters running to a central drain, hooks swinging empty between the stalls. The butchers here work fast and ask nothing.', 'medium', 1, 0, 1, '["A hook swings empty down the lane, then is loaded and swings heavy.","A butcher hoses the gutter toward the drain; it runs, briefly, red."]'::jsonb, '{"west":"zone_meat_ashpit","north":"zone_mq_cage","south":"zone_meat_carrion"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 5, 2, 0, 'Sl', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_deep_waste', 'The Falloff', 'This is where the city simply gives up. The last blocks of Old Coldwater sag into their own flooded basements, streets dead-ending in dust, rebar, and drifts of shattered glass. Nobody has lived out here in a very long time — you can read it in every caved roofline and every door left standing open on nothing.', 'medium', 1, 0, 0, '["A section of roofing lets go somewhere nearby and comes down with a long, tired crash.","Wind moves through a hundred empty window-frames at once, one low toneless moan.","Dust drifts across the dead street in slow, aimless curls.","Deep in a collapsed building, something shifts its weight and settles again."]'::jsonb, '{"east":"zone_badland_sw_outer","west":"zone_waste_grit","south":"zone_deep_tarpit"}'::jsonb, '{"lawless":true,"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"BL","building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -3, 1, 0, 'BL', '#111111', '#e69e73', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_meltline', 'The Meltline', 'The line where the wastes end and the Redline begins, marked by a slumped rail of fused slag that runs off north and south as far as the haze allows. On this side, the counter ticks. On that side, it screams.', 'high', 0, 3, 0, '["Your teeth ache faintly, the way they do near the Meltline, and you understand it as a warning.","Beyond the fused-slag rail the ground has a wrong, glassy sheen, and something moves on it."]'::jsonb, '{"east":"zone_waste_clinkerrow","west":"zone_red_hazardnine","north":"zone_waste_slagverge","south":"zone_waste_deadfurnace"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -8, -6, 0, 'TM', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_sinter', 'The Sinter', 'The sinter beds beside the Slagworks Gate, where fines were once fused into clinker in long shallow trays now cracked and cold. Salvagers work the trays for the metal the process left behind, and the Gate watches them do it.', 'low', 0, 1, 0, '["A sinter tray cracks a little wider under its own dead weight.","A Slagworks hand leans in the Gate''s shadow and watches you work the trays, and says nothing."]'::jsonb, '{"north":"zone_waste_blight","south":"zone_slag_gate"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -8, -1, 0, 'SI', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_ministry', 'Ministry Row', 'A colonnade of ministries that administer nothing, their brass plates polished daily by staff who have not been paid in a decade and turn up anyway. The doors are always open onto empty marble halls.', 'safe', 0, 0, 1, '["A clerk crosses Ministry Row with a stack of forms and a look of terrible purpose.","A ministry door stands open on a hall of empty desks, all of them expectant."]'::jsonb, '{"east":"zone_gov_assembly","south":"zone_gov_registry"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -4, -7, 0, 'MN', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_tarseep', 'Tar Seep', 'A slow black seep wells up through the ash here, patient and bottomless. Things that wander in do not wander out; the surface just closes over with an oily wink.', 'medium', 0, 0, 1, '["A bubble the size of a skull rises through the tar and pops, releasing a sigh.","Something white and half-dissolved surfaces in the seep, then is drawn back under."]'::jsonb, '{"east":"zone_waste_molten","west":"zone_waste_overburden"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -6, -3, 0, 'TS', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_reek', 'The Reek', 'The reek is exactly that — the low ground below the Slagworks where every runoff and effluent the works produces finally collects and stands and stinks. The Effluent Sump drains here. You smell the Reek long before you reach it.', 'low', 0, 1, 0, '["The Reek shifts its skin of scum and lets up a bubble that pops with a sigh.","Runoff trickles in from the Sump above and the standing filth accepts it without a ripple."]'::jsonb, '{"east":"zone_waste_ashenverge","north":"zone_slag_gate"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -8, 1, 0, 'RE', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_slagbar', 'Slag Bar', 'A long bar of fused slag thrown up like a levee across the deep wastes, high enough to climb and walk, a road for those who know it. From its spine you can see the whole grey sweep of the frontier, which is not a comfort.', 'low', 0, 0, 0, '["From the slag bar''s spine the wastes stretch grey and featureless to every horizon.","A figure walks the far end of the slag bar, silhouetted, and is gone behind the ridge."]'::jsonb, '{"east":"zone_waste_ashencut","west":"zone_waste_culvert","north":"zone_slag_drums","south":"zone_waste_gantry"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -10, 2, 0, 'SB', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_rimeflat', 'Rime Flat', 'The southwestern corner of the walkable world, a flat where a pale chemical rime crusts the ground like frost that never melts. It marks the edge; beyond it the map, and the wastes, and the will to go on, all give out.', 'low', 0, 0, 0, '["The chemical rime crunches like frost and leaves a pale burn where it touches skin.","At the flat''s edge the ground simply stops mattering, grey into grey into nothing."]'::jsonb, '{"east":"zone_waste_gantry","north":"zone_waste_culvert"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -11, 3, 0, 'RF', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_dustreach', 'Dust Reach', 'The last reach before the built wastes give out entirely, a plain of fine grey dust that the wind lifts into standing walls and marches across the frontier. Crossing it, you are always inside weather, and the weather is made of this place.', 'low', 0, 0, 0, '["A wall of grey dust marches across the reach and swallows the horizon whole.","The dust settles for a moment and shows a trail of prints leading west, and no one on it."]'::jsonb, '{"east":"zone_waste_hopper","west":"zone_waste_gantry","north":"zone_waste_ashencut"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -9, 3, 0, 'DR', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_culvert', 'The Culvert', 'A great cracked concrete culvert that once carried the works'' floodwater away and now carries nothing but wind and the occasional person with nowhere better to shelter. Its mouth gapes westward, into the dark under the wastes.', 'low', 0, 0, 0, '["Wind moans down the length of the culvert and dies somewhere in its western dark.","A shape shelters deep in the culvert''s mouth and pulls back further as you approach."]'::jsonb, '{"east":"zone_waste_slagbar","north":"zone_waste_coldslag","south":"zone_waste_rimeflat"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -11, 2, 0, 'CV', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_ashencut', 'Ashen Cut', 'A cutting sliced through the spoil where a rail line once ran out to the Slagworks and was torn up for scrap decades back. The cut is sheltered from the wind, which is why the things that shelter here resent visitors.', 'low', 0, 0, 0, '["The ashen cut holds still air and the ghost of creosote from a railway long gone.","Bootprints and other prints share the floor of the cut; some of the others are not shaped right."]'::jsonb, '{"east":"zone_waste_drossworks","west":"zone_waste_slagbar","north":"zone_slag_sump","south":"zone_waste_dustreach"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -9, 2, 0, 'AC', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_gantry', 'The Gantry', 'The skeleton of a loading gantry that once straddled the torn-up rail, now a rusted arch over nothing, straddling the deep wastes like a monument to the work that killed this place. Scavengers use its height to spot trouble coming.', 'low', 0, 0, 0, '["The gantry''s rusted arch groans in the wind and drops a rain of scale.","A lookout perched high on the gantry whistles a warning down and points, west."]'::jsonb, '{"east":"zone_waste_dustreach","west":"zone_waste_rimeflat","north":"zone_waste_slagbar"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -10, 3, 0, 'GA', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_screaminglot', 'The Screaming Lot', 'A lot where a trick of the ruined structures turns the wind into a sound exactly like a great many people screaming, all the time, forever. Newcomers run toward it to help. There is no one to help. There is only the lot, and the wind, and what the sound draws in.', 'lethal', 0, 4, 0, '["The Screaming Lot rises to a crescendo of voices that are only ever the wind, you are almost sure.","For one moment the screaming stops dead, which is far, far worse, and then it starts again."]'::jsonb, '{"east":"zone_red_cullrow","west":"zone_red_feralyard","north":"zone_red_radsink","south":"zone_red_rictusalley"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783307630', 'map_world', NULL, -10, -5, 0, 'SL', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_coldslag', 'Cold Slag', 'A field of slag gone properly cold at last, the western frontier of walkable ground below the neck. Past it the wastes give way to the Redline''s lower reach, and only the desperate and the changed go on.', 'low', 0, 0, 0, '["Cold slag crunches underfoot, dead and grey and finally, entirely done being hot.","At the field''s western edge the ground takes on a wrong sheen, and you feel watched from it."]'::jsonb, '{"east":"zone_slag_drums","north":"zone_slag_reclaimer","south":"zone_waste_culvert"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase11-build', '1783301927', 'map_world', NULL, -11, 1, 0, 'CS', '#eeeeee', '#bfa06b', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_dock_slip', 'Smuggler''s Slip', 'A crooked finger-pier the harbourmaster''s charts pretend doesn''t exist. Boats come in dark and leave lighter. Ask no questions; you won''t like being answered.', 'medium', 1, 0, 1, '["A shuttered boat rocks at the slip, its cargo very deliberately covered.","Someone at the slip''s end watches you the entire time, and says nothing."]'::jsonb, '{"in":"zone_hangar_dock_slip","east":"zone_corp_boardroom","west":"zone_dock_fishmarket","north":"zone_dock_boatyard"}'::jsonb, '{"artery":["Quay Road"],"airfield_id":"af_bay","is_building":false,"is_interior":false,"is_apartment":false,"airfield_fuel":true,"airfield_name":"Smuggler''s Slip Pad","building_name":"","building_type":null,"airfield_fuels":["avgas","biofuel"],"airfield_dealer":false,"airfield_charter":true,"airfield_lawless":true,"scavenging_table_id":"scav_roadside_junk","hangar_interior_zone":"zone_hangar_dock_slip"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 4, -3, 0, 'SS', '#111111', '#50e0d5', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_city_north', 'Threshold Plaza North', 'A cracked concrete plaza ringed by dead streetlights still standing at attention. This is the northern gate into Coldwater proper — the LED departure boards here flicker through routes that no longer run anywhere.', 'safe', 0, 0, 1, '["A drone hums overhead, chassis stenciled with a faded corporate logo.","The departure board flickers: COLDWATER → DENVER → [SIGNAL LOST]."]'::jsonb, '{"north":"zone_ext_1782953094650","south":"zone_threshold"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"airspace_restricted":true,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, NULL, '1783301927', 'map_world', NULL, 0, -1, 0, 'TN', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_city_ne', 'Custodian Row', 'Corporate spires, mostly empty, partially maintained by Custodians who still believe someone is watching the quarterly numbers.', 'safe', 0, 0, 1, '["A Custodian in ill-fitting corporate attire hands out pamphlets nobody reads.","An elevator chimes on a floor that no longer exists."]'::jsonb, '{"north":"zone_up_gate"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"airspace_restricted":true,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, NULL, '1783301927', 'map_world', NULL, 1, -1, 0, 'CR', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meridian', 'Halcyon Walk', 'A stretch of cracked pavement the city has forgotten to condemn. Water-stained precast towers lean over it on both sides, their ground floors a monotony of steel-framed glass — most of it dark, a few doors still lit from within. The Meridian''s lobby throws a wedge of sick fluorescent light across the walk here, doorman long gone, intercom panel hanging by its wires. Somewhere overhead a window unit drips onto its sill in a slow, patient rhythm.', 'safe', 0, 0, 1, '[]'::jsonb, '{"in":"zone_meridian_lobby","north":"zone_up_approach"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":"zone_city_ne","airspace_restricted":true,"scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 2, -1, 0, NULL, '#eeeeee', '#42c96a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_marquee', 'The Marquee', 'The Marquee was a theater district before the Collapse and never entirely stopped pretending. A dead cinema marquee juts over the intersection, its plastic letters half-looted so the last feature reads simply NO ONE. Rain-slick asphalt throws back the pink and cyan of a dozen bar signs still drawing power from god-knows-where. Foot traffic here is the closest thing the basin has to a nightlife, and everyone walks like they''re being watched, because they are.', 'safe', 0, 0, 1, '["A bar door swings open somewhere, leaking bass and warm air, then thuds shut.","The dead marquee buzzes and drops another letter onto the pavement.","A cluster of people laugh too loudly and move on fast.","Neon reflection ripples across a puddle as a bike whines past."]'::jsonb, '{"in":"zone_mq_pigeon_bar","east":"zone_mq_battery","west":"zone_velk_exterior","north":"zone_mq_cathode"}'::jsonb, '{"artery":["Grand Avenue","Cathode Street"],"scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 3, 0, 0, 'MQ', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_ember', 'Ember Alley', 'Where the Marquee''s neon can''t quite reach, the district goes to seed. Ember Alley is a slot of a street lit orange by a single working sodium lamp and the coal-glow of cigarettes in doorways. A dive bar exhales stale beer and old grease into the cold. The walls wear decades of paste-over posters, and somewhere behind them, the brick. People here mind their own business with a dedication that is itself a kind of threat.', 'low', 0, 0, 1, '["Glass breaks in the alley behind you, followed by a tired curse.","The sodium lamp gutters, drowning the street in ember-red, then steadies.","Someone is being sick, thoroughly, out of sight.","A cat the size of a raccoon regards you from a dumpster lid and does not blink."]'::jsonb, '{"in":"zone_mq_sump_bar","south":"zone_weapons_exterior"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 3, 1, 0, 'EM', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_overpass', 'The Overpass', 'A stub of collapsed elevated roadway roofs this block in permanent shadow, its underside a cathedral of rebar and pigeon filth. Someone strung work-lights along the girders and called it commerce. An electronics stall glows under the deck; a stairwell drops into a basement lit by a single sign. Water finds its way down through the concrete no matter the weather, ticking into puddles that never dry.', 'low', 0, 0, 1, '["Water ticks down from the overpass and finds the back of your collar.","Pigeons erupt off a girder in a slapping panic, then resettle.","A work-light swings on its cord, throwing the shadows into motion.","Something heavy passes on the road above; the whole deck shivers dust."]'::jsonb, '{"in":"zone_mq_amp_shop","east":"zone_mq_cage","north":"zone_mq_battery","south":"zone_meat_ashpit"}'::jsonb, '{"scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 4, 1, 0, 'OP', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_civ_commons', 'The Commons', 'A cracked plaza the city forgot to demolish. A breadline shuffles past a dead fountain, and a hand-painted banner insists that WE ARE ALL SHAREHOLDERS.', 'safe', 0, 0, 1, '["The breadline shuffles forward a step for reasons no one can identify.","A pigeon lands on the dead fountain''s rim and judges the crowd."]'::jsonb, '{"down":"zone_under_commons","east":"zone_civ_ledger","west":"zone_waste_windrow"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase2-build', '1783301927', 'map_world', NULL, -3, -3, 0, 'CO', '#111111', '#7fda9a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_rusthollow', 'Rust Hollow', 'A shallow hollow where rainwater once pooled and left everything it touched the deep orange-brown of old blood. Nothing drains here; it just sits, and stains, and waits.', 'low', 0, 0, 0, '["Standing water in the hollow holds the grey sky the colour of rust.","A dropped bolt in the hollow is already, impossibly, half-eaten by rust."]'::jsonb, '{"west":"zone_waste_ashreach","south":"zone_waste_scald"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -5, -7, 0, 'RH', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_city_south', 'The Sprawl Gate', 'Where the dense vertical Sprawl tapers into the rest of the city. Laundry lines and extension cords crisscross overhead like a second sky.', 'safe', 0, 0, 1, '["Something crashes several floors above. Then laughter.","A wall screen loops a corporate conflict-resolution training video, forever."]'::jsonb, '{"west":"zone_city_sw","north":"zone_threshold","south":"zone_slums"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, 0, 1, 0, 'SG', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_sidings', 'The Sidings', 'A tangle of rail sidings where flatcars wait, loaded and forgotten, for engines that are always about to come. The scavengers know the timetable better than the railway does.', 'low', 0, 0, 1, '["A flatcar creaks as its load settles a little further toward salvage.","A picker melts between the sidings, one eye on the far signal box."]'::jsonb, '{"north":"zone_yard_container","south":"zone_yard_boxcar"}'::jsonb, '{"artery":["Boxcar Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase8-build', '1783301927', 'map_world', NULL, 6, -2, 0, 'Sd', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_up_approach', 'Spire Approach', 'A manicured processional toward the Halcyon spire — reflecting pools, engineered calm, and signage in a font that costs more than you do.', 'safe', 0, 0, 1, '["A groundskeeper drone skims a leaf from a pool that has never held a leaf.","The signage subtly rearranges to face whoever is richest."]'::jsonb, '{"north":"zone_dock_quays","south":"zone_meridian"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 2, -2, 0, 'SA', '#eeeeee', '#42c96a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_dock_coldstore', 'Cold Storage', 'A refrigerated warehouse still running on stolen power, its doors breathing fog. Inside, racks of catch and less legal cargo hang in the cold dark.', 'low', 0, 0, 1, '["A cold-store door sighs open, exhaling fog, and no one comes out.","Something shifts on a hook deeper in the cold, then stills."]'::jsonb, '{"north":"zone_bay_sound","south":"zone_dock_wharf"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 1, -4, 0, 'CS', '#111111', '#50e0d5', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cage', 'Tin Lane', 'A dogleg of a service lane roofed in corrugated tin that drums like gunfire whenever it rains, which is always. Every ground-floor window wears its own cage of rebar and welded mesh; commerce here is conducted through slots. The Cage anchors the lane — steel screen floor to ceiling, a clerk somewhere behind it, a shotgun somewhere behind the clerk. A hand-lettered sign promises OPEN and, unusually, means it.', 'low', 0, 0, 1, '[]'::jsonb, '{"in":"zone_mq_cage_shop","west":"zone_mq_overpass","north":"zone_mq_precinct","south":"zone_meat_slaughter"}'::jsonb, '{"is_building":true,"is_interior":false,"is_apartment":false,"building_name":"The Cage","building_type":"shop","world_exit_zone":"zone_mq_overpass","scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 5, 1, 0, 'CG', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_transfer', 'The Transfer Dock', 'The main transfer dock, where cargo changes hands, trucks, and legality. Forklifts weave between pallet-mountains with a recklessness that is somehow never quite fatal.', 'low', 0, 0, 1, '["A forklift threads a gap it has no business fitting through, horn blaring.","A pallet-mountain shifts, sheds a crate, and is restacked before it lands."]'::jsonb, '{"north":"zone_yard_dray","south":"zone_yard_tare"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 7, 1, 0, 'TD', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_fog', 'The Fog Bank', 'A permanent bank of cold fog sits over this stretch of the bay, thick enough to lose a boat in. Sound comes strangely here — near things far, far things near.', 'low', 0, 0, 1, '["A foghorn sounds, impossibly close, from a boat you cannot see.","The fog closes behind you as you move, sealing the way back to a rumour."]'::jsonb, '{"east":"zone_bay_breakwater","west":"zone_bay_open","north":"zone_bay_deep","south":"zone_bay_barges"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 3, -5, 0, 'FB', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_shallows', 'The Shallows', 'A boardwalk on rotting pilings runs out over the shallows, where the bay goes brown and thick with runoff. You can see shapes moving under the skin of the water.', 'low', 0, 0, 1, '["Something breaks the surface of the shallows, then is gone.","The boardwalk gives a soft rotten groan and holds. Just."]'::jsonb, '{"north":"zone_bay_open"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase3-build', '1783301927', 'map_world', NULL, 2, -4, 0, 'SH', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_narrows', 'The Narrows', 'Where the breakwater''s arm nearly meets the far spit, the bay pinches to a churning narrows. The current here has taken stronger swimmers than you and shows no signs of being full.', 'medium', 0, 0, 1, '["The narrows churns white against the last blocks of the breakwater.","The current tugs at the pontoon and, briefly, at you."]'::jsonb, '{"east":"zone_nc_concordat","west":"zone_bay_reach","south":"zone_bay_floes"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 4, -7, 0, 'NR', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_mq_cathode', 'Cathode Row', 'A narrow run of frontage where every third storefront sells some flavor of skin, chrome, or forgetting. The signage competes for attention until it all blurs into one continuous migraine of light. A tattoo parlor, two shuttered clinics, and a club with a cherry blinking over the door. The gutter runs with meltwater and the confetti of a hundred torn wristbands.', 'safe', 0, 0, 1, '["A busker''s amp cuts out mid-note and doesn''t come back.","Someone in a doorway offers you something in a language you almost recognize.","The cherry sign over the club flickers, blinks, holds.","A drone the size of a fist buzzes the row, scanning faces, and moves on."]'::jsonb, '{"in":"zone_mq_cherry_floor","north":"zone_up_skyway","south":"zone_mq_marquee"}'::jsonb, '{"artery":["Cathode Street"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 3, -1, 0, 'CT', '#eeeeee', '#ae9292', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_powerplantnew', 'Coolant Flats', 'A flat apron of stained concrete where the ground still runs warm underfoot, waste heat bleeding up from whatever''s left alive below. Fat coolant mains arc overhead on their gantries, weeping rust-orange at every joint, and the air tastes of hot metal and pond scum. The Coldwater Power Plant looms at the apron''s edge behind chain-link and faded RADIATION placards, a turbine somewhere inside grinding on out of sheer habit. Steam ghosts up from a grate and refuses to disperse.', 'safe', 0, 0, 1, '["The hum changes pitch for a moment, then settles back.","Somewhere inside, something massive and patient keeps turning."]'::jsonb, '{"in":"zone_coldwater_turbine_hall","south":"zone_city_east"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -1, -2, 0, 'CP', '#eeeeee', '#42c96a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_overburden', 'The Overburden', 'The overburden heap — the worthless top-layer stripped off to get at whatever was beneath — dumped and forgotten in a ridge that the wastes have claimed. It is, fittingly, the wastes made of the wastes'' leftovers.', 'low', 0, 0, 0, '["The overburden ridge sheds a slow trickle of spoil and settles a little lower.","Something small bolts across the overburden and vanishes into a gap in the spoil."]'::jsonb, '{"east":"zone_waste_tarseep","west":"zone_waste_pitnine"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -7, -3, 0, 'TO', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_wreck', 'The Wreck', 'A freighter died here decades ago and never fully sank, its rusted flank a cliff of riveted iron you can board at low swell. Deep in the flooded holds, things have made a home.', 'medium', 0, 0, 1, '["The wreck groans as the swell works at it, shedding a rain of rust.","Something large shifts deep in the flooded hold, and the whole hull shivers."]'::jsonb, '{"east":"zone_bay_mid","west":"zone_bay_buoy","north":"zone_bay_slick","south":"zone_bay_sound"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 1, -6, 0, 'WR', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_reach', 'The Reach', 'The long open reach toward the bay mouth, where the fog thins and the swell finally has room to build. The far shore is a rumour on the worst days and invisible on the rest.', 'low', 0, 0, 1, '["The swell lifts the pontoon-walk and sets it down with a sigh.","Something surfaces far out on the reach, considers the distance, and sinks."]'::jsonb, '{"east":"zone_bay_narrows","west":"zone_bay_deadwater","south":"zone_bay_deep"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 3, -7, 0, 'RE', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_buoy', 'Iron Buoy', 'A great rusted channel-buoy lists here, its bell long silenced, chained to a mooring that no longer connects to anything. Squatters have built a precarious perch on top.', 'low', 0, 0, 1, '["The dead buoy''s bell shifts in the swell but does not quite ring.","A squatter waves from the buoy''s perch, or possibly warns you off."]'::jsonb, '{"east":"zone_bay_wreck"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 0, -6, 0, 'IB', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_slick', 'The Slick', 'A permanent rainbow slick of spilled fuel lies flat on the water here, too still to be healthy. Walk the lashed pontoons and try not to breathe deep.', 'low', 0, 0, 1, '["The fuel-slick parts around a pontoon and closes again, seamless.","A dead gull rotates slowly on the slick, wings spread as if still gliding."]'::jsonb, '{"east":"zone_bay_deadwater","south":"zone_bay_wreck"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 1, -7, 0, 'SL', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_deep', 'The Deep', 'The deepest sounding in the bay, marked on old charts with a number and a warning. Whatever the harbour lurkers grew from, it grew biggest down here, in the dark under the cold.', 'medium', 0, 0, 1, '["A wake broad as a road crosses the deep and sinks without a source.","The cold off the deep water climbs your spine like a hand."]'::jsonb, '{"east":"zone_bay_floes","west":"zone_bay_mid","north":"zone_bay_reach","south":"zone_bay_fog"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 3, -6, 0, 'DP', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_bay_mid', 'Coldwater Deep', 'The middle of the bay, where the water goes from grey to a green-black that gives nothing back. The pontoon-walks end at railings here, and beyond is just cold and down.', 'low', 0, 0, 1, '["The green-black water heaves once, without wind, and stills.","A railing marks the edge of the safe walk; past it, nothing but cold."]'::jsonb, '{"east":"zone_bay_deep","west":"zone_bay_wreck","north":"zone_bay_deadwater","south":"zone_bay_open"}'::jsonb, '{"water":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_harbor"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 2, -6, 0, 'CD', '#eeeeee', '#71b1e6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_ashenverge', 'Ashen Verge', 'The western lip of the flats, where the ash deepens to the knee and the wind never stops working at it. Footprints fill in behind you within a minute.', 'medium', 0, 0, 1, '["The ash swallows your last footprint before you''ve taken three more.","Wind carves a new dune-line across the verge while you watch."]'::jsonb, '{"east":"zone_waste_deadflat","west":"zone_waste_reek"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase4-build', '1783301927', 'map_world', NULL, -7, 1, 0, 'AV', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_marrowrow', 'Marrow Row', 'The eastern edge of the core where it presses against the fringe, a row of gnawed and hollowed ruins that the changed use as a larder and a lair both. It is the closest a living person can stand to the Redline''s heart and still, sometimes, walk away.', 'lethal', 0, 4, 0, '["A hollowed ruin along Marrow Row is packed with the clean-gnawed evidence of the Row''s purpose.","Something in the ruins cracks a bone for the marrow with a sound like a snapping bough."]'::jsonb, '{"west":"zone_waste_chargully","north":"zone_red_slaughterworks","south":"zone_waste_fumealley"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -9, -3, 0, 'MR', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_thresholdeast', 'The Threshold East', 'The boulevard continues east as the buildings grow taller and crowd closer together, casting long shadows over the broken pavement. Collapsed skybridges hang between aging towers, their twisted steel frames silhouetted against flickering neon in the distance. Scattered barricades and burned-out vehicles narrow the roadway into a winding path through decades of neglect. Weathered signs advertise businesses that haven''t existed in a generation, while loose cables sway overhead with a faint electrical buzz. Somewhere farther ahead, the city''s heartbeat feels stronger, though whether it promises opportunity or danger is impossible to tell.', 'safe', 0, 0, 1, '[]'::jsonb, '{"in":"zone_furniture_store","east":"zone_velk_exterior","west":"zone_threshold","south":"zone_city_se"}'::jsonb, '{"artery":["Grand Avenue"],"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"airspace_restricted":true,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, 1, 0, 0, 'TE', '#111111', '#7fda9a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_up_gate', 'Uptown Gate', 'The clean edge of the city. A corporate checkpoint of brushed steel and polite menace sorts the paying customers from the rest. Cameras track the way you walk.', 'safe', 0, 0, 1, '["A turnstile chimes approval for someone who is not you.","A recorded voice thanks you for your continued compliance."]'::jsonb, '{"north":"zone_dock_wharf","south":"zone_city_ne"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase1-build', '1783301927', 'map_world', NULL, 1, -2, 0, 'UG', '#eeeeee', '#42c96a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_brokenkiln', 'Broken Kiln', 'The cracked shell of a brick kiln, split down one side so it gapes like a broken jaw. Inside, out of the wind, is one of the few places in the wastes a person can almost rest. Almost.', 'medium', 0, 1, 0, '["Wind whistles through the split in the broken kiln and dies away inside it.","Old scorch-marks and newer bootprints share the floor of the kiln; you are not the first to almost rest here."]'::jsonb, '{"east":"zone_waste_greymile","west":"zone_red_vexhollow","north":"zone_waste_ferrouswash"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase10-build', '1783301927', 'map_world', NULL, -7, -4, 0, 'BK', '#eeeeee', '#efa2a2', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_hangar_outskirts', 'Coldwater Regional Hangar', 'The Coldwater Regional hangar: a cavernous prefab of corrugated steel, its floor a map of old oil stains and tyre scuffs. Tool racks and a battered workbench line one wall; a wheeled ops desk with a bank of flight monitors faces the other. The big bay doors stand open to the west, framing the ramp and the aircraft parked out on it. It smells of avgas, hot metal and cold coffee.', 'safe', 0, 0, 1, '[]'::jsonb, '{"out":"zone_outskirts","down":"zone_util_zone_hangar_outskirts"}'::jsonb, '{"hangar_ramp":"zone_outskirts","is_interior":true,"airfield_name":"Coldwater Regional","hangar_interior":true}'::jsonb, NULL, '1783227243', 'map_int_hangar_outskirts', NULL, 0, 0, 0, NULL, NULL, NULL, 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_hangar_slag_gate', 'Slagworks Strip Hangar', 'The Slagworks Strip hangar: a cavernous prefab of corrugated steel, its floor a map of old oil stains and tyre scuffs. Tool racks and a battered workbench line one wall; a wheeled ops desk with a bank of flight monitors faces the other. The big bay doors stand open to the west, framing the ramp and the aircraft parked out on it. It smells of avgas, hot metal and cold coffee.', 'safe', 0, 0, 1, '[]'::jsonb, '{"out":"zone_slag_gate","down":"zone_util_zone_hangar_slag_gate"}'::jsonb, '{"hangar_ramp":"zone_slag_gate","is_interior":true,"airfield_name":"Slagworks Strip","hangar_interior":true}'::jsonb, NULL, '1783227243', 'map_int_hangar_slag_gate', NULL, 0, 0, 0, NULL, NULL, NULL, 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_hangar_waste_scald', 'Redline Airstrip Hangar', 'The Redline Airstrip hangar: a cavernous prefab of corrugated steel, its floor a map of old oil stains and tyre scuffs. Tool racks and a battered workbench line one wall; a wheeled ops desk with a bank of flight monitors faces the other. The big bay doors stand open to the west, framing the ramp and the aircraft parked out on it. It smells of avgas, hot metal and cold coffee.', 'safe', 0, 0, 1, '[]'::jsonb, '{"out":"zone_waste_scald","down":"zone_util_zone_hangar_waste_scald"}'::jsonb, '{"hangar_ramp":"zone_waste_scald","is_interior":true,"airfield_name":"Redline Airstrip","hangar_interior":true}'::jsonb, NULL, '1783227243', 'map_int_hangar_waste_scald', NULL, 0, 0, 0, NULL, NULL, NULL, 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_hangar_dock_slip', 'Smuggler''s Slip Pad Hangar', 'The Smuggler''s Slip Pad hangar: a cavernous prefab of corrugated steel, its floor a map of old oil stains and tyre scuffs. Tool racks and a battered workbench line one wall; a wheeled ops desk with a bank of flight monitors faces the other. The big bay doors stand open to the west, framing the ramp and the aircraft parked out on it. It smells of avgas, hot metal and cold coffee.', 'safe', 0, 0, 1, '[]'::jsonb, '{"out":"zone_dock_slip","down":"zone_util_zone_hangar_dock_slip"}'::jsonb, '{"hangar_ramp":"zone_dock_slip","is_interior":true,"airfield_name":"Smuggler''s Slip Pad","hangar_interior":true}'::jsonb, NULL, '1783227243', 'map_int_hangar_dock_slip', NULL, 0, 0, 0, NULL, NULL, NULL, 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_city_east', 'The Loading Bay', 'A vast warehouse complex The Franchise uses as a distribution hub. Forklifts move between shelves stacked to the ceiling. Everything here has a SKU.', 'safe', 0, 0, 1, '["An autonomous forklift nearly runs you over. It has a smiley face sticker.","\"CUSTOMER SATISFACTION IS OUR PRIORITY,\" the speakers insist, less and less convincingly."]'::jsonb, '{"north":"zone_powerplantnew","south":"zone_city_west"}'::jsonb, '{"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -1, -1, 0, 'LW', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_registry', 'Registry Hall', 'The central registry of citizens, most of them dead, missing, or invented. Archivists move between the stacks with the reverence of priests tending a god that has stopped answering.', 'safe', 0, 0, 1, '["An archivist reshelves a citizen file with elaborate, pointless care.","A drawer of records rolls open, exhales dust, and offers up a name no one claims."]'::jsonb, '{"east":"zone_gov_cobalt","north":"zone_gov_ministry"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -4, -6, 0, 'RG', '#eeeeee', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_cobalt', 'Cobalt Court', 'A court of law tiled in cobalt, where cases are heard, adjourned, and inherited by the children of the original plaintiffs. Justice here is less blind than simply very, very slow.', 'safe', 0, 0, 1, '["A bailiff calls a case number that has not been reached in nine years.","Two advocates argue amicably over a docket neither expects to resolve."]'::jsonb, '{"east":"zone_gov_vantage","west":"zone_gov_registry","south":"zone_gov_mezzanine"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -3, -6, 0, 'CB', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_assembly', 'The Assembly', 'The debating chamber of a legislature that meets to ratify decisions the Architect already made. The benches are full of the earnest, the appointed, and the merely loud.', 'safe', 0, 0, 1, '["A vote is called in the chamber and passes unanimously, as they all do.","Someone at the rostrum speaks with great feeling to a chamber that isn''t listening."]'::jsonb, '{"east":"zone_gov_prefect","west":"zone_gov_ministry"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -3, -7, 0, 'AS', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_onyx', 'Onyx Row', 'The quarter''s lower approach, an onyx-flagged terrace where the government''s marble finally gives way to the working city — and, beyond the western rail, to the wastes.', 'safe', 0, 0, 1, '["A statue of a forgotten administrator watches Onyx Row with stone disapproval.","From the terrace edge you can see the wastes begin, grey and patient, to the west."]'::jsonb, '{"east":"zone_nc_datum","west":"zone_gov_mezzanine","north":"zone_gov_vantage"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -2, -5, 0, 'OX', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_badland_sw_outer', 'The Static Wood', 'What used to be a municipal park, gone feral over long neglect. The trees have grown in crooked and close, roots buckling the old footpaths, and a swing-set rusts on its chains where no child has played in a lifetime.', 'low', 1, 0, 1, '["A branch creaks overhead, though there is barely wind to move it.","A swing chain ticks back and forth, slow and rusty.","Something small rustles off through the undergrowth and is gone."]'::jsonb, '{"west":"zone_deep_waste"}'::jsonb, '{"lawless":true,"no_spawn":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -2, 1, 0, 'SW', '#eeeeee', '#6d7c9e', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_meat_offal', 'Offal Lane', 'Where the parts nobody names are sold to people who don''t ask — a lane of trestle tables under a low awning, the trade brisk and the eye-contact minimal.', 'medium', 1, 0, 1, '["A vendor slaps down a tray of something and looks away before you can.","Cats mass at the mouth of Offal Lane, waiting for the inevitable."]'::jsonb, '{"east":"zone_meat_carrion","west":"zone_deep_deepmaw","north":"zone_meat_ashpit"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 4, 3, 0, 'Of', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_outskirts', 'The Rust Quarter', 'The industrial edge of the basin, decades past its last shift. Enormous processing facilities stand half-collapsed, their sheet-metal walls streaked orange with rust and peeling off the frames. Weeds have prised up the loading aprons; nothing here has drawn power in a very long time.', 'low', 1, 0, 1, '["Loose sheet metal bangs somewhere in the wind, slow and hollow.","You find a paycheck stub from a company that no longer exists.","A pigeon clatters up out of a dead ventilation stack."]'::jsonb, '{"in":"zone_hangar_outskirts","east":"zone_city_west","west":"zone_badland_w_gate"}'::jsonb, '{"no_spawn":true,"airfield_id":"af_regional","is_building":false,"is_interior":false,"is_apartment":false,"airfield_fuel":true,"airfield_name":"Coldwater Regional","building_name":null,"building_type":null,"airfield_fuels":["avgas","jet","biofuel"],"airfield_dealer":true,"world_exit_zone":null,"airfield_charter":true,"airfield_lawless":false,"scavenging_table_id":"scav_roadside_junk","hangar_interior_zone":"zone_hangar_outskirts"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -2, 0, 0, 'RQ', '#eeeeee', '#6d7c9e', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_gov_vantage', 'Vantage Row', 'A gallery of offices with the best view in the quarter, allotted strictly by seniority to functionaries who no longer look up from their screens to use it.', 'safe', 0, 0, 1, '["A functionary''s blinds are drawn against the finest view in the city.","Someone important passes down Vantage Row and three doors quietly close."]'::jsonb, '{"east":"zone_nc_skyline","west":"zone_gov_cobalt","south":"zone_gov_onyx"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -2, -6, 0, 'VN', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_nc_sable', 'Sable Court', 'A black-marble court ringed by frontages so exclusive they have no signage at all. If you have to ask what''s sold here, a discreet security detail will ask you to leave.', 'safe', 0, 0, 1, '["A frosted door opens, exhales climate-controlled air, and closes on nothing.","Two security operators clock you, confer without words, and keep watching."]'::jsonb, '{"west":"zone_nc_halcyon"}'::jsonb, '{"gov_enclave":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_consumer_trash"}'::jsonb, 'phase5-build', '1783301927', 'map_world', NULL, 0, -7, 0, 'SB', '#111111', '#bca6a6', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_util_zone_hangar_outskirts', 'Coldwater Regional Hangar — Utility Room', 'A cramped below-grade utility room: bare concrete, sweating pipes, and the building junction box humming in its steel cabinet.', 'safe', 0, 0, 0, '[]'::jsonb, '{"up":"zone_hangar_outskirts"}'::jsonb, '{"is_interior":true,"utility_room":true}'::jsonb, NULL, '1783296275', 'map_int_hangar_outskirts', NULL, 0, 0, -1, NULL, NULL, NULL, 'indoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slag_reclaimer', 'The Reclaimer', 'At the works'' dead centre squats the reclaimer — a rotary furnace the size of a city block, its maw a black tunnel the wind pours into and never seems to come back out of. The richest salvage sits here, in the ash beds nobody sane will reach. The air hums, low, in your teeth.', 'medium', 1, 0, 0, '["The reclaimer''s drum shifts on its bearings with a groan you feel in the fillings of your teeth.","For just a second the hum stops, and the silence is so total you can hear your own blood."]'::jsonb, '{"east":"zone_slag_rail","north":"zone_red_dreadfurnace","south":"zone_waste_coldslag"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -11, 0, 0, 'RC', '#111111', '#e9b282', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_oxide', 'Oxide Flats', 'A rust-red flat where the district''s runoff bleeds out onto open ground, staining everything the colour of a wound. The quarter looks the other way; the wastes do not.', 'medium', 0, 0, 1, '["Orange runoff bleeds across the oxide flat in slow, branching deltas.","Something pale and heavy shifts in the rust-stained mud and goes still."]'::jsonb, '{"east":"zone_waste_downwind","west":"zone_nc_manifold","north":"zone_nc_palisade","south":"zone_yard_container"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_west_wastes"}'::jsonb, 'phase9-build', '1783301927', 'map_world', NULL, 6, -4, 0, 'Ox', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
