INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_yard_bulk', 'Bulk Yard', 'An open bulk yard heaped with aggregate, scrap, and materials too cheap to steal but too useful to bin. A grab-crane picks at the heaps with idiot patience.', 'low', 0, 0, 1, '["The grab-crane drops a jawful of scrap and swings back for more.","A heap of aggregate slides with a long grinding sigh and resettles lower."]'::jsonb, '{"west":"zone_yard_interchange","north":"zone_yard_railhead"}'::jsonb, '{"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, 'phase7-build', '1783301927', 'map_world', NULL, 8, 3, 0, 'BK', '#111111', '#1eae5d', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_ruins', 'Old Coldwater', 'What remains of the actual city. Glass and rebar and the occasional wall of a building that still looks like it meant something once. At the center, the old city hall stands largely untouched — the Architect''s infrastructure runs through its foundation. A Precinct checkpoint straddles the old haul road here — a scanner arch, a bored guard, and a queue: the one way the wastes bleed into the city.', 'medium', 1, 0, 0, '["The city hall''s windows glow faint blue. They always do. Nobody goes in.","A dog watches you from a pile of rubble. It doesn''t seem scared. That''s somehow worse."]'::jsonb, '{"east":"zone_badland_w_gate","west":"zone_ashway_road"}'::jsonb, '{"checkpoint":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_roadside_junk"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -4, 0, 0, 'OC', '#eeeeee', '#6d7c9e', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_slag_rail', 'The Rail Throat', 'A rail siding chokes on its own collapse here — tanker cars derailed and stacked, spines snapped, spilling decades-dry chemical crust across the ballast. The rolling stock is a mountain of salvage nobody''s been desperate enough to climb. Yet.', 'low', 1, 0, 0, '["Metal contracts somewhere in the wreck with a bang that rolls off flat across the flats.","A tanker car settles a half-inch with a groan and a shower of rust."]'::jsonb, '{"east":"zone_slag_yard","west":"zone_slag_reclaimer","north":"zone_slag_flarestack","south":"zone_slag_drums"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":null,"scavenging_table_id":"scav_industrial_salvage"}'::jsonb, NULL, '1783301927', 'map_world', NULL, -10, 0, 0, 'RT', '#111111', '#e9b282', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_waste_scald', 'The Scald', 'A field of blanched, chemically-burnt hardpan where nothing has grown since before the Handoff. The government pretends this is the edge of its jurisdiction, and the wastes agree.', 'medium', 0, 0, 1, '["Heat-haze rises off the scalded pan though the air itself is cold.","A brittle crust of bleached salts crunches to powder underfoot."]'::jsonb, '{"in":"zone_hangar_waste_scald","west":"zone_waste_tailings","north":"zone_waste_rusthollow","south":"zone_waste_leachfield"}'::jsonb, '{"lawless":true,"airfield_id":"af_redline","is_building":false,"is_interior":false,"is_apartment":false,"airfield_fuel":true,"airfield_name":"Redline Airstrip","building_name":"","building_type":null,"airfield_fuels":["biofuel"],"airfield_dealer":false,"airfield_charter":false,"airfield_lawless":true,"scavenging_table_id":"scav_west_wastes","hangar_interior_zone":"zone_hangar_waste_scald"}'::jsonb, 'phase6-build', '1783301927', 'map_world', NULL, -5, -6, 0, 'SC', '#eeeeee', '#be9d64', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_rictusalley', 'Rictus Alley', 'A narrow alley where the dead lie where they fell, dried by the poisoned air into leather and locked, every one of them, into a wide fixed grin. They line the walls like an audience. They have been waiting a long time for the show, and you have just walked on.', 'lethal', 0, 4, 0, '["The grinning dead of Rictus Alley watch you pass with their fixed, patient, leather smiles.","A dried corpse propped against the wall has, you are almost certain, turned to follow you."]'::jsonb, '{"east":"zone_red_slaughterworks","west":"zone_red_bonepit","north":"zone_red_screaminglot","south":"zone_waste_chargully"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -10, -4, 0, 'RA', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_red_cullrow', 'Cull Row', 'A row where, in the early days, they tried to hold the line — to cull the changed as they came, at a barricade of scrap and desperation. The barricade is still here. So, in a sense, are the people who manned it, though they are on the wrong side of it now.', 'lethal', 0, 4, 0, '["The old cull-barricade sags across the row, hung with things best not examined closely.","Something on the far side of the barricade tests it, gently, methodically, looking for the give."]'::jsonb, '{"east":"zone_waste_deadfurnace","west":"zone_red_screaminglot","north":"zone_red_hazardnine","south":"zone_red_slaughterworks"}'::jsonb, '{"lawless":true,"is_building":false,"is_interior":false,"is_apartment":false,"building_name":"","building_type":null,"scavenging_table_id":"scav_irradiated_salvage"}'::jsonb, 'phase12-build', '1783301927', 'map_world', NULL, -9, -5, 0, 'CR', '#eeeeee', '#e77474', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_threshold', 'The Threshold', 'The fractured boulevard stretches east beneath leaning streetlights and sagging power lines. Rows of shuttered storefronts stare blankly across the cracked pavement, their windows painted over or shattered years ago. Rusted buses sit abandoned where traffic died, their interiors swallowed by dust and creeping vines. Faded evacuation signs still point deeper into the city, while countless layers of graffiti bury whatever messages came before. Every road seems to lead somewhere important, yet every direction feels equally forgotten.', 'safe', 0, 0, 1, '["A drone hums overhead, its chassis stenciled with a faded corporate logo you half-recognize.","Somewhere in the plaza, a speaker plays a jingle for a fast food chain. Thirty seconds in, it loops.","A ragged NPC catches your eye and immediately looks away. Everyone here has learned not to be interesting.","The departure board flickers: COLDWATER → DENVER → SALT LAKE → [SIGNAL LOST]"]'::jsonb, '{"in":"zone_hangar_threshold","east":"zone_thresholdeast","west":"zone_city_west","north":"zone_city_north","south":"zone_city_south"}'::jsonb, '{"artery":["Grand Avenue"],"no_spawn":true,"airfield_id":"af_helipad","is_building":false,"is_interior":false,"is_apartment":false,"airfield_fuel":true,"airfield_name":"Threshold Helipad","building_name":null,"building_type":null,"airfield_fuels":["avgas","jet"],"airfield_dealer":false,"world_exit_zone":null,"airfield_charter":true,"airfield_lawless":false,"scavenging_table_id":"scav_roadside_junk","hangar_interior_zone":"zone_hangar_threshold"}'::jsonb, NULL, '1783301927', 'map_world', NULL, 0, 0, 0, 'TR', '#111111', '#7fda9a', 'city', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
INSERT INTO zones ("id", "name", "description", "danger_rating", "pvp_enabled", "radiation_level", "is_safe_zone", "ambient_events", "exits", "flags", "created_by", "updated_at", "map_id", "parent_zone", "grid_x", "grid_y", "grid_z", "marker", "color", "bg_color", "ambient_theme", "stains", "audio_theme_id") VALUES ('zone_velk_exterior', 'Castoff Walk', 'A cramped walk wedged between two facades in slow structural surrender, close enough to touch both walls at once. What isn''t rented out is stacked with other people''s abandoned lives — chair legs, dead lamps, a wardrobe with no doors — chained together against the inevitable. Velk''s Pre-Owned holds the middle of the walk, its window a chaos of salvaged furniture arranged with a curator''s inexplicable pride. Everything smells of damp upholstery and someone else''s cigarettes.', 'low', 0, 0, 1, '[]'::jsonb, '{"in":"zone_velk_shop","east":"zone_mq_marquee","west":"zone_thresholdeast","south":"zone_drum_exterior"}'::jsonb, '{"artery":["Grand Avenue"],"is_building":false,"is_interior":false,"is_apartment":false,"building_name":null,"building_type":null,"world_exit_zone":"zone_deep_waste","scavenging_table_id":null}'::jsonb, NULL, '1783301927', 'map_world', NULL, 2, 0, 0, 'Fu', '#eeeeee', '#42c96a', 'outdoors', '{}'::jsonb, NULL) ON CONFLICT DO NOTHING;
