INSERT INTO items ("id", "name", "description", "type", "subtype", "weight", "value", "is_stackable", "is_unique", "is_quest_item", "effects", "stat_modifiers", "requirements", "flags", "tags") VALUES ('item_prison_jumpsuit', 'prison jumpsuit', 'A shapeless one-piece coverall in Precinct 9 orange, the paper-thin fabric stamped DETAINEE across the back in stencilled block letters. It zips from crotch to throat and covers you from shoulders to shins in a single miserable garment. It fits nobody and smells of institutional bleach.', 'clothing', NULL, 800, 5, 0, 0, 0, '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, '{"slot":"torso","armor":0,"layer":"outerwear","covers":["legs"],"bulkiness":2,"insulation":2,"description":"A shapeless one-piece coverall in Precinct 9 orange, the paper-thin fabric stamped DETAINEE across the back in stencilled block letters. It zips from crotch to throat and covers you from shoulders to shins in a single miserable garment. It fits nobody and smells of institutional bleach."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_wanted_patrol_officer', 'SPECTER-PD Patrol Officer', 'A street cop in scuffed riot-lite armor, sidearm already drawn. Not tough, but they radio everything they see.', 42, '[]'::jsonb, 'aggressive', 'police', 'The officer crumples, radio still squawking.', '{}'::jsonb, '{}'::jsonb, 4, 3, '[{"max":5,"min":2,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{"kinetic":1},"weight":1},{"part":"torso","soak":{"kinetic":1},"weight":3},{"part":"legs","soak":{"kinetic":1},"weight":2}]'::jsonb, '[]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_rad_mutant', 'Rad Mutant', 'Something that used to be human. The Bleed does this. The extra limb is load-bearing.', 65, '[{"qty":[1,1],"item":"item_mutant_gland","weight":50}]'::jsonb, 'aggressive', NULL, 'The mutant folds in on itself in a way that suggests the laws of anatomy were more like suggestions.', '{"radiates":true,"attacks_npcs":false,"battle_cries":["$enemy emits wet ragged breathing.","$enemy produces uneven animalistic snarls.","$enemy shifts with bone crackling movement.","$enemy emits guttural choking growls.","$enemy outputs broken vocal screaming fragments.","$enemy emits rising fevered shriek."],"radiation_damage":5,"first_strike_delay_ms":1000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":2,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_architect_drone', 'Architect Scout Drone', 'A black hexagonal drone about the size of a dinner plate. No insignia. Watching.', 30, '[{"qty":[1,1],"item":"item_drone_core","weight":40},{"qty":[1,1],"item":"item_architect_fragment","weight":15}]'::jsonb, 'patrol', NULL, 'The drone spirals down. Somewhere, something notices.', '{"flies":true,"attacks_npcs":false,"battle_cries":["$enemy emits sterile shifting hum.","$enemy produces thin scanning whine.","$enemy shifts pitch to signal awareness.","$enemy emits irregular digital beeps.","$enemy outputs fragmented speech echoes.","$enemy emits rising diagnostic tone.","$enemy produces sub-bass lock pulse."],"architect_aligned":true,"first_strike_delay_ms":1000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":2,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_custodian_enforcer', 'Custodian Enforcer', 'Polo shirt. Khaki pants. Body armor under both. The most dangerous middle manager you''ll ever meet.', 55, '[{"qty":[1,1],"item":"item_custodian_badge","weight":80},{"qty":[1,1],"item":"item_credits_medium","weight":60}]'::jsonb, 'territorial', 'faction_custodians', 'Employee of the Month, the badge reads. Third quarter, four years running.', '{"attacks_npcs":false,"battle_cries":["\"That’s a formal warning.\"","\"This is not optional anymore.\"","\"Documenting noncompliance.\"","\"Voice raised—last warning.\"","\"Escalation is now required.\"","\"Immediate compliance is expected.\""],"first_strike_delay_ms":1000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":2,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_feral_dog', 'Feral Dog', 'Once someone''s pet. Now a forty-pound argument for not going outside.', 25, '[{"qty":[1,1],"item":"trashbag","weight":25}]'::jsonb, 'aggressive', NULL, 'The dog goes down. You feel bad about it for approximately three seconds.', '{"battle_cries":["$enemy coils, ready to spring at $player.","$enemy circles, silently eyeing up $player.","$enemy bares its teeth at $player.","$enemy stiffens as it watches $player.","$enemy creeps a step closer to $player.","$enemy paces around $player.","$enemy snaps its jaws at $player.","$enemy lowers its head toward $player.","$enemy''s hackles rise at the sight of $player.","$enemy paws at the ground before $player.","$enemy glares at $player without blinking.","$enemy prowls around $player.","$enemy lets out a low snarl at $player."],"first_strike_delay_ms":10000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":2,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[{"qty":[1,1],"item":"item_raw_meat","weight":100}]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_arbiterclass_enforcement_unit', 'Arbiter-Class Enforcement Unit', 'The Arbiter-Class Enforcement Unit stands rigid and combat-ready, matte black armor segmented for efficiency rather than aesthetics. Its frame is tall, lean, and engineered for rapid deployment, every joint minimized for speed and controlled force. A single horizontal optic glows white across its head like a targeting slit, flat and expressionless.', 100, '[]'::jsonb, 'aggressive', NULL, 'The Arbiter-Class Enforcement Unit is destroyed—its frame buckles as core systems fail in sequence, optic going dark before the chassis finally collapses into inert, broken alloy.', '{"attacks_npcs":false,"battle_cries":["\"COMPLY.\"","\"HOSTILE CONFIRMED.\"","\"THREAT ACQUIRED.\"","\"LETHAL FORCE AUTHORIZED.\"","\"STAND DOWN.\"","\"SURRENDER IMMEDIATELY.\"","\"RESISTANCE RECORDED.\"","\"ENGAGING TARGET.\"","\"SECURITY PROTOCOL ACTIVE.\"","\"ORDER WILL BE RESTORED.\"","\"YOU ARE IN VIOLATION.\"","\"FORCE ESCALATION AUTHORIZED.\""],"first_strike_delay_ms":0}'::jsonb, '{}'::jsonb, 10, 10, '[{"max":20,"min":10,"type":"energy"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_scav', 'Desperate Scavenger', 'Sunburned, twitchy, armed with something sharp.', 30, '[{"qty":[1,3],"item":"item_scrap_metal","weight":80},{"qty":[1,1],"item":"item_ration","weight":40},{"qty":[1,1],"item":"item_credits_small","weight":60}]'::jsonb, 'aggressive', NULL, 'The scavenger collapses with an expression of profound disappointment.', '{"attacks_npcs":false,"battle_cries":["$enemy sways, blade dragging low through dust.","$enemy scratches at their arm until they draw blood.","$enemy laughs under their breath, unfocused and shaky.","$enemy stumbles, then corrects like gravity is optional.","$enemy keeps blinking hard, trying to clear their vision.","\"I can feel it under my skin.\"","\"Don’t… don’t make it worse.\"","\"It’s moving when I stop.\"","\"I lost track again.\"","\"Which one of you is real?\""],"first_strike_delay_ms":1000}'::jsonb, '{"nodes":{},"_start":""}'::jsonb, 1, 1, '[{"max":2,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[{"qty":[1,1],"item":"item_raw_meat","weight":100}]'::jsonb, 5) ON CONFLICT DO NOTHING;
