INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_scrap_picker', 'Scrap-Picker', 'A gaunt scavenger in a cracked gas-mask and too many coats, guarding a sack of salvage like it is a newborn.', 22, '[{"qty":[1,3],"item":"item_scrap_metal","weight":70},{"qty":[1,1],"item":"item_credits_small","weight":50},{"qty":[1,1],"item":"item_ration","weight":30}]'::jsonb, 'aggressive', NULL, 'The scrap-picker drops their shiv and folds up over their haul.', '{"attacks_npcs":false,"battle_cries":["\"This is my patch. Find your own.\"","\"Don''t. Don''t make me.\"","$enemy waves the shiv in a shaky arc at $player.","\"Everything here''s already spoken for.\"","$enemy backs up a step, blade out, watching $player."],"first_strike_delay_ms":9000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":3,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[{"qty":[1,1],"item":"item_raw_meat","weight":100}]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_sprawl_ganger', 'sprawl ganger', 'A wiry Undermarket local in a patched jacket and a face like a closed door. Carries a ground-down shiv and the confidence of someone with nothing to lose and a crew nearby.', 26, '[{"qty":[1,2],"item":"item_scrap_metal","weight":25}]'::jsonb, 'aggressive', NULL, 'The ganger folds over their own shiv and drops without a sound.', '{}'::jsonb, '{}'::jsonb, 4, 3, '[{"max":6,"min":2,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{"kinetic":1},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_slag_wretch', 'Slag-Wretch', 'What the works made of a shift-worker who never clocked out: skin like slag, eyes like cooling glass, still wearing the tatters of a hi-vis vest.', 34, '[{"qty":[1,2],"item":"item_glowing_scrap","weight":40},{"qty":[1,1],"item":"item_mutated_bone","weight":30},{"qty":[1,1],"item":"item_credits_small","weight":35}]'::jsonb, 'aggressive', NULL, 'The wretch sags against a pipe and slides down it, finally still.', '{"attacks_npcs":false,"battle_cries":["$enemy drags a ruined arm toward $player.","$enemy exhales a lungful of ash at $player.","$enemy''s jaw works, but only static comes out.","$enemy shambles a step closer to $player.","$enemy fixes $player with two panes of cooling glass."],"first_strike_delay_ms":4000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":4,"min":2,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[{"qty":[1,2],"item":"item_raw_meat","weight":100}]'::jsonb, 6) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_ash_crawler', 'Ash Crawler', 'A dog-sized arthropod fused out of ash and something that used to be a raccoon. Too many legs, all of them in a hurry.', 14, '[{"qty":[1,1],"item":"item_mutated_bone","weight":25},{"qty":[1,1],"item":"item_glowing_scrap","weight":12}]'::jsonb, 'aggressive', NULL, 'The crawler curls into itself with a chitinous crackle and stops moving.', '{"attacks_npcs":false,"battle_cries":["$enemy rears up, mandibles clicking at $player.","$enemy scuttles sideways around $player.","$enemy sprays a hiss of ash at $player.","$enemy''s legs blur as it rushes $player.","$enemy drums its forelimbs against the ground at $player."],"first_strike_delay_ms":7000}'::jsonb, '{}'::jsonb, 1, 2, '[{"max":3,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[{"qty":[1,2],"item":"item_raw_meat","weight":100}]'::jsonb, 4) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_gutter_cat', 'Gutter Cat', 'A feral tomcat gone ragged and mean, one ear chewed to a stub. It has ruled this stretch of gutter longer than you have been alive, and it knows it.', 9, '[{"qty":[1,1],"item":"item_raw_meat","weight":35}]'::jsonb, 'aggressive', NULL, 'The cat yowls once, indignant, and bolts its last.', '{"battle_cries":["$enemy flattens its ears and hisses at $player.","$enemy arches its back at $player.","$enemy yowls a warning at $player.","$enemy swipes a ragged paw at $player.","$enemy stares down $player, tail lashing."],"first_strike_delay_ms":5000}'::jsonb, '{}'::jsonb, 1, 3, '[{"max":2,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[{"qty":[1,1],"item":"item_raw_meat","weight":100}]'::jsonb, 2) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_squatter', 'Squatter', 'A gaunt vagrant who has made a home in the ruins and takes trespass personally: layers of salvaged coats, a length of pipe, and eyes that watched the neighbourhood empty out one window at a time.', 22, '[{"qty":[1,2],"item":"item_scrap_metal","weight":60},{"qty":[1,1],"item":"item_credits_small","weight":45},{"qty":[1,1],"item":"item_ration","weight":25}]'::jsonb, 'aggressive', NULL, 'The squatter slumps against their doorway and stops guarding it.', '{"attacks_npcs":false,"battle_cries":["\"This is my block. Move on.\"","\"You don''t belong here.\"","$enemy hefts the pipe at $player.","\"Nothing here for you. Go.\"","$enemy backs into the doorway, pipe raised at $player."],"first_strike_delay_ms":8000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":3,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[{"qty":[1,1],"item":"item_raw_meat","weight":100}]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_rusted_sweeper', 'Rusted Sweeper', 'A municipal street-sweeping drone from the city''s better days, still trundling its route on three good wheels and one bad one. Its brushes are worn to nubs and its logic to nothing. It does not recognise you as pavement, which is the only good news.', 18, '[{"qty":[1,2],"item":"item_scrap_metal","weight":55},{"qty":[1,1],"item":"item_credits_small","weight":30}]'::jsonb, 'aggressive', NULL, 'The sweeper grinds to a halt, brushes still twitching, and goes dark.', '{"battle_cries":["$enemy grinds its worn brushes at $player.","$enemy pivots toward $player with a squeal of bearings.","$enemy emits a garbled municipal chime at $player.","$enemy trundles a wobbling circle around $player.","$enemy flashes a cracked warning light at $player."],"first_strike_delay_ms":6000}'::jsonb, '{}'::jsonb, 1, 1, '[{"max":2,"min":1,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":13},{"part":"right_leg","soak":{},"weight":13}]'::jsonb, '[]'::jsonb, 5) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_wire_jackal', 'wire jackal', 'A lean scavenger stitched together from dog and junkyard — copper-whisker muzzle, a hide of wire and scab. Hunts the wastes in packs and pulls down anything slower than it.', 14, '[{"qty":[1,1],"item":"item_salvaged_wiring","weight":22},{"qty":[1,1],"item":"item_scrap_metal","weight":18}]'::jsonb, 'aggressive', NULL, 'The jackal yelps, folds, and its pack scatters into the grey.', '{}'::jsonb, '{}'::jsonb, 5, 4, '[{"max":5,"min":2,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":10},{"part":"torso","soak":{},"weight":40},{"part":"left_leg","soak":{},"weight":12},{"part":"right_leg","soak":{},"weight":12},{"part":"left_flank","soak":{},"weight":13},{"part":"right_flank","soak":{},"weight":13}]'::jsonb, '[]'::jsonb, 4) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_slag_wight', 'slag wight', 'What''s left of a work-crew that never clocked out — a husk of fused slag and old coveralls, radiant with a dry heat, moving with the patience of something that has already died once.', 34, '[{"qty":[1,1],"item":"item_glowing_scrap","weight":16},{"qty":[1,1],"item":"item_cracked_capacitor","weight":12},{"qty":[1,1],"item":"item_mutated_bone","weight":10}]'::jsonb, 'aggressive', NULL, 'The wight sags, its heat guttering out, and settles into the ash it came from.', '{}'::jsonb, '{}'::jsonb, 5, 2, '[{"max":7,"min":3,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{"kinetic":1},"weight":10},{"part":"torso","soak":{"kinetic":2},"weight":40},{"part":"left_arm","soak":{"kinetic":1},"weight":12},{"part":"right_arm","soak":{"kinetic":1},"weight":12},{"part":"left_leg","soak":{"kinetic":1},"weight":13},{"part":"right_leg","soak":{"kinetic":1},"weight":13}]'::jsonb, '[]'::jsonb, 7) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_harbor_lurker', 'harbour lurker', 'A long, pale thing grown fat on the bay''s runoff — part eel, part something that used to have legs. It hangs just under the surface and takes what strays too near the edge.', 20, '[{"qty":[1,1],"item":"item_fresh_catch","weight":18},{"qty":[1,1],"item":"item_mutated_bone","weight":14},{"qty":[1,1],"item":"item_scrap_metal","weight":10}]'::jsonb, 'aggressive', NULL, 'The lurker thrashes once, sheeting the boards with black water, and sinks out of sight.', '{}'::jsonb, '{}'::jsonb, 5, 4, '[{"max":6,"min":2,"type":"kinetic"}]'::jsonb, '[{"part":"maw","soak":{},"weight":12},{"part":"body","soak":{"kinetic":1},"weight":44},{"part":"tail","soak":{},"weight":16},{"part":"left_fin","soak":{},"weight":14},{"part":"right_fin","soak":{},"weight":14}]'::jsonb, '[{"qty":[1,2],"item":"item_fresh_catch","weight":30}]'::jsonb, 4) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_tar_horror', 'tar-pit horror', 'A slow-heaving mass of accreted tar, bone, and swallowed machinery that hauls itself up out of the seeps to feed. It is patient, nearly mindless, and very hard to convince to let go.', 42, '[{"qty":[1,2],"item":"item_mutated_bone","weight":18},{"qty":[1,1],"item":"item_glowing_scrap","weight":12},{"qty":[1,1],"item":"item_scrap_metal","weight":10}]'::jsonb, 'aggressive', NULL, 'The horror sloughs apart into the tar it came from, and the seep drinks it back down.', '{}'::jsonb, '{}'::jsonb, 4, 1, '[{"max":8,"min":4,"type":"kinetic"}]'::jsonb, '[{"part":"crown","soak":{"kinetic":1},"weight":12},{"part":"mass","soak":{"kinetic":3},"weight":48},{"part":"left_tendril","soak":{"kinetic":1},"weight":20},{"part":"right_tendril","soak":{"kinetic":1},"weight":20}]'::jsonb, '[{"qty":[1,1],"item":"item_mutated_bone","weight":30}]'::jsonb, 8) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_cable_eel', 'Cable Eel', 'A black, cable-thick eel as long as a man is tall, its hide studded with the barnacled remains of fibre-optic sheathing it has swallowed and grown around. Its jaw is a ring of glassy, back-curved teeth.', 16, '[{"qty":[1,1],"item":"item_fresh_catch","weight":40}]'::jsonb, 'aggressive', NULL, 'The eel thrashes itself still and lies steaming on the boards.', '{"attacks_npcs":false,"battle_cries":["$enemy coils and lunges at $player, jaws wide.","$enemy lashes a whipcrack of muscle across the dock at $player.","$enemy''s glassy teeth snap shut a hand''s breadth from $player."],"first_strike_delay_ms":3000}'::jsonb, '{}'::jsonb, 3, 3, '[{"max":6,"min":2,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":20},{"part":"torso","soak":{},"weight":60},{"part":"tail","soak":{},"weight":20}]'::jsonb, '[{"qty":[1,2],"item":"item_raw_meat","weight":100}]'::jsonb, 4) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_bay_leviathan', 'bay leviathan', 'The thing the harbour lurkers are only the children of — a vast, pale, coiling shape that owns the deep water of Coldwater Bay. It rises rarely, feeds enormously, and has never once been photographed and believed.', 55, '[{"qty":[1,1],"item":"item_contraband_crate","weight":10},{"qty":[2,3],"item":"item_fresh_catch","weight":22},{"qty":[1,2],"item":"item_mutated_bone","weight":16},{"qty":[1,1],"item":"item_glowing_scrap","weight":10}]'::jsonb, 'aggressive', NULL, 'The leviathan rolls once, vast and final, and slides back into the deep it will not truly leave.', '{}'::jsonb, '{}'::jsonb, 5, 2, '[{"max":10,"min":5,"type":"kinetic"}]'::jsonb, '[{"part":"maw","soak":{"kinetic":1},"weight":14},{"part":"body","soak":{"kinetic":2},"weight":46},{"part":"coils","soak":{"kinetic":1},"weight":24},{"part":"fluke","soak":{},"weight":16}]'::jsonb, '[{"qty":[2,4],"item":"item_fresh_catch","weight":30}]'::jsonb, 9) ON CONFLICT DO NOTHING;
INSERT INTO enemies ("id", "name", "description", "hp_max", "loot_table", "behavior", "faction", "death_message", "flags", "behaviour_graph", "hit", "dodge", "weapon", "body_parts", "butcher_table", "butcher_difficulty") VALUES ('enemy_redline_horror', 'a Redline horror', 'The apex the Redline bred to rule its killing floor — too many limbs, too much of it load-bearing, and a heart you can hear ticking from across the open ground. Whatever it started as, the Bleed finished it into this.', 130, '[{"qty":[1,1],"item":"item_redline_heart","weight":100},{"qty":[1,2],"item":"item_mutant_gland","weight":60}]'::jsonb, 'aggressive', NULL, 'The horror comes apart in a way that suggests it had been holding itself together out of spite, and the ticking, at last, stops.', '{"radiates":true,"attacks_npcs":false,"battle_cries":["$enemy drags its load-bearing limbs across the bone with a wet scrape.","$enemy emits a low tick that climbs into a shriek.","$enemy unfolds a limb that should not bend that way.","$enemy screams with a mouth that is mostly other mouths."],"radiation_damage":8,"first_strike_delay_ms":800}'::jsonb, '{}'::jsonb, 3, 2, '[{"max":9,"min":4,"type":"kinetic"}]'::jsonb, '[{"part":"head","soak":{},"weight":8},{"part":"torso","soak":{},"weight":44},{"part":"left_arm","soak":{},"weight":12},{"part":"right_arm","soak":{},"weight":12},{"part":"left_leg","soak":{},"weight":12},{"part":"right_leg","soak":{},"weight":12}]'::jsonb, '[]'::jsonb, 9) ON CONFLICT DO NOTHING;
