INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_yardmaster', 'Voss', 'The Yards'' yardmaster, a barrel of a man who runs freight, salvage, and the occasional quiet cargo out of a dead signal box. He knows where everything is, whose it is, and what it would cost you to disagree.', 'zone_yard_railhead', NULL, '{"bye":{"text":"\"Mind the forklifts on your way out.\"","options":[]},"root":{"text":"Voss looks up from a manifest he plainly wrote himself. \"Freight, salvage, or a favour? I do all three, and only one of them''s on the books.\"","options":[{"next":"quest_offer","label":"What kind of favour?"},{"next":"__shop__","label":"Show me your salvage."},{"next":"bye","label":"Nothing."}]},"accepted":{"text":"\"Good. They den in the wet freight down the south end. Mind the grab-crane; it doesn''t stop for anyone, including me.\"","actions":[{"action":"START_QUEST","quest_id":"quest_sidings_cleared"}],"options":[{"next":"bye","label":"Understood."}]},"reported":{"text":"\"...Sidings are quiet. My flatcars still have their fittings. Here — your coin, and a crate that fell off the back of a truck I definitely logged. We''re square.\"","actions":[{"action":"TURN_IN","quest_id":"quest_sidings_cleared"}],"options":[{"next":"bye","label":"Obliged."}]},"quest_offer":{"text":"\"Scavengers. Coming up off the sidings and stripping my parked flatcars to the rivets. Clear three of them out of the yards — Skid Row, the bulk heaps, the bonded cage — and there''s coin and a no-questions crate in it for you.\"","options":[{"next":"accepted","label":"I''ll clear the sidings."},{"next":"reported","label":"It''s done. (report back)"},{"next":"bye","label":"Pass."}]}}'::jsonb, '[{"price":4,"item_id":"item_scrap_metal"},{"price":8,"item_id":"item_salvaged_wiring"},{"price":14,"item_id":"item_cracked_capacitor"},{"price":90,"item_id":"item_contraband_crate"},{"price":15,"item_id":"canteen"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a hi-vis yardmaster''s vest","a grease-grey work shirt","a heavy freight-hauler''s belt"]}'::jsonb, '{}'::jsonb, 'zone_yard_railhead', NULL, 'zone_yard_railhead', '[]'::jsonb, 24, 24, 'male', '[{"item_id":"item_scrap_metal"},{"item_id":"item_salvaged_wiring"},{"item_id":"item_cracked_capacitor"},{"item_id":"item_contraband_crate"},{"item_id":"canteen"}]'::jsonb, 10, 1, 340, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'The Railhead Office', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_butcher', 'the Butcher', 'A vast, unhurried man in an apron you try not to look at too closely, working the killing lane with a cleaver worn thin from sharpening. He sells meat, buys meat, and does not clarify the difference.', 'zone_meat_slaughter', NULL, '{"bye":{"text":"\"Everyone comes back hungry.\"","options":[]},"root":{"text":"The Butcher sets down his cleaver with unsettling gentleness. \"Meat. Fresh, mostly. Cheap, always. You bring me something with meat on it, I''ll pay, and I won''t ask what it was.\"","options":[{"next":"__shop__","label":"What''s fresh?"},{"next":"bye","label":"Lost my appetite."}]}}'::jsonb, '[{"price":6,"item_id":"item_raw_meat"},{"price":6,"item_id":"item_bar_jerky"},{"price":10,"item_id":"item_ration"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a rubber apron best left undescribed","a blood-stiff undershirt","waders and nothing to discuss"]}'::jsonb, '{}'::jsonb, 'zone_meat_slaughter', NULL, 'zone_meat_slaughter', '[]'::jsonb, 22, 22, 'male', '[{"item_id":"item_raw_meat"},{"item_id":"item_bar_jerky"},{"item_id":"item_ration"}]'::jsonb, 8, 1, 120, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'Slaughter Lane', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_yard_teamster', 'a teamster', 'A rope-armed teamster with a manifest board and no patience, directing forklifts by bellowed insult and pointing with whatever''s in her hand.', 'zone_yard_transfer', NULL, '{"bye":{"text":"\"Then pass faster.\"","options":[]},"root":{"text":"The teamster doesn''t stop marking her board. \"If you''re not freight and you''re not crew, you''re an obstacle. Which is it?\"","options":[{"next":"bye","label":"Just passing."}]}}'::jsonb, NULL, 0, '{"personality":"labourer","clothing_layers":["a hi-vis vest over a thermal","cargo trousers with too many pockets","steel-caps worn to the steel"]}'::jsonb, '{}'::jsonb, 'zone_yard_transfer', NULL, 'zone_yard_transfer', '["The teamster bellows a forklift into a gap and it obeys.","\"You''re standing in a load lane. Don''t.\"","\"Everything in this yard is going somewhere. Are you?\""]'::jsonb, 18, 18, 'female', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_captain_nguyen', 'Captain Nguyen', 'A broadcast studio host.', 'zone_city_north', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_precinct_officer_2', 'Detention Officer Pryce', 'Wiry and unhurried, Pryce runs the holding block like a night-shift librarian — quiet, exact, and utterly unbothered by whatever you did to get here. A ring of mag-keys hangs off one hip; a lukewarm coffee never leaves the other hand.', 'zone_mq_precinct_lobby', 'SPECTER-PD', '{}'::jsonb, '[]'::jsonb, 0, '{"police":true,"essential":true,"personality":"police","clothing_layers":["a surplus tac-vest stencilled POLICE","a navy uniform shirt","grey briefs"]}'::jsonb, '{}'::jsonb, 'zone_mq_precinct_lobby', NULL, NULL, '["Pryce thumbs through a charge sheet without much interest.","\"Booking''s backed up. Everybody''s in a hurry to be somewhere worse.\""]'::jsonb, 60, 60, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_consignor', 'Merrow', 'A consignment broker in a suit that has never seen the yard floor, who trades in the paperwork that turns stolen cargo into legitimate cargo. She smiles like a signature.', 'zone_corp_boardroom', NULL, '{"bye":{"text":"\"Do come back when you''ve something worth laundering.\"","options":[]},"root":{"text":"Merrow closes a folio and offers a smile with nothing behind it. \"Consignment, insurance, and provenance — I make cargo legitimate, which is a different thing from making it legal. What are we moving today?\"","options":[{"next":"__shop__","label":"Show me the paperwork."},{"next":"bye","label":"Nothing today."}]}}'::jsonb, '[{"price":35,"item_id":"item_travel_permit"},{"price":24,"item_id":"item_id_papers"},{"price":100,"item_id":"item_contraband_crate"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a knife-sharp charcoal suit","a shell-silk blouse","the quiet luxury of the truly insulated"]}'::jsonb, '{}'::jsonb, 'zone_corp_boardroom', NULL, 'zone_corp_boardroom', '[]'::jsonb, 18, 18, 'female', '[{"item_id":"item_travel_permit"},{"item_id":"item_id_papers"},{"item_id":"item_contraband_crate"}]'::jsonb, 8, 1, 420, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'The Consignment House', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_water_warden', 'The Water Warden', 'A broad woman in a rubber apron who runs the taps like a border crossing. She has personally memorised who owes what, and to whom.', 'zone_civ_meltwater', NULL, '{"bye":{"text":"\"Mind the queue.\"","options":[]},"root":{"text":"The Water Warden eyes your canteen. \"Clean water, five creds a bottle. Refills if you brought your own. Line forms behind you.\"","options":[{"next":"__shop__","label":"Show me what you''ve got."},{"next":"bye","label":"Later."}]}}'::jsonb, '[{"price":5,"item_id":"item_water_bottle"},{"price":15,"item_id":"canteen"},{"price":10,"item_id":"item_ration"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a heavy rubber apron","a patched utility jumpsuit","a sweat-grey undershirt"]}'::jsonb, '{}'::jsonb, 'zone_civ_meltwater', NULL, 'zone_civ_meltwater', '[]'::jsonb, 20, 20, 'female', '[{"item_id":"item_water_bottle"},{"item_id":"canteen"},{"item_id":"item_ration"}]'::jsonb, 8, 1, 60, 'vendor', '{"fri":[{"to":24,"from":6}],"mon":[{"to":24,"from":6}],"sat":[{"to":24,"from":6}],"sun":[{"to":24,"from":6}],"thu":[{"to":24,"from":6}],"tue":[{"to":24,"from":6}],"wed":[{"to":24,"from":6}]}'::jsonb, 0, 'The Meltwater Tap', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_clinkerman', 'The Clinkerman', 'A stooped scavenger-broker who works a cart of sorted salvage out here where the machine-shells den. Grease-black to the elbow, eyes like ball bearings.', 'zone_waste_grit', NULL, '{"bye":{"text":"\"Grey keeps. I''ll be here.\"","options":[]},"root":{"text":"The Clinkerman spreads grease-black hands over a cart of sorted salvage. \"Buyin'' scrap, sellin'' worse. What''re you carryin''?\"","options":[{"next":"__shop__","label":"Let''s trade."},{"next":"bye","label":"Nothing today."}]}}'::jsonb, '[{"price":4,"item_id":"item_scrap_metal"},{"price":8,"item_id":"item_salvaged_wiring"},{"price":14,"item_id":"item_cracked_capacitor"},{"price":10,"item_id":"item_ration"},{"price":15,"item_id":"canteen"},{"price":28,"item_id":"item_rusty_knife"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a coat of stitched tarp and wire","layers of grease-stiff rags","whatever was underneath, best not asked"]}'::jsonb, '{}'::jsonb, 'zone_waste_grit', NULL, 'zone_waste_grit', '[]'::jsonb, 22, 22, 'male', '[{"item_id":"item_scrap_metal"},{"item_id":"item_salvaged_wiring"},{"item_id":"item_cracked_capacitor"},{"item_id":"item_ration"},{"item_id":"canteen"},{"item_id":"item_rusty_knife"}]'::jsonb, 10, 1, 220, 'vendor', '{"fri":[{"to":24,"from":6}],"mon":[{"to":24,"from":6}],"sat":[{"to":24,"from":6}],"sun":[{"to":24,"from":6}],"thu":[{"to":24,"from":6}],"tue":[{"to":24,"from":6}],"wed":[{"to":24,"from":6}]}'::jsonb, 0, 'The Clinkerman''s Cart', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_registrar', 'The Registrar', 'A precise, papery woman who has outlasted the department she serves. She still stamps, files, and disapproves as if any of it will be audited.', 'zone_civ_ledger', NULL, '{"bye":{"text":"\"Do mind the filing.\"","options":[]},"root":{"text":"The Registrar peers over cracked spectacles. \"Records office. Mostly closed. Mostly. Was there something on file?\"","options":[{"next":"quest_offer","label":"Anything I can do?"},{"next":"bye","label":"Nothing."}]},"accepted":{"text":"\"Grime Row, The Bailey — the low, bad end of the wastes. Mind the ash, and mind the wight.\"","actions":[{"action":"START_QUEST","quest_id":"quest_paper_trail"}],"options":[{"next":"bye","label":"Understood."}]},"reported":{"text":"\"...Filed. Recovered. You''re in the ledger now, for whatever that''s worth. Take this for your trouble — and my thanks, off the record.\"","actions":[{"action":"TURN_IN","quest_id":"quest_paper_trail"}],"options":[{"next":"bye","label":"Obliged."}]},"quest_offer":{"text":"\"Something''s denning on a spool of lost citizen records out in the deep wastes — a slag wight, by the heat of it. Put it down so my people can recover the file, and I''ll see you''re paid and, more importantly, registered as helpful.\"","options":[{"next":"accepted","label":"I''ll deal with it."},{"next":"reported","label":"I''ve dealt with it. (report back)"},{"next":"bye","label":"Not now."}]}}'::jsonb, NULL, 0, '{"personality":"clerk","clothing_layers":["a threadbare municipal blazer","a high-collared blouse","sensible, joyless underthings"]}'::jsonb, '{}'::jsonb, 'zone_civ_ledger', NULL, 'zone_civ_ledger', '["The Registrar squares a stack of paper that is already square.","\"Everything is on file. Somewhere. In theory.\""]'::jsonb, 16, 16, 'female', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_precinct_guard', 'Detention Officer Kohl', 'A block of a man in Precinct 9 body armor, thumbs hooked in his belt beside a baton and a zip-tie dispenser. He watches the holding block on a bank of monitors and processes the overnight guests one at a time, without hurry and without interest.', 'zone_mq_precinct_lobby', 'SPECTER-PD', '{}'::jsonb, '[]'::jsonb, 0, '{"police":true,"essential":true}'::jsonb, '{}'::jsonb, 'zone_mq_precinct_lobby', NULL, NULL, '[]'::jsonb, 60, 60, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_almoner', 'The Almoner', 'A tired man of no discernible faith who keeps the breadline moving. He ladles grey nutrient paste with the steadiness of someone who has stopped expecting thanks.', 'zone_civ_commons', NULL, '{"bye":{"text":"\"Move down.\"","options":[]},"root":{"text":"The Almoner ladles something grey into a dented cup and offers it without looking up. \"Everyone eats. Even you. Move down when you''re done.\"","options":[{"next":"bye","label":"Thanks."}]}}'::jsonb, NULL, 0, '{"personality":"charity","clothing_layers":["a stained volunteer''s tabard","a shapeless grey sweater","long johns gone soft with age"]}'::jsonb, '{}'::jsonb, 'zone_civ_commons', NULL, 'zone_civ_commons', '["The Almoner ladles another grey portion and does not look up.","\"Everyone eats. That''s the whole sermon.\""]'::jsonb, 16, 16, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_sorting_bot', 'Sorting Unit 9', 'A belt-mounted sorting automaton, one optic cracked, that never received the order to stop. It stamps, routes, and returns to sender with tireless, pointless devotion.', 'zone_civ_sortation', NULL, '{"bye":{"text":"\"PROCESSING. PLEASE HOLD. INDEFINITELY.\"","options":[]},"root":{"text":"SORTING UNIT 9 swivels its cracked optic toward you. \"PARCEL? ...NO PARCEL. RETURN TO SENDER.\"","options":[{"next":"bye","label":"...okay."}]}}'::jsonb, NULL, 0, '{"personality":"robot","clothing_layers":["a riveted municipal chassis","faded MAIL/POST livery","exposed conduit and a single blinking status LED"]}'::jsonb, '{}'::jsonb, 'zone_civ_sortation', NULL, 'zone_civ_sortation', '["SORTING UNIT 9 stamps a parcel addressed to a crater.","\"RETURN. TO. SENDER.\"","A belt of dead-letter parcels crawls past, endless."]'::jsonb, 30, 30, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_financier', 'a freight financier', 'A freight futures trader who owns a dozen ships he has never seen and cargoes that may not exist, and is, on paper, immensely wealthy. On paper.', 'zone_corp_investor', NULL, '{"bye":{"text":"He has already looked away.","options":[]},"root":{"text":"The financier glances at you, prices you instantly, and finds the figure disappointing. \"Unless you''re carrying a bill of lading, we''ve nothing to discuss.\"","options":[{"next":"bye","label":"...right."}]}}'::jsonb, NULL, 0, '{"personality":"corporate","clothing_layers":["a sharp, forgettable suit","a shirt the colour of a spreadsheet","socks that cost more than your boots"]}'::jsonb, '{}'::jsonb, 'zone_corp_investor', NULL, 'zone_corp_investor', '["The financier sells a shipment short and toasts himself with someone else''s drink.","\"It''s not gambling if you insure both outcomes.\"","\"Everything on that yard is a number to me. Pleasant, isn''t it?\""]'::jsonb, 14, 14, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_bourse_broker', 'Quill', 'A floor broker on the Bourse who trades in anything with a price, which is everything. He speaks in offers and hears in counters, and has never once in his life said a round number.', 'zone_nc_bourse', NULL, '{"bye":{"text":"\"Watchers become buyers. I''ll be here.\"","options":[]},"root":{"text":"Quill clocks you mid-shout and drops his voice to a purr. \"Buying or selling? Everything on this floor is one or the other, including the people. What''ll it be — paper, product, or a position?\"","options":[{"next":"__shop__","label":"Show me your book."},{"next":"bye","label":"Just watching."}]}}'::jsonb, '[{"price":60,"item_id":"item_bearer_bond"},{"price":100,"item_id":"item_contraband_crate"},{"price":35,"item_id":"item_travel_permit"},{"price":22,"item_id":"item_drink_embassy_reserve"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a trading-floor jacket in house colours","a shirt damp with the day","braces holding up more than trousers"]}'::jsonb, '{}'::jsonb, 'zone_nc_bourse', NULL, 'zone_nc_bourse', '[]'::jsonb, 18, 18, 'male', '[{"item_id":"item_bearer_bond"},{"item_id":"item_contraband_crate"},{"item_id":"item_travel_permit"},{"item_id":"item_drink_embassy_reserve"}]'::jsonb, 8, 1, 520, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'The Bourse', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_pd_officer', 'Sergeant Vale', 'Sergeant Vale leans against the kiosk, coffee in one hand, the other never far from the sidearm. Their eyes do the arithmetic on everyone who walks past.', 'zone_apt_1', NULL, '{"end":{"text":"''Move along.''","options":[]},"sub":{"text":"''Hand me the chip. If it''s chargeable, there''s a bounty in it for you.'' (use: submit <datachip>)","options":[{"next":"end","label":"Right."}]},"root":{"text":"''SPECTER-PD. You got something for me, or you just loitering?''","options":[{"next":"sub","label":"I have footage to submit."},{"next":"bribe","label":"How much to lose a charge?"},{"next":"end","label":"Nothing."}]},"bribe":{"text":"''...Petty heat only. And it''ll cost you. Don''t make it weird.'' (use: bribe)","options":[{"next":"end","label":"Understood."}]}}'::jsonb, '[]'::jsonb, 0, '{"police":true,"personality":"police","clothing_layers":["a surplus tac-vest stencilled POLICE","a navy uniform shirt","a plain bra and panties"]}'::jsonb, '{}'::jsonb, 'zone_apt_1', NULL, NULL, '["Vale sips coffee and watches the street.","''Stay clean and we stay friendly.''"]'::jsonb, 30, 30, 'female', '[]'::jsonb, 0, 0, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_jerry_rosenberg', 'Jerry Rosenberg', 'A broadcast studio host.', 'zone_dock_slip', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_consul', 'Consul Reyes', 'A career corporate diplomat who has negotiated three ceasefires and broken all of them personally. She is unfailingly gracious, which is how you know to be afraid.', 'zone_nc_consulate', NULL, '{"bye":{"text":"\"Do give my regards to no one in particular.\"","options":[]},"root":{"text":"Consul Reyes turns to you with a smile of flawless, weaponised courtesy. \"You have the look of someone who resolves things off the record. As it happens, I have a thing that requires resolving. Off the record.\"","options":[{"next":"quest_offer","label":"Go on."},{"next":"bye","label":"Not today."}]},"accepted":{"text":"\"Marvellous. Oxide Flats and the Downwind, just past the Manifold''s edge. Do be discreet; the whole point of downwind is that no one sees it.\"","actions":[{"action":"START_QUEST","quest_id":"quest_downwind"}],"options":[{"next":"bye","label":"Understood."}]},"reported":{"text":"\"...The signing ground is clean, the delegates none the wiser, and everyone will take credit but you. Which is precisely why I''m paying you in a bond that names no one. We understand each other.\"","actions":[{"action":"TURN_IN","quest_id":"quest_downwind"}],"options":[{"next":"bye","label":"Obliged."}]},"quest_offer":{"text":"\"We dump our unpleasantness downwind, as one does, and something has moved into it — slag wights, fouling the very ground where a rather important accord is to be signed outdoors, for the optics. Clear two of them before the signing and the Concordat will remember you fondly, in bond form.\"","options":[{"next":"accepted","label":"Consider it cleared."},{"next":"reported","label":"It''s handled. (report back)"},{"next":"bye","label":"Find someone else."}]}}'::jsonb, NULL, 0, '{"personality":"official","clothing_layers":["an immaculate consular coat with a discreet corporate pin","a high silk collar","the armour of the perfectly composed"]}'::jsonb, '{}'::jsonb, 'zone_nc_consulate', NULL, 'zone_nc_consulate', '["Consul Reyes greets someone she is currently undermining with genuine warmth.","\"Diplomacy is simply war with better catering.\""]'::jsonb, 18, 18, 'female', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_attache', 'a consular attaché', 'A junior attaché who carries other people''s secrets in a locked case and their coffee in the other hand, and is quietly better informed than anyone he serves.', 'zone_nc_ivory', NULL, '{"bye":{"text":"He is already elsewhere in spirit.","options":[]},"root":{"text":"The attaché gives you the smile of a man trained to reveal nothing. \"I''m afraid the Consul is unavailable, whoever you''re looking for is unavailable, and this conversation is, ideally, also unavailable.\"","options":[{"next":"bye","label":"...noted."}]}}'::jsonb, NULL, 0, '{"personality":"official","clothing_layers":["a well-cut but off-the-rack suit","a shirt ironed in a hurry","the shoes of a man who walks a great deal for others"]}'::jsonb, '{}'::jsonb, 'zone_nc_ivory', NULL, 'zone_nc_ivory', '["The attaché checks a discreet earpiece and rearranges his face into neutrality.","\"I couldn''t possibly say. I could, but I couldn''t.\"","\"Everyone up here is lying. The trick is knowing about what.\""]'::jsonb, 14, 14, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_prospector', 'a slag prospector', 'A lean, coughing man who works the scrap mesa with a bent rake and a rad-band he stopped looking at weeks ago. He is convinced the seam he''s found will make him rich, and he is running out of the time it would take to spend it.', 'zone_waste_scrapmesa', NULL, '{"bye":{"text":"He is already raking again, ticking softly to himself.","options":[]},"root":{"text":"The prospector barely looks up from his rake. \"Claim''s mine, if that''s what you''re wondering. Whole mesa''s mine. Found the seam, didn''t I. You want a piece, you dig your own — plenty of mesa, plenty of...\" he coughs, \"...plenty of time.\"","options":[{"next":"bye","label":"Good luck with the seam."}]}}'::jsonb, NULL, 0, '{"personality":"lowlife","clothing_layers":["a filthy dust-cloak stiff with grit","a scarf pulled up against the ash","fingerless gloves worn through at every tip"]}'::jsonb, '{}'::jsonb, 'zone_waste_scrapmesa', NULL, 'zone_waste_scrapmesa', '["The prospector hacks a wet cough into his scarf and keeps raking.","\"One good seam. That''s all a man needs. One good seam.\"","\"You hear that ticking? Course you don''t. You get used to it.\""]'::jsonb, 16, 16, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_dockhand', 'Pell', 'A wiry stevedore who has hauled the same quays for twenty years and has opinions about all of them. Rope-scarred hands, a roll-up welded to his lip.', 'zone_dock_quays', NULL, '{"bye":{"text":"\"Then pass. Mind the nets.\"","options":[]},"root":{"text":"Pell drops his end of a crate and wipes his hands. \"You lost, or just in the way?\"","options":[{"next":"bye","label":"Just passing."}]}}'::jsonb, NULL, 0, '{"personality":"labourer","clothing_layers":["a hi-vis vest gone the colour of nothing","a thermal shirt","work trousers and steel-caps"]}'::jsonb, '{}'::jsonb, 'zone_dock_quays', NULL, 'zone_dock_quays', '["Pell shoulders a coil of rope and grunts a greeting.","\"Tide''s turning. You can smell it, if you''ve got the nose.\"","\"Don''t go past the Slip after dark. That''s all I''ll say.\""]'::jsonb, 16, 16, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_precinct_officer_3', 'Detention Officer Marlow', 'Broad, slow-blinking, and built like a vending machine, Marlow works the graveyard rotation. He''s processed enough overnight guests that nothing surprises him and nobody argues twice. His baton has a name. He won''t tell you what it is.', 'zone_mq_precinct_lobby', 'SPECTER-PD', '{}'::jsonb, '[]'::jsonb, 0, '{"police":true,"essential":true,"personality":"police","clothing_layers":["a patched patrol jacket with a dulled badge","a department-issue undershirt","issue boxer shorts"]}'::jsonb, '{}'::jsonb, 'zone_mq_precinct_lobby', NULL, NULL, '["Marlow cracks his knuckles one at a time, watching the cells.","\"Sleep it off. Doors open when the clock says so, not when you do.\""]'::jsonb, 60, 60, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_slake', 'Slake', 'A rad-scarred former smelter-hand who runs the last shop before the Redline out of a cracked kiln, selling the gear that keeps the counter quiet. Half her face is a burn map and all of her advice is worth taking.', 'zone_waste_brokenkiln', NULL, '{"bye":{"text":"\"Keep the counter in your ear and the wind at your back. West of here, neither''s a suggestion.\"","options":[]},"root":{"text":"Slake looks you over with the eye that still works and reads your odds in a glance. \"You''re either lost or you''re going west. Either way you''ll want what I sell before you do. Counters, RadAway, a kit for when the RadAway''s too late. Buying, bleeding, or brave?\"","options":[{"next":"__shop__","label":"Show me the gear."},{"next":"work","label":"Anything need doing out here?"},{"next":"capstone","label":"What’s in the core itself?"},{"next":"bye","label":"Just passing."}]},"work":{"text":"Her jaw tightens. \"As it happens. The muties den past the Meltline, always have — but lately they''re coming this side of it, toward my kiln, toward my customers. Put two of them down out there, at the Meltline or in Vex Hollow, and I''ll square you in the only currency that matters out here: something to keep you alive.\"","options":[{"next":"accepted","label":"I''ll thin them out."},{"next":"reported","label":"Already done. (report back)"},{"next":"bye","label":"Not my problem."}]},"accepted":{"text":"\"West, past the fused rail. You''ll know the Meltline by the way your teeth start aching. Vex Hollow''s just inside it — that''s where they den thickest. Two''s enough to make the rest reconsider. Don''t be a hero; heroes glow.\"","actions":[{"action":"START_QUEST","quest_id":"quest_meltline"}],"options":[{"next":"bye","label":"Two it is."}]},"capstone":{"text":"Something shutters behind her working eye. \"The core. The killing floor, right at the top of the world. I''ve sold gear to every fool who went west to see it and I''ve inventory to spare because none of them came back to spend the rest. There''s a thing up there — the Redline bred it to rule the place. It ticks. You can hear its heart from across the floor.\" She studies you. \"If you''re set on dying, do it useful. Bring me that heart. Proof the floor can be touched. I''ll pay what a thing like that is worth, which is: everything I''ve got and a debt besides.\"","options":[{"next":"cap_accept","label":"I''ll bring you its heart."},{"next":"cap_report","label":"I''ve got it here. (report back)"},{"next":"bye","label":"Not for all the credits out here."}]},"reported":{"text":"Slake nods slowly, the working half of her face almost approving. \"The counter''s quieter tonight. Won''t last, nothing does out here — but it''ll last long enough. Here. Take the pills; you''ve earned the years they''ll buy you back.\"","actions":[{"action":"TURN_IN","quest_id":"quest_meltline"}],"options":[{"next":"bye","label":"Obliged, Slake."}]},"cap_accept":{"text":"\"Then go up the neck, past Vex Hollow, past Marrow Row where the larder is, out onto the open floor. It holds court there over the bones of everyone who tried this before you. Kill it, cut the heart, come back. If you come back. Wear both bands and don''t stop moving.\" She almost smiles. \"I''ll keep the fire lit.\"","actions":[{"action":"START_QUEST","quest_id":"quest_redline_core"}],"options":[{"next":"bye","label":"Keep it lit."}]},"cap_report":{"text":"Slake takes the heart in both hands — still ticking, still warm — and for a long moment says nothing at all, the burn-mapped half of her face unreadable and the rest of it something close to awe. \"Then it can be touched. After all of them. After all these years.\" She sets it reverently on the counter, where it ticks between you. \"Everything I''ve got, I said. Take it. And take this too: you''re the only one I''ve ever had to pay. Go careful. You''ve spent enough.\"","actions":[{"action":"TURN_IN","quest_id":"quest_redline_core"}],"options":[{"next":"bye","label":"I spent it well."}]}}'::jsonb, '[{"price":25,"item_id":"item_rad_band"},{"price":25,"item_id":"item_rad_pills"},{"price":55,"item_id":"item_medkit"},{"price":70,"item_id":"item_precursor_stim"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a lead-lined smelter''s apron gone stiff with age","layered rags against the wind","a rad-band on each wrist, both ticking"]}'::jsonb, '{}'::jsonb, 'zone_waste_brokenkiln', NULL, 'zone_waste_brokenkiln', '[]'::jsonb, 24, 24, 'female', '[{"item_id":"item_rad_band"},{"item_id":"item_rad_pills"},{"item_id":"item_medkit"},{"item_id":"item_precursor_stim"}]'::jsonb, 8, 1, 300, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'The Last Kiln', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_culvert_wretch', 'a culvert wretch', 'A wretch who lives deep in the culvert''s mouth, wrapped in everything she owns, guarding a small fire and a smaller hope. She has been west, once, and it is the only thing she will talk about and the last thing she wants to.', 'zone_waste_culvert', NULL, '{"bye":{"text":"She turns back to her fire, done with you and with everything.","options":[]},"root":{"text":"The wretch pulls her coats tighter and eyes you from beside her fire. \"You''re headed west, I can see it on you, you''ve got the look — the not-yet-scared look. I had it too. Warm yourself if you want. Then turn around.\"","options":[{"next":"west","label":"What’s west?"},{"next":"bye","label":"I’ll keep moving."}]},"west":{"text":"Her eyes go somewhere else for a moment. \"The neck. The killing floor above it. The things the neck lets down. I went up it on a dare and a full stomach and came back on my hands. Left something up there I''m not getting back. Don''t make it two of us.\"","options":[{"next":"bye","label":"...I hear you."}]}}'::jsonb, NULL, 0, '{"personality":"lowlife","clothing_layers":["a bundle of stolen coats worn all at once","rags bound at the wrist and ankle against the wind","a blanket that is more hole than blanket"]}'::jsonb, '{}'::jsonb, 'zone_waste_culvert', NULL, 'zone_waste_culvert', '["The culvert wretch feeds a splinter to her small fire and watches it go.","\"Don''t go west. That''s all. Don''t.\"","\"I went west once. I came back less. Ask me nothing else.\""]'::jsonb, 14, 14, 'female', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_juno_kael', 'Juno Kael', 'Juno Kael is tall and angular, her hair dye growing out in a gradient from platinum to black root. She wears a faded Dead Space Interiors polo shirt tucked into cargo trousers. She tracks you with the patient, evaluating attention of someone who has spent a lot of time waiting for browsers to become buyers.', 'zone_furniture_store', NULL, '{"end":{"text":"''Take your time.'' She goes back to her clipboard.","options":[]},"root":{"text":"Juno looks up from a clipboard of handwritten inventory tallies. ''Browse or buy — I don''t care which, as long as you don''t sit on everything without committing. What can I do for you?''","options":[{"next":"looking","label":"I''m looking for furniture."},{"next":"what_is_this","label":"What is this place?"},{"next":"pricing","label":"How does pricing work?"},{"next":"__shop__","label":"Browse your wares."},{"next":"end","label":"Nothing, just looking."}]},"looking":{"text":"''Good. Everything in here is functional, everything has a story, and most of the stories are better than the things in the showroom right now.'' She gestures at the vignettes behind her. ''Stock rotates. If you don''t see what you want today, come back tomorrow.''","options":[{"next":"__shop__","label":"Show me what you''ve got."},{"next":"end","label":"I''ll look around."}]},"pricing":{"text":"''Prices are what they are. The mag-lev stuff costs what it costs because the components aren''t made anymore and the patent holders are suing each other into dust. The surplus cots are cheap because they''re surplus. I don''t negotiate down — I might negotiate trade.''","options":[{"next":"root","label":"Fair enough."},{"next":"__shop__","label":"Let me see the inventory."}]},"what_is_this":{"text":"''Dead Space Interiors. I took the name from the lease — the building code still says DEAD SPACE on the fire certificate. Seemed honest.'' She taps the clipboard. ''I source from estate sales, corporate liquidations, lab clearances. If something''s in here it works or it''s interesting. Usually both.''","options":[{"next":"root","label":"Sounds like my kind of place."},{"next":"__shop__","label":"Show me what you''ve got."}]}}'::jsonb, '[{"price":2400,"item_id":"item_furn_mag_lev_chair"},{"price":4800,"item_id":"item_furn_haptic_throne"},{"price":180,"item_id":"item_furn_corpcore_bench"},{"price":650,"item_id":"item_furn_diner_booth"},{"price":60,"item_id":"item_furn_barstool_wreck"},{"price":320,"item_id":"item_furn_pneumatic_stool"},{"price":890,"item_id":"item_furn_meditation_pod"},{"price":3200,"item_id":"item_furn_neural_couch"},{"price":120,"item_id":"item_furn_busted_sofa"},{"price":6500,"item_id":"item_furn_sleep_pod"},{"price":95,"item_id":"item_furn_mil_surplus_cot"},{"price":75,"item_id":"item_furn_pipe_railing"},{"price":40,"item_id":"item_furn_payphone_husk"},{"price":780,"item_id":"item_furn_counter_slab"},{"price":3600,"item_id":"item_furn_nano_desk"},{"price":5200,"item_id":"item_furn_wallscreen"},{"price":280,"item_id":"item_furn_crt_relic"},{"price":4100,"item_id":"item_furn_holo_projector"},{"price":1600,"item_id":"item_furn_ruggedized_monitor"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a many-pocketed utility coat","a faded company tee knotted at the waist","a worn bra and briefs"]}'::jsonb, '{}'::jsonb, 'zone_furniture_store', NULL, NULL, '["Juno makes a note on her clipboard without looking up.","''Half of this came from a corporate office liquidated in forty-eight hours. Surprising what people leave behind when security cuts their badge.''","She straightens a price tag that didn''t need straightening.","''The sleep pod''s the best thing in here. I tested it myself. Didn''t want to get up. That''s a good sign.''","''Stock rotates every day. Yesterday I had three mag-lev chairs. Now I have one.''","''I''m not a decorator. I''m a vendor. If you want to know if it''ll hold your weight, I can help.''"]'::jsonb, 20, 20, 'female', '[{"item_id":"item_furn_mag_lev_chair"},{"item_id":"item_furn_haptic_throne"},{"item_id":"item_furn_corpcore_bench"},{"item_id":"item_furn_diner_booth"},{"item_id":"item_furn_barstool_wreck"},{"item_id":"item_furn_pneumatic_stool"},{"item_id":"item_furn_meditation_pod"},{"item_id":"item_furn_neural_couch"},{"item_id":"item_furn_busted_sofa"},{"item_id":"item_furn_sleep_pod"},{"item_id":"item_furn_mil_surplus_cot"},{"item_id":"item_furn_pipe_railing"},{"item_id":"item_furn_counter_slab"},{"item_id":"item_furn_nano_desk"},{"item_id":"item_furn_wallscreen"},{"item_id":"item_furn_crt_relic"},{"item_id":"item_furn_holo_projector"},{"item_id":"item_furn_ruggedized_monitor"}]'::jsonb, 10, 1, 12826, 'npc', '{"fri":[{"to":18,"from":9}],"mon":[{"to":18,"from":9}],"sat":[{"to":18,"from":9}],"sun":[{"to":18,"from":9}],"thu":[{"to":18,"from":9}],"tue":[{"to":18,"from":9}],"wed":[{"to":18,"from":9}]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_vane', 'Vane', 'A poised, unreadable bartender who runs the Aerie''s floor like a chess clock. She remembers every drink, every debt, and every indiscretion, and files them all somewhere you will never reach.', 'zone_nc_halcyon', NULL, '{"bye":{"text":"\"The view''s complimentary. Everything else is not.\"","options":[]},"root":{"text":"The bartender sets down a glass she was already polishing and takes your measure in one clean sweep. \"The Aerie. Members and their curiosities only — which, tonight, apparently means you. Drink? Or something more interesting?\"","options":[{"next":"quest_offer","label":"Something more interesting."},{"next":"bye","label":"Just the view."}]},"accepted":{"text":"\"It sounds the deepest water — off The Wreck, out over The Deep. Go heavy, and come back, ideally. The members do so hate an anticlimax.\"","actions":[{"action":"START_QUEST","quest_id":"quest_leviathan_bounty"}],"options":[{"next":"bye","label":"Understood."}]},"reported":{"text":"\"...The deep''s gone quiet. The members felt it from up here, believe it or not. Your fee — and a standing tab, which up here is the higher honour by far.\"","actions":[{"action":"TURN_IN","quest_id":"quest_leviathan_bounty"}],"options":[{"next":"bye","label":"Obliged."}]},"quest_offer":{"text":"\"The members are bored, and bored money does harm. So we''re... privately sponsoring a hunt. There''s a thing in the deep water — the leviathan, the big one the lurkers come from. Bring me proof it''s dead and the sponsors pay very, very well. Discretion included.\"","options":[{"next":"accepted","label":"I''ll hunt it."},{"next":"reported","label":"It''s dead. (collect)"},{"next":"bye","label":"Pass."}]}}'::jsonb, '[{"price":14,"item_id":"item_drink_glow_cocktail"},{"price":22,"item_id":"item_drink_embassy_reserve"},{"price":9,"item_id":"item_drink_rust_whiskey"},{"price":5,"item_id":"item_water_bottle"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a sharply cut black bar-jacket","a crisp collarless shirt","tailored, invisible foundations"]}'::jsonb, '{}'::jsonb, 'zone_nc_halcyon', NULL, 'zone_nc_halcyon', '["Vane polishes a glass that was already clean and watches the door.","\"Up here, the weather is a rumour and so is everyone else.\"","\"A member once asked me the time. I told them it was whatever they preferred.\""]'::jsonb, 20, 20, 'female', '[{"item_id":"item_drink_glow_cocktail"},{"item_id":"item_drink_embassy_reserve"},{"item_id":"item_drink_rust_whiskey"},{"item_id":"item_water_bottle"}]'::jsonb, 8, 1, 300, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'The Aerie', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_gantry_lookout', 'a gantry lookout', 'A wiry scavenger perched high in the rusted gantry with a spyglass and a whistle, paid in salvage-shares to watch the western dark and call it when something comes out of it. He has good eyes and a worse imagination, and out here the imagination is usually right.', 'zone_waste_gantry', NULL, '{"bye":{"text":"He is already glassing the dark again, whistle between his teeth.","options":[]},"root":{"text":"The lookout doesn''t lower his glass. \"Camp pays me to watch west and whistle when it moves, so that''s what I do. You''re going out there? Then do me the courtesy of being visible, so when you don''t come back I can log why. Keep to the slag bar. Off it, the dust''ll have you.\"","options":[{"next":"bye","label":"I’ll keep to the bar."}]}}'::jsonb, NULL, 0, '{"personality":"lowlife","clothing_layers":["a wind-shredded scav coat lashed down with cable","goggles pushed up on a soot-black brow","fingerless gloves and a whistle on a cord"]}'::jsonb, '{}'::jsonb, 'zone_waste_gantry', NULL, 'zone_waste_gantry', '["The lookout sweeps his spyglass across the western wastes and holds his breath.","\"Something''s always coming. Trick''s calling it before it arrives.\"","\"You go west, I''ll whistle for you. That''s a promise and a warning both.\""]'::jsonb, 16, 16, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_1782945871225', 'Deacon Pell', 'A gaunt man in a Custodian cassock with the Architect sigil unpicked from the chest — the thread holes still trace its outline. He walks like he''s late for a service that ended years ago, lips moving through liturgy nobody asked for.', 'zone_city_north', NULL, '{"root":{"text":"Deacon Pell stops mid-mutter and fixes you with eyes like burnt-out filaments. \"You''re not here for a sermon. Nobody is. So what?\"","options":[{"next":"architect","label":"Is the Architect really dead?"},{"next":"custodians","label":"Weren''t you a Custodian?"},{"next":"walking","label":"Why do you keep walking the circuit?"},{"next":null,"label":"Never mind, Deacon."}]},"walking":{"text":"\"The route was holy once. Threshold to the Strip, the Row, the Gate, back again. Somebody has to keep the shape of it.\" He almost smiles. \"Besides — the day I stop, I''ll have to think about all of it. No thank you.\"","options":[{"next":"root","label":"Back"}]},"architect":{"text":"\"Dead. Watching. Ascended. Bored.\" He shrugs. \"The power''s on, the water runs, and nobody''s home when you pray. Pick whichever word lets you sleep.\"","options":[{"next":"root","label":"Back"}]},"custodians":{"text":"He touches the thread holes where the sigil used to be. \"Thirty years keeping the substations blessed and the relays clean. Then I asked it one question — just one — and got the same silence the Breakers get. At least their silence is honest.\"","options":[{"next":"root","label":"Back"}]}}'::jsonb, '[]'::jsonb, 0, '{"mis_willing":false}'::jsonb, '{"nodes":{"start":{"next":"patrol","type":"start"},"linger":{"next":"patrol","type":"wait","seconds":30},"patrol":{"next":"sermon","type":"action","params":{"loop":true,"mode":"walk","waypoints":["zone_city_north","zone_city_ne","zone_city_east","zone_city_se","zone_city_south","zone_city_west","zone_velk_exterior","zone_drum_exterior","zone_thresholdeast"]},"action_type":"PATROL"},"sermon":{"next":"linger","type":"action","params":{"message":"mutters: \"...and the grid shall provide, and the grid provided, and we called it mercy because we didn''t have a better word...\"","cooldown_s":120},"action_type":"SAY"}},"_start":"start"}'::jsonb, 'zone_threshold', NULL, NULL, '["Keep walking. It''s what I do.","\"It listens. It just stopped answering.\"","\"I gave it forty years. It gave me this coat.\"","\"The lampposts still hum the old hymns. Nobody else hears it.\"","\"Custodians say faith. I say habit with better posture.\"","\"You want a blessing? The water''s off on Thursdays. That''s the blessing.\"","\"I unpicked the sigil myself. Took all night. Felt nothing.\"","\"The Basin stays lit. That''s not love. That''s momentum.\"","\"Keep walking. It''s what I do.\""]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{"fri":[],"mon":[],"sat":[],"sun":[],"thu":[],"tue":[],"wed":[]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_marta_velk', 'Marta Velk', 'A stocky woman in her fifties with calloused hands and a permanent evaluating squint, like she''s appraising everything for resale value. A vendor''s lanyard hangs crooked around her neck. She smells like oil soap and synth-leather.', 'zone_velk_exterior', NULL, '{"bye":{"text":"\"Don''t let the door hit you. Actually, it might — the hinge is shot. I keep meaning to fix that.\"","options":[]},"root":{"text":"Velk wipes her hands on a rag that only makes them dirtier. \"You buying or just looking? Either way, don''t sit on anything unless you plan to buy it.\"","options":[{"next":"__shop__","label":"Browse your wares."},{"next":"history","label":"How long have you been here?"},{"next":"sarcasm","label":"Nice place."},{"next":"bye","label":"Nothing, never mind."},{"next":"gossip","label":"Heard anything on the street?"}]},"gossip":{"text":"Marta wipes the counter, weighing what to share.","actions":[{"action":"GOSSIP_TELL"}],"options":[{"next":"root","label":"Back"}]},"history":{"text":"\"Fifteen years in this spot. Before me it was a noodle bar. Before that, rubble. This city''s got layers.\"","options":[{"next":"noodles","label":"What happened to the noodle bar?"},{"next":"__shop__","label":"Browse your wares."},{"next":"bye","label":"See you around."}]},"noodles":{"text":"\"Owner got Custodian debt. You know how that goes. I bought the chair she left behind. Still got it — twelve credits if you want it.\"","options":[{"next":"__shop__","label":"Browse your wares."},{"next":"bye","label":"See you around."}]},"sarcasm":{"text":"\"It ain''t the Meridian, but everything in here works. More than I can say for most things in this city.\"","options":[{"next":"__shop__","label":"Browse your wares."},{"next":"bye","label":"Fair enough. See you around."}]}}'::jsonb, '[]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a many-pocketed utility coat","a faded company tee knotted at the waist","a worn bra and briefs"]}'::jsonb, '{"nodes":{"start":{"next":"check_work","type":"start"},"go_home":{"next":"home_life_ps","type":"action","action_type":"GO_HOME"},"have_life":{"next":"check_work","type":"action","action_type":"HAVE_LIFE"},"check_work":{"next":"have_life","type":"action","ports":{"offWork":"home_idle_ps","endShift":"go_home","goToWork":"go_to_work","haveLife":"have_life"},"action_type":"CHECK_VENDOR_WORK"},"go_to_work":{"next":"vendor_chitchat","type":"action","action_type":"GO_TO_WORK"},"home_idle_ps":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"home_life_ps":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"vendor_chitchat":{"next":"check_work","type":"action","action_type":"VENDOR_CHITCHAT"}},"_start":"start"}'::jsonb, 'zone_meridian_unit_203', NULL, 'zone_velk_shop', '["\"Everything''s got a second life if you know how to look at it.\"","runs a hand along the edge of a battered cabinet, checking for warps","\"You break it, you bought it. That''s the rule. It''s always been the rule.\"","squints at a price tag and decides it should be higher","\"Good wood''s hard to find since the Singe. Synth-board''s everywhere but it warps.\"","stacks two crates with practised efficiency, barely looking","\"I had a couch in here last week. Guy offered me four credits. Four. I told him to get out.\"","taps the side of a lamp three times until it flickers on","\"If it''s broken I''ll fix it. If it''s ugly I''ll price it lower. Comes out the same in the end.\"","exhales slowly and writes something in a worn ledger"]'::jsonb, 30, 30, 'female', '[]'::jsonb, 10, 1, 0, 'vendor', '{"fri":[{"to":22,"from":10}],"mon":[{"to":22,"from":10}],"sat":[{"to":22,"from":10}],"sun":[{"to":22,"from":10}],"thu":[{"to":22,"from":10}],"tue":[{"to":22,"from":10}],"wed":[{"to":22,"from":10}]}'::jsonb, 0, 'Velk''s Pre-Owned Furnishings', '["polishes a second-hand lamp until it gleams","\"Still a deal at half the price.\"","sorts through a box of salvaged drawer handles","sketches something in a notebook, crosses it out, starts again","\"Fifteen years. This chair''s earned its spot.\"","runs a cloth along an old shelf, checking the joints","counts something quietly on her fingers, frowns"]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_cash_vane', 'Cassius Vane', 'A rangy man in a salvaged casino-floor coat, the felt-green lining worn to grey. His jaw is chrome from the cheekbone down — an old repair he never bothered to skin over, so it catches the light when he smiles, which is often and rarely means anything good. He watches hands the way other people watch weather. They call him Cash, mostly because he keeps taking it.', 'zone_yard_weighbridge', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"poker_player":true,"poker_persona":{"buyIn":200,"betSizing":0.6,"bluffFreq":0.18,"tightness":0.5,"tiltProne":0.35,"aggression":0.7,"chattiness":0.6,"semiBluffFreq":0.4},"poker_bankroll":3180}'::jsonb, '{"nodes":{"wait":{"next":"start","type":"wait","seconds":20},"start":{"next":"have_life","type":"start"},"have_life":{"next":"home_check","type":"action","action_type":"HAVE_LIFE"},"home_life":{"next":"wait","type":"action","action_type":"AT_HOME_LIFE"},"home_check":{"type":"condition","ifTrue":"home_life","ifFalse":"wait","condition_type":"AT_HOME"}},"_start":"start"}'::jsonb, 'zone_apt_1', NULL, NULL, '["\"Anybody feel like donating some credits? I take cards, cash, and bad decisions.\"","shuffles a battered deck one-handed, watching the room","\"You look like a caller. I like callers.\"","taps two chips together in a slow, patient rhythm","\"Sit down. The felt won''t bite. Much.\"","rolls a chip across his knuckles and pockets it without looking"]'::jsonb, 25, 25, 'male', '[]'::jsonb, 10, 1, 0, 'gambler', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_embassy_barkeep', 'Lowry Cormack', 'A former concierge, still buttoned into a frayed Embassy vest, polishing a glass that was already clean. Calls every customer "valued guest," sincerity optional.', 'zone_residential_lobby', NULL, '{"menu":{"text":"The Reserve is our signature pour — don''t ask what''s left to age it in. The Swill is also available, for guests with simpler tastes, or none. Canapés are complimentary with a drink. They are not actually complimentary.","options":[{"next":"root","label":"Back"}]},"root":{"text":"Welcome to the Embassy Lounge, valued guest. We maintain certain standards here, within reason. What can I get you?","options":[{"next":"menu","label":"What''s on the menu?"},{"next":"gossip","label":"Any news from the front desk?"},{"next":null,"label":"Never mind."}]},"gossip":{"text":"Lowry lowers his voice to something discreet.","actions":[{"action":"GOSSIP_TELL"}],"options":[{"next":"root","label":"Back"}]}}'::jsonb, '[{"price":22,"stock":15,"item_id":"item_drink_embassy_reserve"},{"price":4,"stock":99,"item_id":"item_drink_basin_swill"},{"price":9,"stock":25,"item_id":"item_embassy_canapes"}]'::jsonb, 0, '{"mis_willing":false,"personality":"bartender","clothing_layers":["a worn leather bar-apron","a tight black tee","black briefs"]}'::jsonb, '{"nodes":{"start":{"next":"have_life","type":"start"},"at_work":{"next":"go_home","type":"action","action_type":"AT_WORK"},"go_home":{"next":"home_wait","type":"action","action_type":"GO_HOME"},"have_life":{"next":"go_to_work","type":"action","action_type":"HAVE_LIFE"},"home_wait":{"next":"start","type":"wait","seconds":60},"go_to_work":{"next":"at_work","type":"action","action_type":"GO_TO_WORK"}},"_start":"start"}'::jsonb, 'zone_meridian_unit_102', NULL, 'zone_residential_lobby', '["What''ll it be?","You look like you''ve had a rough one.","Pay first. Trust later. That''s policy.","You''re not the first person to cry at this bar. Won''t be the last.","I''ve heard worse. Much worse.","Last call was three hours ago. I''m still here.","We''re out of the good stuff. We were always out of the good stuff.","Tab''s running. Keep drinking.","I don''t ask questions. That''s why people come here.","You want ice with that? Funny."]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_reg', 'Reg Naylor', 'A heavyset person behind a scratched counter. Apron: CERTIFIED SURVIVOR.', 'zone_meridian_floor_1', NULL, '{"root":{"text":"You look new. Or you look like you died recently. Hard to tell the difference. What do you need?","options":[{"next":"where","label":"Where am I?"},{"next":"factions","label":"What are the factions?"},{"next":null,"label":"Never mind."}]},"where":{"text":"Coldwater Basin. Used to be a city. Now it''s whatever this is. The Architect''s infrastructure runs under the whole basin — power, water, comms. So it stays livable. Relatively.","options":[{"next":"root","label":"Back"}]},"factions":{"text":"Custodians think the Architect is God. Breakers want to smash everything. Archivists want to know everything. The Franchise wants to sell everything. The Glitch think they can talk to it. None of them are right, probably. Pick the one that''s wrong in a way you can live with.","options":[{"next":"root","label":"Back"}]}}'::jsonb, '[{"price":12,"stock":10,"item_id":"item_ration"},{"price":8,"stock":15,"item_id":"item_water_bottle"},{"price":15,"stock":8,"item_id":"item_bandage"},{"price":300,"item_id":"item_thermex_top"},{"price":130,"item_id":"item_watch_cap"}]'::jsonb, 1, '{"mis_willing":false,"personality":"travelling_vendor","clothing_layers":["a battered oilskin poncho","a layered thermal shirt","grey briefs"]}'::jsonb, '{"nodes":{"start":{"next":"have_life","type":"start"},"at_work":{"next":"go_home","type":"action","action_type":"AT_WORK"},"go_home":{"next":"home_wait","type":"action","action_type":"GO_HOME"},"have_life":{"next":"go_to_work","type":"action","action_type":"HAVE_LIFE"},"home_wait":{"next":"start","type":"wait","seconds":60},"go_to_work":{"next":"at_work","type":"action","action_type":"GO_TO_WORK"}},"_start":"start"}'::jsonb, 'zone_meridian_unit_201', NULL, NULL, '["Another quiet night, too quiet...","Inventory’s running low again, like always.","Everything here has a price, even silence.","That shipment wasn’t supposed to be late...","Funny how the same items keep coming back with different stories.","The terminal''s logging phantom transactions","Somebody’s been through here, can still feel it.","City chews through stock, I can''t keep up!"]'::jsonb, 20, 20, 'male', '[{"item_id":"item_thermex_top"},{"item_id":"item_watch_cap"}]'::jsonb, 10, 1, 0, 'npc', '{"fri":[{"to":23,"from":6}],"mon":[{"to":23,"from":6}],"sat":[{"to":23,"from":6}],"sun":[{"to":23,"from":6}],"thu":[{"to":23,"from":6}],"tue":[{"to":23,"from":6}],"wed":[{"to":23,"from":6}]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_prefect_clerk', 'Prefect Aldous', 'The senior clerk of the Prefecture, a small grey man who has turned the withholding of stamps into a martial art. He can end your day with a shrug and a form number.', 'zone_gov_prefect', NULL, '{"bye":{"text":"\"Then you remain, officially, nobody. Next.\"","options":[]},"root":{"text":"Prefect Aldous looks up over half-moon glasses, unimpressed in advance. \"The Prefecture issues permits, papers, and — occasionally — pardons. Which delay would you like to begin today?\"","options":[{"next":"__shop__","label":"Show me the paperwork."},{"next":"bye","label":"Never mind."}]}}'::jsonb, '[{"price":30,"item_id":"item_travel_permit"},{"price":20,"item_id":"item_id_papers"},{"price":5,"item_id":"item_water_bottle"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a grey civil-service tunic pressed to a razor edge","an ink-cuffed shirt","regulation, joyless underthings"]}'::jsonb, '{}'::jsonb, 'zone_gov_prefect', NULL, 'zone_gov_prefect', '[]'::jsonb, 18, 18, 'male', '[{"item_id":"item_travel_permit"},{"item_id":"item_id_papers"},{"item_id":"item_water_bottle"}]'::jsonb, 8, 1, 120, 'vendor', '{"fri":[{"to":22,"from":6}],"mon":[{"to":22,"from":6}],"sat":[{"to":22,"from":6}],"sun":[{"to":22,"from":6}],"thu":[{"to":22,"from":6}],"tue":[{"to":22,"from":6}],"wed":[{"to":22,"from":6}]}'::jsonb, NULL, 'The Prefecture', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_fishmonger', 'Brack the Fishmonger', 'A slab-armed man with a cleaver and a laugh like a dropped crate. He can fillet a bay-thing before it knows it''s dead and sell you the parts that aren''t glowing.', 'zone_dock_fishmarket', NULL, '{"bye":{"text":"\"Suit yourself. Cats aren''t fussy.\"","options":[]},"root":{"text":"Brack slaps a pale fillet onto the slab. \"Fresh off the bay, mostly fish! Buyin'' your catch too, if it''s got fewer than three eyes.\"","options":[{"next":"__shop__","label":"Show me the catch."},{"next":"bye","label":"Not hungry."}]}}'::jsonb, '[{"price":7,"item_id":"item_fresh_catch"},{"price":10,"item_id":"item_ration"},{"price":5,"item_id":"item_water_bottle"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a gore-stiff rubber apron","a striped fishmonger''s shirt gone grey","sturdy waders"]}'::jsonb, '{}'::jsonb, 'zone_dock_fishmarket', NULL, 'zone_dock_fishmarket', '[]'::jsonb, 20, 20, 'male', '[{"item_id":"item_fresh_catch"},{"item_id":"item_ration"},{"item_id":"item_water_bottle"}]'::jsonb, 8, 1, 90, 'vendor', '{"fri":[{"to":24,"from":6}],"mon":[{"to":24,"from":6}],"sat":[{"to":24,"from":6}],"sun":[{"to":24,"from":6}],"thu":[{"to":24,"from":6}],"tue":[{"to":24,"from":6}],"wed":[{"to":24,"from":6}]}'::jsonb, 0, 'The Fishmarket', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_harbormaster', 'The Harbourmaster', 'A weathered official in a peaked cap she has no authority to wear anymore, keeping ledgers for ships that mostly don''t file. She sees everything on her wharf and reports almost none of it.', 'zone_dock_wharf', NULL, '{"bye":{"text":"\"Keep it that way and we''ll get along.\"","options":[]},"root":{"text":"The Harbourmaster looks up from her ledger. \"You''re not crew, and you''re not cargo. So what are you?\"","options":[{"next":"quest_offer","label":"Looking for work."},{"next":"bye","label":"Nobody in particular."}]},"accepted":{"text":"\"Try the shallows, the moored barges, out past the breakwater. Mind you don''t end up in the ledger of the lost yourself.\"","actions":[{"action":"START_QUEST","quest_id":"quest_wet_cargo"}],"options":[{"next":"bye","label":"Understood."}]},"reported":{"text":"\"...Fewer wakes out there tonight. Good. Here — off the books, like everything else on this wharf. We never spoke.\"","actions":[{"action":"TURN_IN","quest_id":"quest_wet_cargo"}],"options":[{"next":"bye","label":"Obliged."}]},"quest_offer":{"text":"\"Something in the bay''s been taking my dockhands and gnawing my hulls — lurkers, big ones. Thin them out — three, at least — and I''ll pay you in something I definitely never received.\"","options":[{"next":"accepted","label":"I''ll clear them."},{"next":"reported","label":"Done. (report back)"},{"next":"bye","label":"Not my problem."}]}}'::jsonb, NULL, 0, '{"personality":"official","clothing_layers":["a salt-bleached harbourmaster''s coat","a cabled sweater","oilskin trousers"]}'::jsonb, '{}'::jsonb, 'zone_dock_wharf', NULL, 'zone_dock_wharf', '["The Harbourmaster notes something in a ledger and closes it before you can look.","\"Every boat that ties up here is my problem. Try not to become one.\""]'::jsonb, 18, 18, 'female', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_aerie_patron', 'a platinum shareholder', 'A platinum-tier shareholder in a suit that costs more than the building you were born in. He looks at the bay the way a cat looks at a fishbowl, and at you not at all.', 'zone_nc_sable', NULL, '{"bye":{"text":"He has already stopped seeing you.","options":[]},"root":{"text":"The shareholder does not lower his glass. \"If you have to be up here, do try to be interesting. The last one wasn''t.\"","options":[{"next":"bye","label":"..."}]}}'::jsonb, '[]'::jsonb, 0, '{"personality":"corporate","clothing_layers":["a bespoke charcoal suit","a shirt woven from something extinct","silk that has never met a working day"]}'::jsonb, '{}'::jsonb, 'zone_nc_sable', NULL, NULL, '["The shareholder swirls something amber and watches the deep water with mild appetite.","\"Everything down there is inventory. It simply doesn''t know it yet.\""]'::jsonb, 14, 14, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_salvage_broker', 'Voss Iyaka', 'A wiry old clone with a jeweller''s loupe screwed into one eye and a brass hanging-scale bolted to the gatehouse beside him. A strongbox sits chained to his ankle. He weighs everything you carry before he weighs you.', 'zone_slag_gate', NULL, '{"bye":{"text":"\"Wastes''ll still be here when you change your mind.\"","options":[]},"buys":{"text":"\"Metal, wire, components, bone — anything the works spat out that''ll fetch a price back in the city. I weigh it, I pay it, and you don''t have to haul it through the wastes. I also sell what''ll keep you breathing out here, if you''re buying.\"","options":[{"next":"__shop__","label":"Show me the shop."},{"next":"root","label":"Back"}]},"root":{"text":"Voss doesn''t look up from the scale. \"You came all this way, so you''ve either got salvage or you''ve got a death wish. Which is it?\"","options":[{"next":"__shop__","label":"I''ve got salvage to sell."},{"next":"buys","label":"What do you buy?"},{"next":"gossip","label":"Heard anything out here?"},{"next":"bye","label":"Just passing through."}]},"gossip":{"text":"Voss taps the scale and leans in.","actions":[{"action":"GOSSIP_TELL"}],"options":[{"next":"root","label":"Back"}]}}'::jsonb, '[{"price":15,"item_id":"item_ration"},{"price":30,"item_id":"item_rusty_knife"},{"price":50,"item_id":"item_pipe_wrench"},{"price":110,"item_id":"item_taser"}]'::jsonb, 0, '{"mis_willing":false,"personality":"vendor","clothing_layers":["a grease-stained merchant''s apron","a padded vest","a sweat-yellowed undershirt and boxers"]}'::jsonb, '{"nodes":{"idle":{"next":"idle","type":"wait","seconds":600},"start":{"next":"idle","type":"start"}},"_start":"start"}'::jsonb, 'zone_slag_gate', NULL, 'zone_slag_gate', '["Weigh in or move on.","Everything''s got a price by the gram.","The works''ll kill you slow. I pay fast.","Don''t bring me anything that ticks.","Scrap''s scrap. Bring me more of it.","Mind the wire on your way in."]'::jsonb, 20, 20, 'male', '[{"item_id":"item_ration"},{"item_id":"item_rusty_knife"},{"item_id":"item_pipe_wrench"},{"item_id":"item_taser"}]'::jsonb, 8, 1, 465, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'Voss''s Weigh Station', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_fence', 'Sluice', 'A narrow, still woman who runs the Slip''s quiet trade. She never raises her voice and never forgets a face, and both facts should worry you equally.', 'zone_dock_slip', NULL, '{"bye":{"text":"\"Then you were never here.\"","options":[]},"root":{"text":"Sluice regards you without expression. \"You didn''t see a shop. But since you''re here — buying, or unloading something you''d rather not explain?\"","options":[{"next":"__shop__","label":"Let me see."},{"next":"bye","label":"Wrong pier."}]}}'::jsonb, '[{"price":90,"item_id":"item_contraband_crate"},{"price":14,"item_id":"item_cracked_capacitor"},{"price":8,"item_id":"item_salvaged_wiring"},{"price":28,"item_id":"item_rusty_knife"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a long oiled-canvas coat","dark, unremarkable clothes","nothing that would identify a body"]}'::jsonb, '{}'::jsonb, 'zone_dock_slip', NULL, 'zone_dock_slip', '[]'::jsonb, 20, 20, 'female', '[{"item_id":"item_contraband_crate"},{"item_id":"item_cracked_capacitor"},{"item_id":"item_salvaged_wiring"},{"item_id":"item_rusty_knife"}]'::jsonb, 8, 1, 420, 'vendor', '{"fri":[{"to":24,"from":6}],"mon":[{"to":24,"from":6}],"sat":[{"to":24,"from":6}],"sun":[{"to":24,"from":6}],"thu":[{"to":24,"from":6}],"tue":[{"to":24,"from":6}],"wed":[{"to":24,"from":6}]}'::jsonb, 0, 'The Slip', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_assemblyman', 'Assemblyman Croll', 'A back-bench Assemblyman with a florid manner and a genuine, unfashionable belief that the government should govern something. It has made him a nuisance to everyone, including himself.', 'zone_gov_assembly', NULL, '{"bye":{"text":"\"Quite. Well. Someone must, I suppose.\"","options":[]},"root":{"text":"Assemblyman Croll brightens at the sight of anyone who might listen. \"You there — you have the look of someone who solves things. This chamber does the opposite. Might I trouble you?\"","options":[{"next":"quest_offer","label":"What is it?"},{"next":"bye","label":"Afraid not."}]},"accepted":{"text":"\"Splendid! West of Onyx Row — the Scald, the steppe, the sootbanks. Four should quiet them. Do watch the leach-beds; they are not on any map I''d trust.\"","actions":[{"action":"START_QUEST","quest_id":"quest_prefects_problem"}],"options":[{"next":"bye","label":"Understood."}]},"reported":{"text":"\"...The archivists report quiet in the overflow stacks. Extraordinary. Here — your fee, and a permit stamped by my own hand, which still means something in three or four offices.\"","actions":[{"action":"TURN_IN","quest_id":"quest_prefects_problem"}],"options":[{"next":"bye","label":"Obliged."}]},"quest_offer":{"text":"\"Jackals — wire-jackals, the wretched wire-and-scab kind — are coming up out of the wastes and into the Registry''s overflow archives. Nobody official will act; jurisdiction, you understand. Cull four of them for me and I''ll see you''re paid and papered.\"","options":[{"next":"accepted","label":"I''ll cull them."},{"next":"reported","label":"It''s done. (report back)"},{"next":"bye","label":"Not my business."}]}}'::jsonb, NULL, 0, '{"personality":"official","clothing_layers":["a moth-eaten ceremonial sash over a good suit","a starched wing-collar shirt","dignified, defeated underthings"]}'::jsonb, '{}'::jsonb, 'zone_gov_assembly', NULL, 'zone_gov_assembly', '["Assemblyman Croll rehearses a point of order to no one in particular.","\"Someone must mind the west gate. It may as well be me. It certainly won''t be them.\""]'::jsonb, 18, 18, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_shipwright', 'Keel', 'A grizzled shipwright welded into a leather apron, forever half-finished with a hull he''ll never launch. Sells the tools and scrap he isn''t using, which is most of it.', 'zone_dock_boatyard', NULL, '{"bye":{"text":"\"Mind the stands on your way out.\"","options":[]},"root":{"text":"Keel lowers his heat-gun and squints. \"Boat parts, tools, scrap — take your pick. She''s not going anywhere.\" (he nods at the half-built hull)","options":[{"next":"__shop__","label":"What have you got?"},{"next":"bye","label":"Just looking."}]}}'::jsonb, '[{"price":4,"item_id":"item_scrap_metal"},{"price":8,"item_id":"item_salvaged_wiring"},{"price":45,"item_id":"item_pipe_wrench"},{"price":15,"item_id":"canteen"},{"price":28,"item_id":"item_rusty_knife"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a scorched leather apron","a sweat-soaked workshirt","heavy canvas trousers"]}'::jsonb, '{}'::jsonb, 'zone_dock_boatyard', NULL, 'zone_dock_boatyard', '[]'::jsonb, 24, 24, 'male', '[{"item_id":"item_scrap_metal"},{"item_id":"item_salvaged_wiring"},{"item_id":"item_pipe_wrench"},{"item_id":"canteen"},{"item_id":"item_rusty_knife"}]'::jsonb, 8, 1, 130, 'vendor', '{"fri":[{"to":24,"from":6}],"mon":[{"to":24,"from":6}],"sat":[{"to":24,"from":6}],"sun":[{"to":24,"from":6}],"thu":[{"to":24,"from":6}],"tue":[{"to":24,"from":6}],"wed":[{"to":24,"from":6}]}'::jsonb, 0, 'The Boat Yard', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_gov_archivist', 'an archivist', 'A stooped archivist who has memorised the location of files for people who no longer exist, and treats each one as a small held breath.', 'zone_gov_registry', NULL, '{"bye":{"text":"She has already returned to the dead.","options":[]},"root":{"text":"The archivist does not look up from the stacks. \"If you seek a record, give me a name. If you seek a person, I cannot help you; we stopped stocking those.\"","options":[{"next":"bye","label":"Just looking."}]}}'::jsonb, NULL, 0, '{"personality":"clerk","clothing_layers":["a dust-grey archivist''s smock","a high-buttoned blouse","sensible, forgotten underthings"]}'::jsonb, '{}'::jsonb, 'zone_gov_registry', NULL, 'zone_gov_registry', '["The archivist reshelves a file with the tenderness of a burial.","\"Everyone is on record here. Being on record is not the same as being alive.\""]'::jsonb, 14, 14, 'female', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_gov_advocate', 'a court advocate', 'An advocate of Cobalt Court in robes gone shiny at the elbows, arguing a case he inherited and will bequeath, unresolved, to whoever comes next.', 'zone_gov_cobalt', NULL, '{"bye":{"text":"\"Adjourned, then. As ever.\"","options":[]},"root":{"text":"The advocate turns, scenting a potential client. \"Do you have standing? Grievance? Retainer? No? Then I''m afraid we''ve nothing to discuss, which is, ironically, my entire caseload.\"","options":[{"next":"bye","label":"...right."}]}}'::jsonb, NULL, 0, '{"personality":"official","clothing_layers":["threadbare cobalt court robes","a frayed cravat","the underthings of a man who has stopped hoping"]}'::jsonb, '{}'::jsonb, 'zone_gov_cobalt', NULL, 'zone_gov_cobalt', '["The advocate cites a precedent from a court that no longer sits.","\"Justice delayed, in my experience, is simply justice pending. Endlessly pending.\""]'::jsonb, 14, 14, 'male', NULL, NULL, 1, 0, 'npc', NULL, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_lucky_malone', 'Lucky Malone', 'A broadcast studio host.', 'zone_ext_1782953094650', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
