INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_1783019600509', 'Jinx Delacroix', 'A dancer with a shrapnel scar over one hip that the glitter never quite covers — she''s stopped trying. Works the main pole in a slow, deliberate spiral, sizing up the room between spins like she''s pricing everyone in it.', 'zone_mq_chrome_101', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"stripper":true,"mis_willing":true,"personality":"stripper","clothing_layers":["an oversized bomber jacket","a mesh crop top","a black g-string"],"mis_requires_zone_flag":"mis_ok"}'::jsonb, '{"nodes":{"start":{"next":"check_work","type":"start"},"deposit":{"next":"post_shift","type":"action","action_type":"VENDOR_DEPOSIT"},"atm_wait":{"next":"deposit","type":"wait","seconds":10},"work_say":{"next":"check_work","type":"action","action_type":"VENDOR_CHITCHAT"},"atm_emote":{"next":"atm_wait","type":"action","params":{"message":"steps up to the ATM terminal and makes a deposit."},"action_type":"EMOTE"},"go_to_atm":{"next":"atm_emote","type":"action","action_type":"VENDOR_GO_TO_ATM"},"have_life":{"next":"check_work","type":"action","action_type":"HAVE_LIFE"},"home_idle":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"work_wait":{"next":"player_check","type":"wait","seconds":60},"check_work":{"type":"action","offWork":"off_home_check","endShift":"collect_safe","goToWork":"go_to_work","haveLife":"have_life","action_type":"CHECK_VENDOR_WORK"},"go_home_ps":{"next":"home_life_ps","type":"action","action_type":"GO_HOME"},"go_to_work":{"next":"work_wait","type":"action","action_type":"GO_TO_WORK"},"off_random":{"type":"random","branch_0":"have_life","branch_1":"go_home_off","branches":[{"weight":1},{"weight":5}]},"post_shift":{"type":"random","branch_0":"have_life","branch_1":"go_home_ps","branches":[{"weight":1},{"weight":5}]},"go_home_off":{"next":"check_work","type":"action","action_type":"GO_HOME"},"collect_safe":{"next":"go_to_atm","type":"action","action_type":"VENDOR_COLLECT_SAFE"},"home_life_ps":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"player_check":{"type":"condition","ifTrue":"work_say","ifFalse":"check_work","condition_type":"PLAYER_IN_ZONE"},"off_home_check":{"type":"condition","ifTrue":"home_idle","ifFalse":"off_random","condition_type":"AT_HOME"}},"_start":"start"}'::jsonb, 'zone_mq_chrome_101', NULL, 'zone_mq_cherry_floor', '[]'::jsonb, 20, 20, 'female', '[]'::jsonb, 10, 1, 0, 'npc', '{"fri":[{"to":24,"from":19}],"mon":[{"to":24,"from":19}],"sat":[{"to":24,"from":19}],"sun":[{"to":24,"from":19}],"thu":[{"to":24,"from":19}],"tue":[{"to":24,"from":19}],"wed":[{"to":24,"from":19}]}'::jsonb, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_1783019600618', 'Ruby Six', 'One leg below the knee is chrome prosthetic, buffed to a mirror shine and worked into the routine like a prop instead of a war story. She smiles with exactly the wattage the tip requires — no more, no less.', 'zone_mq_chrome_202', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"stripper":true,"mis_willing":true,"personality":"stripper","clothing_layers":["a vinyl trench coat","a chrome-studded bra","a red lace thong"],"mis_requires_zone_flag":"mis_ok"}'::jsonb, '{"nodes":{"start":{"next":"check_work","type":"start"},"deposit":{"next":"post_shift","type":"action","action_type":"VENDOR_DEPOSIT"},"atm_wait":{"next":"deposit","type":"wait","seconds":10},"work_say":{"next":"check_work","type":"action","action_type":"VENDOR_CHITCHAT"},"atm_emote":{"next":"atm_wait","type":"action","params":{"message":"steps up to the ATM terminal and makes a deposit."},"action_type":"EMOTE"},"go_to_atm":{"next":"atm_emote","type":"action","action_type":"VENDOR_GO_TO_ATM"},"have_life":{"next":"check_work","type":"action","action_type":"HAVE_LIFE"},"home_idle":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"work_wait":{"next":"player_check","type":"wait","seconds":60},"check_work":{"type":"action","offWork":"off_home_check","endShift":"collect_safe","goToWork":"go_to_work","haveLife":"have_life","action_type":"CHECK_VENDOR_WORK"},"go_home_ps":{"next":"home_life_ps","type":"action","action_type":"GO_HOME"},"go_to_work":{"next":"work_wait","type":"action","action_type":"GO_TO_WORK"},"off_random":{"type":"random","branch_0":"have_life","branch_1":"go_home_off","branches":[{"weight":1},{"weight":5}]},"post_shift":{"type":"random","branch_0":"have_life","branch_1":"go_home_ps","branches":[{"weight":1},{"weight":5}]},"go_home_off":{"next":"check_work","type":"action","action_type":"GO_HOME"},"collect_safe":{"next":"go_to_atm","type":"action","action_type":"VENDOR_COLLECT_SAFE"},"home_life_ps":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"player_check":{"type":"condition","ifTrue":"work_say","ifFalse":"check_work","condition_type":"PLAYER_IN_ZONE"},"off_home_check":{"type":"condition","ifTrue":"home_idle","ifFalse":"off_random","condition_type":"AT_HOME"}},"_start":"start"}'::jsonb, 'zone_mq_chrome_202', NULL, 'zone_mq_cherry_floor', '[]'::jsonb, 20, 20, 'female', '[]'::jsonb, 10, 1, 0, 'npc', '{"fri":[{"to":24,"from":19}],"mon":[{"to":24,"from":19}],"sat":[{"to":24,"from":19}],"sun":[{"to":24,"from":19}],"thu":[{"to":24,"from":19}],"tue":[{"to":24,"from":19}],"wed":[{"to":24,"from":19}]}'::jsonb, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_ma_cinder', 'Ma Cinder', 'The matriarch of the Slake Pond camp: sun-cured, iron-grey, and entirely without illusions. She has buried more of her people than she''ll say and guards the living with a pragmatism that shades into menace.', 'zone_waste_slake', NULL, '{"bye":{"text":"\"Fill your jug and move on, then.\"","options":[]},"root":{"text":"A leather-faced woman looks up from a cook-pot, one hand never far from a length of pipe. \"This is my pond, my camp, my water. State your business or fill your jug and go.\"","options":[{"next":"quest_offer","label":"You run this camp?"},{"next":"bye","label":"Just passing through."}]},"accepted":{"text":"\"They den in the wet ground — the Seep, the Rust Marsh, the Runoff down south. Two at least. And mind your footing; the tar doesn''t give anything back.\"","actions":[{"action":"START_QUEST","quest_id":"quest_bog_standard"}],"options":[{"next":"bye","label":"Understood."}]},"reported":{"text":"\"...The seeps are quieter. My people noticed. Here — clean water and a hot meal, and you''re welcome at this fire, which is more than most get.\"","actions":[{"action":"TURN_IN","quest_id":"quest_bog_standard"}],"options":[{"next":"bye","label":"Obliged."}]},"quest_offer":{"text":"\"Something''s coming up out of the seeps — tar-things, big and slow and hungry. Took two of mine this week. Put a couple of them down and there''s water, food, and goodwill in it. Goodwill''s worth more than it sounds out here.\"","options":[{"next":"accepted","label":"I''ll thin them out."},{"next":"reported","label":"It''s done. (report back)"},{"next":"bye","label":"Not my fight."}]}}'::jsonb, '[{"price":5,"item_id":"item_water_bottle"},{"price":10,"item_id":"item_ration"},{"price":15,"item_id":"canteen"},{"price":6,"item_id":"item_reagent_acid"},{"price":6,"item_id":"item_reagent_solvent"},{"price":6,"item_id":"item_reagent_feedstock"},{"price":6,"item_id":"item_reagent_nutrient"}]'::jsonb, 0, '{"personality":"vendor","clothing_layers":["a patched canvas duster hung with tools","layered wool gone the colour of ash","sturdy, much-mended underthings"]}'::jsonb, '{}'::jsonb, 'zone_waste_slake', NULL, 'zone_waste_slake', '["Ma Cinder stirs the pot and watches the flats over your shoulder.","\"Water''s life out here. Don''t waste mine.\"","\"Camp''s full. Doesn''t mean you''re welcome to stay.\""]'::jsonb, 24, 24, 'female', '[{"item_id":"item_water_bottle"},{"item_id":"item_ration"},{"item_id":"canteen"},{"item_id":"item_reagent_acid"},{"item_id":"item_reagent_solvent"},{"item_id":"item_reagent_feedstock"},{"item_id":"item_reagent_nutrient"}]'::jsonb, 8, 1, 110, 'vendor', '{"fri":[{"to":24,"from":0}],"mon":[{"to":24,"from":0}],"sat":[{"to":24,"from":0}],"sun":[{"to":24,"from":0}],"thu":[{"to":24,"from":0}],"tue":[{"to":24,"from":0}],"wed":[{"to":24,"from":0}]}'::jsonb, 0, 'Slake Pond Camp', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_the_fixer', 'a hooded figure', 'A lean figure in a hood who keeps to the edges of the light, hands in pockets, eyes everywhere. Nothing about them invites conversation. They could be gone the moment you look away.', 'zone_tunnels', NULL, '{}'::jsonb, '[{"price":70,"item_id":"item_dreamsmoke","min_trust":0},{"price":60,"item_id":"item_buzz","min_trust":0},{"price":100,"item_id":"item_lull","min_trust":0},{"price":45,"item_id":"item_ether","min_trust":0},{"price":140,"item_id":"item_static","min_trust":25},{"price":120,"item_id":"item_laughers","min_trust":25},{"price":90,"item_id":"item_psilocybin","min_trust":25},{"price":40,"item_id":"item_amyls","min_trust":25},{"price":175,"item_id":"item_redline","min_trust":45},{"price":210,"item_id":"item_grey","min_trust":45},{"price":150,"item_id":"item_mescaline","min_trust":45},{"price":185,"item_id":"item_blotter","min_trust":45},{"price":145,"item_id":"item_screamers","min_trust":45},{"price":360,"item_id":"item_coldfire","min_trust":70},{"price":300,"item_id":"item_blacktar","min_trust":70},{"price":250,"item_id":"item_khole","min_trust":70},{"price":300,"item_id":"item_memhack","min_trust":70},{"price":550,"item_id":"item_threshold","min_trust":90},{"price":480,"item_id":"item_voidwalk","min_trust":90},{"price":500,"item_id":"item_overclock","min_trust":90}]'::jsonb, 0, '{"covert":true,"deal_to":5,"deal_from":21,"trust_max":100,"drug_buyer":true,"trust_flag":"dealer_trust","passphrases":["the static''s bad tonight","you holding","ask the shadows"],"trust_per_buy":8,"inner_circle_flag":"dealer_inner_circle","inner_circle_line":"The Fixer''s whisper drops lower still. \"You don''t want to just *deal*, do you. You want to cook. Then you want raw, not street-cut product. Go see Sully — the barkeep at the Pigeon Bar, over in the Marquee. Tell him the static''s clean tonight. He''ll open the back-room list for you.\""}'::jsonb, '{"nodes":{"prowl":{"next":"night_check","type":"action","params":{"loop":true,"mode":"walk","waypoints":["zone_tunnels","zone_city_sw","zone_thresholdeast"]},"action_type":"PATROL"},"vanish":{"next":"night_check","type":"action","action_type":"GO_HOME"},"night_check":{"type":"condition","ifTrue":"prowl","params":{"to":5,"from":21},"ifFalse":"vanish","condition_type":"HOUR_RANGE"}},"_start":"night_check"}'::jsonb, 'zone_tunnels', NULL, NULL, '["doesn''t look up.","keeps to the shadows, watching the exits.","\"Wrong guy. Keep moving.\"","says nothing, but you feel watched.","melts a little further into the dark."]'::jsonb, 40, 40, 'male', '[]'::jsonb, 0, 1, 0, 'dealer', '{"fri":[{"to":4,"from":0},{"to":24,"from":20}],"mon":[{"to":4,"from":0},{"to":24,"from":20}],"sat":[{"to":4,"from":0},{"to":24,"from":20}],"sun":[{"to":4,"from":0},{"to":24,"from":20}],"thu":[{"to":4,"from":0},{"to":24,"from":20}],"tue":[{"to":4,"from":0},{"to":24,"from":20}],"wed":[{"to":4,"from":0},{"to":24,"from":20}]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '["zone_tunnels","zone_city_sw","zone_thresholdeast"]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_barkeep', 'Sully Holt', 'Runs the bar out of a gutted delivery van. Pours with the bored precision of someone who has heard every sob story twice.', 'zone_mq_pigeon_bar', NULL, '{"menu":{"text":"Swill''s free with a straight face. Whiskey''ll put hair on parts of you that don''t currently have hair. The Glow Cocktail is mostly safe — emphasis on ''mostly,'' don''t email me about it.","_vine":{"x":360,"y":60},"actions":[],"options":[{"next":"root","label":"Back"}]},"root":{"text":"Drink or don''t, but don''t just stand there breathing on my bar.","_vine":{"x":40,"y":60},"actions":[],"options":[{"next":"menu","label":"What''s good?"},{"next":"gossip","label":"Heard anything?"},{"next":"bm_menu","label":"[quietly] I hear you move more than drinks.","conditions":[{"op":"set","flag":"dealer_inner_circle","scope":"player"}]},{"next":"","label":"Never mind."}]},"gossip":{"text":"Sully leans in over the bar.","_vine":{"x":360,"y":240},"actions":[{"action":"GOSSIP_TELL"}],"options":[{"next":"root","label":"Back"}]},"bm_menu":{"text":"Sully sets down the glass he''s been not-cleaning and leans in. \"Back-room list. I don''t touch the stuff — I just know a drone pilot who owes me. You point, it lands out at the Scald, and getting it home past the checkpoint is *your* lookout. What''re you after?\"","_vine":{"x":700,"y":60},"actions":[],"options":[{"next":"bm_q_buzz","label":"crude Buzz — 10₵/crate"},{"next":"bm_q_glasshollow","label":"crude Glasshollow — 10₵/crate"},{"next":"bm_q_slow","label":"crude Slow — 10₵/crate"},{"next":"bm_q_blotter","label":"crude Blotter — 28₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"1"}]},{"next":"bm_q_laughers","label":"crude Laughers — 28₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"1"}]},{"next":"bm_q_mescaline","label":"crude Mescaline — 28₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"1"}]},{"next":"bm_q_psilocybin","label":"crude Psilocybin — 28₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"1"}]},{"next":"bm_q_screamers","label":"crude Screamers — 28₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"1"}]},{"next":"bm_q_threshold","label":"crude The Threshold — 28₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"1"}]},{"next":"bm_q_dreamsmoke","label":"crude Dreamsmoke — 62₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"3"}]},{"next":"bm_q_memhack","label":"crude Memhack — 62₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"3"}]},{"next":"bm_q_static","label":"crude Static — 62₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"3"}]},{"next":"bm_q_amyls","label":"crude Amyls — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_blacktar","label":"crude Blacktar — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_coldfire","label":"crude Coldfire — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_ether","label":"crude Ether — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_grey","label":"crude Grey — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_khole","label":"crude K-Hole — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_lull","label":"crude Lull — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_overclock","label":"crude Neural Overclock — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_redline","label":"crude Redline — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"bm_q_voidwalk","label":"crude Voidwalk — 126₵/crate","conditions":[{"op":"gt","flag":"bm_trust","scope":"player","value":"6"}]},{"next":"root","label":"Nothing tonight."}]},"bm_broke":{"text":"Sully snorts and goes back to the glass. \"Come back when your credits clear. I run a cash business, and you''re not the kind of face I extend credit to.\"","_vine":{"x":1360,"y":240},"actions":[],"options":[{"next":"bm_menu","label":"Fair. Let me look again."},{"next":"root","label":"Never mind."}]},"bm_q_buzz":{"text":"\"crude Buzz. How many crates?\" Sully doesn''t write anything down. \"10₵ apiece, dropped at the Scald.\"","_vine":{"x":1040,"y":40},"actions":[],"options":[{"next":"bm_ordered","label":"1 crate — 10₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":1,"itemId":"item_raw_buzz"}}]},{"next":"bm_ordered","label":"3 crates — 30₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":3,"itemId":"item_raw_buzz"}}]},{"next":"bm_ordered","label":"5 crates — 50₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":5,"itemId":"item_raw_buzz"}}]},{"next":"bm_menu","label":"On second thought — back."}]},"bm_q_grey":{"text":"\"crude Grey. How many crates?\" Sully doesn''t write anything down. \"126₵ apiece, dropped at the Scald.\"","_vine":{"x":1040,"y":680},"actions":[],"options":[{"next":"bm_ordered","label":"1 crate — 126₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":1,"itemId":"item_raw_grey"}}]},{"next":"bm_ordered","label":"3 crates — 378₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":3,"itemId":"item_r