,"actions":[],"options":[{"next":"bm_ordered","label":"1 crate — 62₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":1,"itemId":"item_raw_dreamsmoke"}}]},{"next":"bm_ordered","label":"3 crates — 186₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":3,"itemId":"item_raw_dreamsmoke"}}]},{"next":"bm_ordered","label":"5 crates — 310₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":5,"itemId":"item_raw_dreamsmoke"}}]},{"next":"bm_menu","label":"On second thought — back."}]},"bm_q_psilocybin":{"text":"\"crude Psilocybin. How many crates?\" Sully doesn''t write anything down. \"28₵ apiece, dropped at the Scald.\"","_vine":{"x":1040,"y":280},"actions":[],"options":[{"next":"bm_ordered","label":"1 crate — 28₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":1,"itemId":"item_raw_psilocybin"}}]},{"next":"bm_ordered","label":"3 crates — 84₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":3,"itemId":"item_raw_psilocybin"}}]},{"next":"bm_ordered","label":"5 crates — 140₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":5,"itemId":"item_raw_psilocybin"}}]},{"next":"bm_menu","label":"On second thought — back."}]},"bm_q_glasshollow":{"text":"\"crude Glasshollow. How many crates?\" Sully doesn''t write anything down. \"10₵ apiece, dropped at the Scald.\"","_vine":{"x":1040,"y":80},"actions":[],"options":[{"next":"bm_ordered","label":"1 crate — 10₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":1,"itemId":"item_raw_glasshollow"}}]},{"next":"bm_ordered","label":"3 crates — 30₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":3,"itemId":"item_raw_glasshollow"}}]},{"next":"bm_ordered","label":"5 crates — 50₵","actions":[{"action":"PLACE_SMUGGLE_ORDER","params":{"qty":5,"itemId":"item_raw_glasshollow"}}]},{"next":"bm_menu","label":"On second thought — back."}]}}'::jsonb, '[{"price":4,"stock":99,"item_id":"item_drink_basin_swill"},{"price":9,"stock":30,"item_id":"item_drink_rust_whiskey"},{"price":14,"stock":12,"item_id":"item_drink_glow_cocktail"},{"price":6,"stock":20,"item_id":"item_bar_jerky"},{"price":120,"stock":20,"item_id":"canteen"},{"price":5,"item_id":"item_drug_coffee"},{"price":6,"item_id":"item_drug_beer"}]'::jsonb, 0, '{"drug_buyer":true,"mis_willing":false,"personality":"travelling_vendor","clothing_layers":["a dust-caked longcoat hung with trinkets","a road-worn wool jumper","long johns and boxers"]}'::jsonb, '{"nodes":{},"_start":""}'::jsonb, 'zone_mq_pigeon_bar', NULL, NULL, '["Best prices in the district. That''s not saying much.","You touch it, you bought it.","Everything''s genuine. Genuinely acquired.","Trade you for it. Credits preferred. Bullets accepted.","Limited supply. Always limited. That''s the pitch.","I don''t know where it came from. That''s not your business either.","Come back tomorrow — stock changes. If I''m still here.","Quality merchandise at prices that won''t kill you. Probably."]'::jsonb, 20, 20, 'male', '[{"item_id":"item_drug_coffee"},{"item_id":"item_drug_beer"},{"item_id":"item_cigarettes"},{"item_id":"item_joint"}]'::jsonb, 12, 1, 35, 'npc', '{"fri":[{"to":2,"from":0},{"to":24,"from":18}],"mon":[{"to":2,"from":0},{"to":24,"from":18}],"sat":[{"to":2,"from":0},{"to":24,"from":18}],"sun":[{"to":2,"from":0},{"to":24,"from":18}],"thu":[{"to":2,"from":0},{"to":24,"from":18}],"tue":[{"to":2,"from":0},{"to":24,"from":18}],"wed":[{"to":2,"from":0},{"to":24,"from":18}]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_narrator', 'Bobby Francis', 'A broadcast studio host.', 'zone_ext_1782953094650', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true,"mis_willing":false}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_charter_kessler', 'Old Kessler', 'A gaunt, grey old bird of a man who talks to his aircraft more than to people. He takes the evening shift off Smuggler''s Slip, and he will fly you absolutely anywhere — he just won''t ask why.', 'zone_up_skyway', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"charter_pilot","charter_pilot":{"field":"zone_dock_slip","shift_start":16}}'::jsonb, '{}'::jsonb, 'zone_residential_lobby', NULL, 'zone_dock_slip', '[]'::jsonb, 24, 24, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_breaker_sledge', 'Sledge Vurn', 'A slab of a man gone to rust, Sledge runs the Breakers'' end of Slaughter Lane with a length of rebar and a grudge against anything that beeps. Half his face is a burn scar shaped like a circuit board — a souvenir, he''ll tell you, from teaching a drone some manners. He does not blink much.', 'zone_meat_slaughter', 'faction_breakers', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"lowlife","faction_guard":true,"clothing_layers":["a battle-jacket riveted with road-signs and bike chain","a grease-black wifebeater","torn canvas work shorts"]}'::jsonb, '{}'::jsonb, 'zone_meat_slaughter', NULL, NULL, '["Sledge drags his rebar along the ground, letting it sing off the concrete.","\"This is Breaker ground. You bleed here, you bleed for us.\"","\"Smash the smart stuff. Keep the dumb stuff. Simple.\""]'::jsonb, 130, 130, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_breaker_grease', 'Grease', 'Grease earned the name honestly — he''s slick with it head to boot, and it never quite washes off. He guards the Lane''s mouth, chewing something that used to be gum, cataloguing everyone who walks in by how much trouble they''ll be.', 'zone_meat_slaughter', 'faction_breakers', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"lowlife","faction_guard":true,"clothing_layers":["a sleeveless denim cut with the Breakers'' broken-cog patch","an oil-slick thermal shirt","frayed boxer briefs"]}'::jsonb, '{}'::jsonb, 'zone_meat_slaughter', NULL, NULL, '["Grease spits, missing your boot on purpose.","\"Keep walking or start paying. Toll''s whatever I say it is.\""]'::jsonb, 90, 90, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_breaker_nyla', 'Nyla Sparks', 'Nyla keeps a row of bottles racked on her hip, each stoppered with an oily rag, and the easy smile of someone who genuinely enjoys her work. The Breakers point her at anything with a screen and let her cook.', 'zone_meat_slaughter', 'faction_breakers', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"lowlife","faction_guard":true,"clothing_layers":["a fireproof tabard scorched black at every hem","a soot-grey tank top","a plain sports bra and briefs"]}'::jsonb, '{}'::jsonb, 'zone_meat_slaughter', NULL, NULL, '["Nyla thumbs a lighter open and shut, open and shut.","\"Everything burns. Circuit boards just burn prettier.\""]'::jsonb, 90, 90, 'female', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_custodian_ferrin', 'Deacon Aldous Ferrin', 'Deacon Ferrin tends the ruins of Old Coldwater the way a verger tends a cathedral — reverently, and with a clipboard. He believes the Architect maintains all things and that the Custodians are simply its middle management. He will explain this to you at length, whether or not you asked.', 'zone_ruins', 'faction_custodians', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"corporate","faction_guard":true,"clothing_layers":["a hi-vis vestment worn over a charcoal three-piece suit","a starched white shirt with a fraying collar","pressed grey briefs"]}'::jsonb, '{}'::jsonb, 'zone_ruins', NULL, NULL, '["Ferrin runs a white glove along a broken rail and studies the dust with quiet disappointment.","\"The Architect maintains. We merely file the paperwork.\"","\"This district is under Custodial care. Kindly do not deface the ruins.\""]'::jsonb, 120, 120, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_graham_mercer', 'Graham Mercer', 'A broadcast studio host.', 'zone_ruins', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_custodian_wren', 'Custodian-Adjunct Wren', 'Adjunct Wren has a form for everything and a pen that never runs dry. She logs each visitor to the ruins in triplicate and issues citations for infractions no one else can see. Cross her and the paperwork becomes eternal.', 'zone_ruins', 'faction_custodians', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"official","faction_guard":true,"clothing_layers":["a laminated tabard hung with cleaning-rota clipboards","a grey pencil-skirt suit","a beige bra and briefs"]}'::jsonb, '{}'::jsonb, 'zone_ruins', NULL, NULL, '["Wren notes your arrival on a clipboard without looking up.","\"You are not on the approved-access list. I''ll require a reason. In writing.\""]'::jsonb, 90, 90, 'female', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_custodian_pell', 'Sub-Custodian Pell', 'Pell mops. That is the whole of Pell''s visible ministry — a slow, devotional mopping of floors that crumbled to gravel years ago. He hums the Coldwater hum under his breath and flinches if you interrupt the rhythm.', 'zone_ruins', 'faction_custodians', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"clerk","faction_guard":true,"clothing_layers":["a grey maintenance cassock with a name stitched over the breast","a company polo shirt buttoned to the throat","white cotton briefs"]}'::jsonb, '{}'::jsonb, 'zone_ruins', NULL, NULL, '["Pell moves his mop over bare rubble in careful, reverent strokes.","\"Mustn''t let it get untidy. The Architect notices untidy things.\""]'::jsonb, 90, 90, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_glitch_oracle', 'Oracle-9', 'Oracle-9 sits in the dark of The Under with her eyes half-closed and a fan of severed fibre-optic running into a socket at the base of her skull. The Glitch treat her word as scripture; she treats packet loss as prophecy. She may be brilliant. She is definitely not well.', 'zone_tunnels', 'faction_glitch', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"lowlife","faction_guard":true,"clothing_layers":["a cloak stitched from dead server-blade shielding","a hoodie sagging with looped patch cable","a mismatched bralette and briefs"]}'::jsonb, '{}'::jsonb, 'zone_tunnels', NULL, NULL, '["Oracle-9 tilts her head as if listening to a frequency you can''t hear.","\"The Architect speaks in dropped packets. We are learning to answer.\"","\"You''re standing in the Glitch''s signal, meat. Mind the interference.\""]'::jsonb, 110, 110, 'female', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_glitch_null', 'Null', 'Null talks in the cadence of a dial-up handshake and answers questions you didn''t ask. He runs the Under''s makeshift relays and guards them like a dog guards a bone it can no longer taste.', 'zone_tunnels', 'faction_glitch', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"lowlife","faction_guard":true,"clothing_layers":["a taped-together longcoat bristling with dead antennas","a black tee showing a corrupted logo","grey trunks"]}'::jsonb, '{}'::jsonb, 'zone_tunnels', NULL, NULL, '["Null''s fingers twitch through a keystroke pattern in the empty air.","\"Access denied. You are not — hkkt — one of us yet.\""]'::jsonb, 90, 90, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_john_akerson', 'John Akerson', 'A broadcast studio host.', 'zone_up_skyway', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_glitch_hex', 'Hex', 'Hex smiles too much and blinks too little, her skin traced with conductive ink that catches the tunnel-light like faint circuitry. She collects other people''s passwords the way children collect shiny stones, for no reason she can explain.', 'zone_tunnels', 'faction_glitch', '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"lowlife","faction_guard":true,"clothing_layers":["a hooded poncho of woven ribbon-cable","a cropped mesh top over circuit-inked skin","a black bra and boyshorts"]}'::jsonb, '{}'::jsonb, 'zone_tunnels', NULL, NULL, '["Hex watches you with her head cocked, grinning at something only she can see.","\"Ooh. You''ve got such a pretty little password behind those eyes.\""]'::jsonb, 90, 90, 'female', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_orion_dex', 'Orion Dex', 'A lean man of indeterminate age in a black shirt, rolled to the elbows. His hands are always moving — shuffling, squaring a deck, tapping the felt — with a precision that suggests either training or compulsion. He watches the room with an expression that gives nothing away. A dealer''s badge is pinned to his shirt: hand-printed, slightly crooked.', 'zone_residential_lobby', NULL, '{"bye":{"text":"\"Seat''s waiting.\"","options":[]},"play":{"text":"\"Then sit down and type join. Buy-in''s posted on the table. Don''t splash the pot.\"","options":[{"next":"betting","label":"How do I bet?"},{"next":"bye","label":"Got it. Thanks."}]},"root":{"text":"Orion Dex doesn''t look up from the cards he''s riffle-shuffling. \"You''re either here to play or you''re in the way. Which is it?\"","options":[{"next":"play","label":"I''d like to play."},{"next":"rules","label":"Tell me the rules."},{"next":"place","label":"What''s this place?"},{"next":"bye","label":"Just looking."}]},"place":{"text":"\"The Embassy. Used to be a hotel lobby. Now it''s got a bar and a poker table, which is an improvement. The rest is none of my business.\"","options":[{"next":"bye","label":"Sounds like my kind of place."},{"next":"play","label":"I''d like to play."}]},"rules":{"text":"\"Texas Hold''em. Two hole cards, five community. Best hand wins. Blinds are posted automatically. If you fold every hand you''ll last longer but win nothing.\"","options":[{"next":"betting","label":"How do I bet?"},{"next":"commands","label":"What commands do I use?"},{"next":"play","label":"Ready to play."}]},"betting":{"text":"\"check, call, bet X, raise X, fold, allin. The system enforces minimum raises. Don''t waste my time asking what the minimum is — it''ll tell you.\"","options":[{"next":"commands","label":"What commands are there?"},{"next":"bye","label":"Ready."}]},"commands":{"text":"\"join — sit down. leave — cash out and go. check / call / bet X / raise X / fold / allin — in-hand actions. board — see community cards. pot — current pot. players — who''s in and their stacks.\"","options":[{"next":"bye","label":"Got it."}]}}'::jsonb, '[]'::jsonb, 0, '{"table_id":"gametable_embassy"}'::jsonb, '{"nodes":{"start":{"next":"player_check","type":"start"},"chitchat":{"next":"chat_wait","type":"action","action_type":"VENDOR_CHITCHAT"},"chat_wait":{"next":"start","type":"wait","seconds":90},"idle_wait":{"next":"start","type":"wait","seconds":30},"player_check":{"type":"condition","ifTrue":"chitchat","ifFalse":"idle_wait","condition_type":"PLAYER_IN_ZONE"}},"_start":"start"}'::jsonb, 'zone_residential_lobby', NULL, 'zone_residential_lobby', '["\"Pot''s right.\"","cuts the deck without looking, a motion as automatic as breathing","\"No rabbit hunting.\"","sets out the cut card with a flat click","\"Your read or your math — pick one. You''re not fast enough for both.\"","riffles the deck once, sets it down, waits","\"Minimum raise is the size of the last raise. Always.\"","adjusts the position of the discard tray by exactly one centimeter","\"If you can''t afford to call, you shouldn''t have raised.\"","watches the room with the patient attention of someone who has seen every tell twice","\"Side pot. Keep your stacks separate.\"","squares the deck against the felt — a crisp, decisive sound","glances toward the bar, then back at the table","\"House doesn''t take a cut. Don''t ask why.\""]'::jsonb, 25, 25, 'male', '[]'::jsonb, 10, 1, 0, 'dealer', '{"fri":[],"mon":[],"sat":[],"sun":[],"thu":[],"tue":[],"wed":[]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_neil_mcmanistan', 'Neil Mcmanistan', 'A broadcast studio host.', 'zone_civ_ledger', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_charter_soto', 'Magpie Soto', 'A stocky, quick-handed pilot with a magpie''s eye for anything shiny and loose, forever chewing a toothpick. She flies the daylight run out of the Marshalling Yard freight field and swears she''s never lost a passenger. On purpose.', 'zone_hangar_yard_marshalling', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"charter_pilot","charter_pilot":{"field":"zone_yard_marshalling","shift_start":8}}'::jsonb, '{}'::jsonb, 'zone_residential_lobby', NULL, 'zone_yard_marshalling', '[]'::jsonb, 24, 24, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_charter_doyle', 'Ratchet Doyle', 'A wiry charter pilot in an oil-stained flight jacket, with a scar where an ear used to be and the flat, far-off stare of someone who has spent too long above the clouds. He works the graveyard shift out of Coldwater Regional.', 'zone_city_west', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"personality":"charter_pilot","charter_pilot":{"field":"zone_outskirts","shift_start":0}}'::jsonb, '{}'::jsonb, 'zone_residential_lobby', NULL, 'zone_outskirts', '[]'::jsonb, 24, 24, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_cassius_drum', 'Cassius Drum', 'A lean man in his thirties with an eye for colour coordination that looks deliberately out of place in this city. He wears a patchwork of reclaimed fabric and tech-fibre with a tailor''s tape measure wrapped around one wrist like a bracelet. Attitude to spare.', 'zone_meridian_unit_202', NULL, '{"bye":{"text":"\"Come back when you''re ready to commit to an aesthetic. Or don''t. Either way, you know where I am.\"","options":[]},"root":{"text":"Cassius Drum looks you up and down with professional interest. \"Okay. Okay. I see what we''re working with. Don''t worry — I''ve dressed worse.\"","options":[{"next":"__shop__","label":"Browse your wares."},{"next":"craft","label":"You make these yourself?"},{"next":"fashion","label":"What''s the post-apocalypse look this season?"},{"next":"bye","label":"I''m good, thanks."},{"next":"gossip","label":"Heard anything on the street?"}]},"craft":{"text":"\"Some of it. The rest I pull off people — gently, don''t look at me like that, they were already dead. Point is, everything here has a story. I just charge you for the good parts.\"","options":[{"next":"__shop__","label":"Browse your wares."},{"next":"bye","label":"See you around."}]},"gossip":{"text":"Cassius glances past you, then talks low.","actions":[{"action":"GOSSIP_TELL"}],"options":[{"next":"root","label":"Back"}]},"fashion":{"text":"\"Layering. Always layering. You want at least three textures — keeps the rad-scanner confused and looks incredible. Also, pockets. You can never have enough pockets in a disaster zone.\"","options":[{"next":"__shop__","label":"Browse your wares."},{"next":"bye","label":"Sound advice. See you around."}]}}'::jsonb, '[{"price":900,"item_id":"item_thermal_parka"},{"price":280,"item_id":"item_thermex_top"},{"price":250,"item_id":"item_thermex_leggings"},{"price":120,"item_id":"item_watch_cap"},{"price":16,"item_id":"item_briefs_novelty_spareme"},{"price":61,"item_id":"item_thong_lace_sheer"},{"price":162,"item_id":"item_jock_leather"},{"price":41,"item_id":"item_briefs_sport_wick"},{"price":4,"item_id":"item_underpants_lucky"},{"price":95,"item_id":"item_longjohns_thermal"},{"price":74,"item_id":"item_panties_crotchless_mesh"},{"price":24,"item_id":"item_boxers_biohazard"},{"price":74,"item_id":"item_bralette_lace_sheer"},{"price":54,"item_id":"item_sportsbra_compression"},{"price":203,"item_id":"item_bra_leather_harness"},{"price":11,"item_id":"item_undershirt_ribbed"},{"price":34,"item_id":"item_pasties_tassel"},{"price":81,"item_id":"item_binder_chest"},{"price":27,"item_id":"item_tee_singularity"},{"price":61,"item_id":"item_hoodie_grey"},{"price":68,"item_id":"item_croptop_fishnet"},{"price":34,"item_id":"item_tee_mascot"},{"price":47,"item_id":"item_shirt_flannel"},{"price":81,"item_id":"item_halter_backless"},{"price":54,"item_id":"item_sweater_ugly"},{"price":122,"item_id":"item_jacket_denim"},{"price":149,"item_id":"item_blouse_sheer_wrap"},{"price":30,"item_id":"item_tee_offbrand_security"},{"price":54,"item_id":"item_jeans_relaxed"},{"price":41,"item_id":"item_shorts_cargo"},{"price":243,"item_id":"item_leggings_latex"},{"price":41,"item_id":"item_sweatpants_grey"},{"price":61,"item_id":"item_shorts_micro"},{"price":47,"item_id":"item_trousers_clown"},{"price":34,"item_id":"item_sneakers_canvas"},{"price":27,"item_id":"item_slippers_monster"},{"price":297,"item_id":"item_boots_thigh_heel"},{"price":16,"item_id":"item_sandals_strap"},{"price":24,"item_id":"item_cap_trucker_slogan"},{"price":41,"item_id":"item_bucket_hat"},{"price":95,"item_id":"item_veil_lace"},{"price":27,"item_id":"item_gloves_fingerless"},{"price":88,"item_id":"item_gloves_lace_opera"},{"price":108,"item_id":"item_collar_leather"},{"price":30,"item_id":"item_fannypack"},{"price":20,"item_id":"item_tote_canvas"},{"price":6,"item_id":"item_reagent_acid"},{"price":6,"item_id":"item_reagent_solvent"},{"price":6,"item_id":"item_reagent_feedstock"},{"price":6,"item_id":"item_reagent_nutrient"}]'::jsonb, 0, '{"mis_willing":false,"personality":"vendor","clothing_layers":["a many-pocketed utility coat","a faded company polo","grey boxer-briefs"]}'::jsonb, '{"nodes":{"start":{"next":"check_work","type":"start"},"deposit":{"next":"post_shift","type":"action","action_type":"VENDOR_DEPOSIT"},"atm_wait":{"next":"deposit","type":"wait","seconds":10},"work_say":{"next":"check_work","type":"action","action_type":"VENDOR_CHITCHAT"},"atm_emote":{"next":"atm_wait","type":"action","params":{"message":"steps up to the ATM terminal and makes a deposit."},"action_type":"EMOTE"},"go_to_atm":{"next":"atm_emote","type":"action","action_type":"VENDOR_GO_TO_ATM"},"have_life":{"next":"check_work","type":"action","action_type":"HAVE_LIFE"},"home_idle":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"work_wait":{"next":"player_check","type":"wait","seconds":60},"check_work":{"type":"action","offWork":"off_home_check","endShift":"collect_safe","goToWork":"go_to_work","haveLife":"have_life","action_type":"CHECK_VENDOR_WORK"},"go_home_ps":{"next":"home_life_ps","type":"action","action_type":"GO_HOME"},"go_to_work":{"next":"work_wait","type":"action","action_type":"GO_TO_WORK"},"off_random":{"type":"random","branch_0":"have_life","branch_1":"go_home_off","branches":[{"weight":1},{"weight":5}]},"post_shift":{"type":"random","branch_0":"have_life","branch_1":"go_home_ps","branches":[{"weight":1},{"weight":5}]},"go_home_off":{"next":"check_work","type":"action","action_type":"GO_HOME"},"collect_safe":{"next":"go_to_atm","type":"action","action_type":"VENDOR_COLLECT_SAFE"},"home_life_ps":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"player_check":{"type":"condition","ifTrue":"work_say","ifFalse":"check_work","condition_type":"PLAYER_IN_ZONE"},"off_home_check":{"type":"condition","ifTrue":"home_idle","ifFalse":"off_random","condition_type":"AT_HOME"}},"_start":"start"}'::jsonb, 'zone_meridian_unit_202', NULL, 'zone_drum_shop', '["\"Color is a weapon. Most people just don''t know how to aim it.\"","folds a jacket with the kind of precision that borders on religious","\"You''d be surprised what a good belt does for a silhouette. Changes everything.\"","holds a piece of fabric up to the light and clicks his tongue","\"Half this city''s walking around in borrowed clothes. The other half don''t care. I care for both halves.\"","snips a loose thread and examines the result critically","\"Rad-shielded lining is the future. I was doing it before it was a survival necessity.\"","rearranges a display rack, steps back, then rearranges it again","\"Pockets. I''m telling you. Every design needs more pockets. This is non-negotiable.\"","hums something tuneless while pinning a hem"]'::jsonb, 25, 25, 'male', '[{"item_id":"item_thermal_parka"},{"item_id":"item_thermex_top"},{"item_id":"item_thermex_leggings"},{"item_id":"item_watch_cap"},{"item_id":"item_briefs_novelty_spareme"},{"item_id":"item_thong_lace_sheer"},{"item_id":"item_jock_leather"},{"item_id":"item_briefs_sport_wick"},{"item_id":"item_underpants_lucky"},{"item_id":"item_longjohns_thermal"},{"item_id":"item_panties_crotchless_mesh"},{"item_id":"item_boxers_biohazard"},{"item_id":"item_bralette_lace_sheer"},{"item_id":"item_sportsbra_compression"},{"item_id":"item_bra_leather_harness"},{"item_id":"item_undershirt_ribbed"},{"item_id":"item_pasties_tassel"},{"item_id":"item_binder_chest"},{"item_id":"item_tee_singularity"},{"item_id":"item_hoodie_grey"},{"item_id":"item_croptop_fishnet"},{"item_id":"item_tee_mascot"},{"item_id":"item_shirt_flannel"},{"item_id":"item_halter_backless"},{"item_id":"item_sweater_ugly"},{"item_id":"item_jacket_denim"},{"item_id":"item_blouse_sheer_wrap"},{"item_id":"item_tee_offbrand_security"},{"item_id":"item_jeans_relaxed"},{"item_id":"item_shorts_cargo"},{"item_id":"item_leggings_latex"},{"item_id":"item_sweatpants_grey"},{"item_id":"item_shorts_micro"},{"item_id":"item_trousers_clown"},{"item_id":"item_sneakers_canvas"},{"item_id":"item_slippers_monster"},{"item_id":"item_boots_thigh_heel"},{"item_id":"item_sandals_strap"},{"item_id":"item_cap_trucker_slogan"},{"item_id":"item_bucket_hat"},{"item_id":"item_veil_lace"},{"item_id":"item_gloves_fingerless"},{"item_id":"item_gloves_lace_opera"},{"item_id":"item_collar_leather"},{"item_id":"item_fannypack"},{"item_id":"item_tote_canvas"},{"item_id":"item_reagent_acid"},{"item_id":"item_reagent_solvent"},{"item_id":"item_reagent_feedstock"},{"item_id":"item_reagent_nutrient"}]'::jsonb, 46, 3, 33, 'vendor', '{"fri":[{"to":22,"from":10}],"mon":[{"to":22,"from":10}],"sat":[{"to":22,"from":10}],"sun":[{"to":22,"from":10}],"thu":[{"to":22,"from":10}],"tue":[{"to":22,"from":10}],"wed":[{"to":22,"from":10}]}'::jsonb, 69, 'Second Skin', '["stitches something under a low light, squinting","\"Texture, contrast, silhouette. In that order.\"","lays out three different fabric swatches side by side","carefully hangs a jacket, adjusts it twice, then a third time","\"If I had better thread this would be perfect.\"","cuts a pattern piece from a paper template with quiet precision","holds two colors up to the window and stares at them for a long moment"]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_1783019600726', 'Vesper Cole', 'Moves like she''s already spent the money you haven''t given her yet. A faded hospital band, cut loose long ago, still rings one wrist — a story she never finishes, no matter how much you tip for it.', 'zone_mq_cherry_floor', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"stripper":true,"mis_willing":true,"personality":"stripper","clothing_layers":["a sequined slip dress","a lace bralette","a satin thong"],"mis_requires_zone_flag":"mis_ok"}'::jsonb, '{"nodes":{"start":{"next":"check_work","type":"start"},"deposit":{"next":"post_shift","type":"action","action_type":"VENDOR_DEPOSIT"},"atm_wait":{"next":"deposit","type":"wait","seconds":10},"work_say":{"next":"check_work","type":"action","action_type":"VENDOR_CHITCHAT"},"atm_emote":{"next":"atm_wait","type":"action","params":{"message":"steps up to the ATM terminal and makes a deposit."},"action_type":"EMOTE"},"go_to_atm":{"next":"atm_emote","type":"action","action_type":"VENDOR_GO_TO_ATM"},"have_life":{"next":"check_work","type":"action","action_type":"HAVE_LIFE"},"home_idle":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"work_wait":{"next":"player_check","type":"wait","seconds":60},"check_work":{"type":"action","offWork":"off_home_check","endShift":"collect_safe","goToWork":"go_to_work","haveLife":"have_life","action_type":"CHECK_VENDOR_WORK"},"go_home_ps":{"next":"home_life_ps","type":"action","action_type":"GO_HOME"},"go_to_work":{"next":"work_wait","type":"action","action_type":"GO_TO_WORK"},"off_random":{"type":"random","branch_0":"have_life","branch_1":"go_home_off","branches":[{"weight":1},{"weight":5}]},"post_shift":{"type":"random","branch_0":"have_life","branch_1":"go_home_ps","branches":[{"weight":1},{"weight":5}]},"go_home_off":{"next":"check_work","type":"action","action_type":"GO_HOME"},"collect_safe":{"next":"go_to_atm","type":"action","action_type":"VENDOR_COLLECT_SAFE"},"home_life_ps":{"next":"check_work","type":"action","action_type":"AT_HOME_LIFE"},"player_check":{"type":"condition","ifTrue":"work_say","ifFalse":"check_work","condition_type":"PLAYER_IN_ZONE"},"off_home_check":{"type":"condition","ifTrue":"home_idle","ifFalse":"off_random","condition_type":"AT_HOME"}},"_start":"start"}'::jsonb, 'zone_mq_chrome_303', NULL, 'zone_mq_cherry_vip', '[]'::jsonb, 20, 20, 'female', '[]'::jsonb, 10, 1, 0, 'npc', '{"fri":[{"to":24,"from":19}],"mon":[{"to":24,"from":19}],"sat":[{"to":24,"from":19}],"sun":[{"to":24,"from":19}],"thu":[{"to":24,"from":19}],"tue":[{"to":24,"from":19}],"wed":[{"to":24,"from":19}]}'::jsonb, NULL, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_nyra_voss', 'Nyra Voss', 'Nyra Voss moves like she belongs to the city''s electrical current rather than its streets. She is composed, precise, and unnervingly aware of everything around her without ever appearing distracted. Her presence is understated but magnetic — less about overt display and more about controlled integration with technology and environment.', 'zone_meridian_unit_103', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"mis_willing":false,"personality":"unemployed","clothing_layers":["a fraying interview blazer gone shapeless","a coffee-stained blouse","a plain bra and worn panties"]}'::jsonb, '{"nodes":{"start":{"next":"have_life","type":"start"},"at_work":{"next":"go_home","type":"action","action_type":"AT_WORK"},"go_home":{"next":"home_wait","type":"action","action_type":"GO_HOME"},"have_life":{"next":"go_to_work","type":"action","action_type":"HAVE_LIFE"},"home_wait":{"next":"start","type":"wait","seconds":60},"go_to_work":{"next":"at_work","type":"action","action_type":"GO_TO_WORK"}},"_start":"start"}'::jsonb, 'zone_meridian_unit_103', NULL, NULL, '["traces a finger along the edge of a nearby surface without looking at it.","glances toward the nearest data terminal, expression unreadable.","adjusts the interface contacts on her gloves with quiet precision.","appears to be processing something — her iris ring shifts almost imperceptibly.","is perfectly still, which somehow feels deliberate.","scans the room with the easy calm of someone who already knows every exit.","taps two fingers against her forearm, once.","exhales slowly, like she''s filtering the air for useful information."]'::jsonb, 50, 50, 'female', '[]'::jsonb, 10, 1, 0, 'unemployed', '{"fri":[],"mon":[],"sat":[],"sun":[],"thu":[],"tue":[],"wed":[]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO npcs ("id", "name", "description", "zone_id", "faction", "dialogue_tree", "vendor_inventory", "wanders", "flags", "behaviour_graph", "home_zone", "studio_zone_id", "work_zone_id", "chitchat", "hp", "hp_max", "sex", "vendor_stock", "vendor_stock_size", "vendor_restock_rate", "vendor_credits", "npc_type", "vendor_schedule", "vendor_bank_credits", "vendor_shop_name", "home_activities", "banter", "wander_zones") VALUES ('npc_dex_rime', 'Dex Rime', 'A broadcast studio host.', 'zone_city_north', NULL, '{}'::jsonb, '[]'::jsonb, 0, '{"studio_npc":true,"mis_willing":false}'::jsonb, '{"nodes":{"n_life":{"next":"n_loop","type":"action","action_type":"HAVE_LIFE"},"n_loop":{"next":"n_start","type":"loop"},"n_start":{"next":"n_life","type":"start"}},"_start":"n_start"}'::jsonb, 'zone_studio_1782953094650', NULL, NULL, '[]'::jsonb, 20, 20, 'male', '[]'::jsonb, 10, 1, 0, 'npc', '{"fri":[{"to":22,"from":10}],"mon":[{"to":22,"from":10}],"sat":[{"to":22,"from":10}],"sun":[{"to":22,"from":10}],"thu":[{"to":22,"from":10}],"tue":[{"to":22,"from":10}],"wed":[{"to":22,"from":10}]}'::jsonb, 0, NULL, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_ficus_zone_meridian_lobby', 'zone_meridian_lobby', 'dead ficus', 'A ficus in a chipped ceramic planter, dead so long it has gone the grey of old newspaper. And yet the soil is damp — someone keeps watering it. Hope is a hard habit to break.', '{}'::jsonb, 'decoration', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_bench_zone_meridian_lobby', 'zone_meridian_lobby', 'cracked vinyl bench', 'A low waiting bench upholstered in oxblood vinyl, split along every seam and weeping yellow foam. It has absorbed forty years of people waiting for elevators that stopped working in year three. It still holds weight, if you don''t mind the crunch.', '{"interactions":["sit","lean"]}'::jsonb, 'furniture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_47054b84', 'zone_apt_2', 'neural interface couch', 'Long enough to lie flat in, upholstered in smart-foam that tracks your body temperature. Three data ports run along the headrest.', '{"interactions":["sit","lie"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 3200, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_1782683782251', 'zone_residential_lobby', 'citadel financial ATM terminal', 'A sleek black ATM glows beneath flickering neon, its holographic display cycling ads between transactions. Biometric scanners and an armored card slot sit beneath a scratched, graffiti-covered shell, weathered by the city''s streets.', '{"atm":true,"interactions":[]}'::jsonb, 'terminal', 0, NULL, 5, NULL, 400, 12000, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_apt1_hotplate', 'zone_apt_1', 'hot plate', 'A two-burner electric hot plate plugged into the wall near the door. One burner glows red when switched on. The other has been dead for a while.', '{"interactions":[]}'::jsonb, 'fixture', 0, 'lamp', NULL, NULL, NULL, 45, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_embassy_corkboard', 'zone_residential_lobby', 'unit listings corkboard', 'Bolted over what used to be the concierge desk. Handwritten unit listings cover every inch, half of them crossed out and re-listed at a worse price.', '{"interactions":[]}'::jsonb, 'fixture', 0, 'lamp', NULL, NULL, NULL, 25, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_mailboxes_zone_meridian_lobby', 'zone_meridian_lobby', 'tenant mailboxes', 'A bank of aluminum tenant mailboxes bolted to the east wall, most pried open decades ago — little doors hanging off single hinges, keyholes drilled out. A yellowed flyer for a pizza place that no longer exists is still wedged in slot 4C. Nobody here is expecting mail.', '{}'::jsonb, 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_apt12_lamp', 'zone_apt_12', 'portable lamp', 'A battered work lamp on the floor, doing the job of the fixtures stripped out of the ceiling. Its shade throws a warm cone up the wall and leaves the corners to themselves.', '{"interactions":["switch"]}'::jsonb, 'light', 1, 'lamp', 5, NULL, 400, 30, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_apt2_cot', 'zone_apt_2', 'metal-framed cot', 'A narrow army-surplus cot with a thin mattress and a wool blanket folded at the foot. Functional, if not comfortable.', '{"interactions":["sit","lie"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 70, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_1782511287046', 'zone_residential_lobby_z-1_1782105292491', 'overhead light', 'A bare bulb on a pull-chain. Functional, nothing more.', '{"interactions":["switch"]}'::jsonb, 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_apt12_bed', 'zone_apt_12', 'wide bed', 'A broad bed under the window, wide enough for two who trust each other. The far side of the building from the bar — as quiet as the Embassy gets.', '{"interactions":["sit","lie"]}'::jsonb, 'furniture', 0, NULL, NULL, NULL, NULL, 120, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_embassy_stools', 'zone_residential_lobby', 'cracked vinyl stools', 'A half-dozen stools lined up at the counter, vinyl split and patched with duct tape. Free to sit, if you don''t mind the wobble.', '{"interactions":["sit"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 35, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_apt12_wardrobe', 'zone_apt_12', 'mirrored wardrobe', 'A freestanding wardrobe with a full-length mirror gone black and blistered at the edges. Your reflection stands in the clear middle, hemmed in by the dark.', '{"interactions":["lean"]}'::jsonb, 'fixture', 0, NULL, NULL, NULL, NULL, 90, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_apt2_poster', 'zone_apt_2', 'faded travel poster', 'A glossy travel poster, sun-bleached to pastel. A beach. Palm trees. A slogan that has faded to illegibility. Whoever left it here was thinking of somewhere else.', '{"interactions":[]}'::jsonb, 'fixture', 0, 'lamp', NULL, NULL, NULL, 15, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_1782365983389', 'zone_thresholdeast', 'graffiti: COUNT YOUR DAYS', 'Scratched directly into the inside of the door, deep enough that it can''t be painted over. COUNT YOUR DAYS. Below it, someone has scratched a smaller reply: I DID. STILL HERE.', '{"interactions":[]}'::jsonb, 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_1782276836159', 'zone_start', 'overhead light', 'A bare bulb on a pull-chain. Functional, nothing more.', '{"interactions":["switch"]}'::jsonb, 'light', 1, 'overhead', 20, NULL, 1200, 40, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_secdesk_zone_meridian_lobby', 'zone_meridian_lobby', 'security desk', 'A curved reception desk in scuffed laminate, built to be manned around the clock. The chair behind it is long gone. A dead terminal cycles a screensaver of rolling static, throwing a faint grey flicker across the underside of the counter. A coffee ring older than most of the tenants has fossilized on the surface.', '{"interactions":["lean"]}'::jsonb, 'fixture', 0, NULL, NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_embassy_bar_counter', 'zone_residential_lobby', 'the embassy lounge bar', 'A scarred wooden counter beneath the brass THE EMBASSY LOUNGE sign. Lowry keeps it spotless out of sheer habit.', '{"interactions":["lean"]}'::jsonb, 'fixture', 0, 'lamp', NULL, NULL, NULL, 2500, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_apt1_crate', 'zone_apt_1', 'wooden crate', 'A salvaged shipping crate pressed into service as a side table and spare seat. FRAGILE is stenciled on the side, which stopped being relevant some time ago.', '{"interactions":["sit","lean"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 20, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_sl_zone_thresholdeast', 'zone_thresholdeast', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}'::jsonb, 'light', 1, 'streetlight', 200, NULL, 8000, 0, NULL, NULL) ON CONFLICT DO NOTHING;
