INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('secdev_pd_zone_city_east', 'zone_city_east', 'PD street camera', 'A hardened municipal camera on a tall pole, blue status light steady. A decal reads SPECTER-PD — SMILE.', '{"concealed":false,"device_id":"secdev_pd_zone_city_east","security_device":true}'::jsonb, 'security_device', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
