INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_basement_chair', 'zone_residential_lobby_z-1_1782105292491', 'broken office chair', 'A wheeled office chair with a cracked backrest and one arm missing. It still rolls, barely, and takes your weight if you sit carefully.', '{"interactions":["sit"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 20, NULL, NULL) ON CONFLICT DO NOTHING;
