INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_apt9_desk', 'zone_apt_9', 'wall-bolted desk', 'A slab of desk bolted flush to the wall so nobody can carry it off. Someone did their thinking here — the surface is ringed with coffee and scored with crossed-out sums.', '{"interactions":["lean"]}'::jsonb, 'fixture', 0, NULL, NULL, NULL, NULL, 70, NULL, NULL) ON CONFLICT DO NOTHING;
