INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_generator_coldwater', 'zone_coldwater_turbine_hall', 'coldwater main generator', 'A colossal city-grade turbine generator, its armoured casing streaked with grime and hazard chevrons. Banks of indicator lights stutter across its control face; a heavy sealed hacking port is bolted shut beneath a cracked screen. It ROARS.', '{"destructible":true,"generator_id":"gen_zone_powerplantnew_1782069598190","requires_demolition":true}'::jsonb, 'generator', 0, 'lamp', NULL, NULL, NULL, 0, 5000, 5000) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_1782698855727', 'zone_warehouse', 'notice board', 'A thick slab of cork bolted to a sheet of armored steel, repaired so many times it''s become sturdier than the wall behind it. Flyers overlap handwritten notes, official-looking forms, faded family photos, and at least three declarations of eternal vengeance. Someone keeps tidying it every morning, which is either comforting or deeply unsettling.', '{"bulletin":true,"interactions":[]}'::jsonb, 'furniture', 0, NULL, 5, NULL, 400, 25, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('secdev_pd_zone_residential_lobby_z-1_1782105292491', 'zone_residential_lobby_z-1_1782105292491', 'PD street camera', 'A hardened municipal camera on a tall pole, blue status light steady. A decal reads SPECTER-PD — SMILE.', '{"concealed":false,"device_id":"secdev_pd_zone_residential_lobby_z-1_1782105292491","security_device":true}'::jsonb, 'security_device', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_vendor_safe_juno', 'zone_furniture_store', 'phantom vault', 'A matte-black security enclosure about the size of a microwave oven, bolted directly into the structural concrete behind the counter. The door has no visible seam, no keyway, no biometric reader. The entire face is a single panel of electrochromic glass that cycles between mirror, opaque, and — briefly — translucent, though there is nothing visibly inside when it clears. A holographic lock interface shimmers above the surface: a rotating key rendered in the 8–14nm band, invisible to the naked eye. The frequency shifts every ninety seconds. Etched in the concrete beside it in small, precise letters: PROPERTY OF VENDOR. MONITORED.', '{"vendor_safe":true,"vendor_npc_id":"npc_juno_kael","hack_difficulty":5}'::jsonb, 'fixture', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_apt2_crate', 'zone_apt_2', 'plastic storage crate', 'A heavy-duty plastic crate — the kind you find in a demolished warehouse — doing duty as a bedside table. A candle stub sits on top of it.', '{"interactions":["sit","lean"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 25, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_cell_weightbench', 'zone_mq_precinct_holding', 'prison weight bench', 'A slab of a bench welded from scrap rebar and a cracked vinyl pad, bolted to the floor so nobody gets ideas about swinging it. The plates are mismatched chunks of poured concrete on a bent bar, worn smooth by a thousand bored inmates. It is, somehow, the most honest thing in the building.', '{"interactions":["lie","lift"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_cell_toilet', 'zone_mq_precinct_holding', 'steel cell toilet', 'A seatless steel toilet-and-basin combo bolted to the cinderblock, scuffed to a dull shine by a decade of reluctant use. No lid, no privacy, no dignity — just cold metal and a slow, resigned trickle.', '{}'::jsonb, 'toilet', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_cell_sink', 'zone_mq_precinct_holding', 'stainless cell sink', 'A knuckle-sized stainless basin jutting from the wall above the toilet. One push-button tap coughs out a thin stream of cold water — enough to drink, or to scrub the worst of the night off your hands.', '{"water_source":true}'::jsonb, 'sink', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_cell_cot', 'zone_mq_precinct_holding', 'bolted steel cot', 'A steel shelf welded to the wall, topped with a vinyl pad the thickness of a sympathy card. It is not comfortable. It is, technically, a place to lie down until the clock lets you out.', '{"interactions":["sit","lie"]}'::jsonb, 'furniture', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_apt2_hardcase', 'zone_apt_2', 'Nexis biometric hardcase', 'A matte-black composite case the size of a footlocker, its corners scuffed down to bare alloy. A biometric pad glows a patient amber above the seam — jailbroken, by the look of it, the lock light stuttering between green and red. Heavier than it has any right to be.', '{"container":40000}'::jsonb, 'container', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_hero_poster_kiyo', 'zone_apt_1', 'hero poster: KIYO, THE GRID-BREAKER', 'A heavy-stock poster, its edges scorched like it was printed too close to something on fire. Kiyo stands hip-deep in a nest of torn cabling and cracked-open server towers, sleeves shoved past the elbow, a soldering iron in one fist and a length of live wire in the other, sparks hanging frozen around a face that hasn''t slept and doesn''t intend to. Behind him a dead machine is grinding back to life at his say-so. KIYO — HE DOESN''T FIX THE MACHINE. HE MAKES IT AFRAID OF HIM. Stencilled below in service-manual type: "give him ten minutes and a junction box and he''ll hand you a weapon, a bomb, or a way out — his call." A real strand of copper wire is threaded through two punched holes, worried bright by passing thumbs.', '{"poster_key":"kiyo","hero_poster":true}'::jsonb, 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_emerglight_zone_meridian_lobby', 'zone_meridian_lobby', 'emergency light bar', 'A wall-mounted emergency light bar on a trickle-charged cell, casting the pale amber wash the lobby is named for. It stays lit when the grid drops — about the only promise this building still keeps.', '{}'::jsonb, 'light', 1, 'emergency', 5, NULL, 350, 25, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_sl_zone_mq_battery', 'zone_mq_battery', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}'::jsonb, 'light', 1, 'streetlight', 200, NULL, 8000, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_1783065860962', 'zone_residential_lobby', 'shoddy television', 'A battered flatscreen bolted to the wall with mismatched screws. The casing is cracked and one corner is held together with duct tape, but the picture still comes through.', '{"tv":true,"interactions":["watch"],"tv_dial_freq":7,"broadcast_receiver":true,"broadcast_device_type":"tv"}'::jsonb, 'furniture', 0, NULL, 5, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_hero_poster_ocelot', 'zone_residential_lobby', 'hero poster: OCELOT, THE SHADOW THAT GUARDS', 'A sleek, expensive-looking poster — someone spent real money on this one. A silhouette crouches on a gargoyle of rebar, eyes rendered as two slit-pupil coins of reflective foil that catch you wherever you stand. OCELOT WATCHES THE STREET SO THE STREET NEVER SLEEPS ALONE. Below, in a smaller, warmer font: "sightings unconfirmed. that''s the point." The foil eyes have been half-peeled by someone who wanted the shiny bit.', '{"poster_key":"ocelot","hero_poster":true}'::jsonb, 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_schd_npc_salvage_broker', 'zone_slag_gate', 'Voss Iyaka''s Schedule', 'Voss Iyaka''s Schedule
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_hero_poster_alphagunman', 'zone_meridian_lobby', 'hero poster: ALPHAGUNMAN, THE LAST STRAIGHT SHOOTER', 'A high-contrast poster built like a wanted bill turned inside-out — not WANTED but WANTED BACK. A gunfighter stands centred and unhurried against a white noon, coat open, hands empty and loose, because the poster wants you to understand he doesn''t need to reach. ALPHAGUNMAN NEVER FIRED FIRST. HE NEVER HAD TO FIRE SECOND EITHER. The paper is punched clean through by a single old bullet hole, dead centre, which someone has helpfully circled and labelled "exhibit A."', '{"poster_key":"alphagunman","hero_poster":true}'::jsonb, 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_hero_poster_stabbz', 'zone_mq_sump_bar', 'hero poster: STABBZ, THE PEOPLE’S SCALPEL', 'A heroic poster in deep arterial reds, the ink already flaking. A lean figure stands astride a heap of the vanquished, a knife raised to a stormbreak sky, its edge catching a light that isn''t in the rest of the picture. THE PEOPLE''S SCALPEL, the banner proclaims, HE CUTS ONLY WHAT NEEDS CUTTING. The fine print at the bottom, tiny and legal, adds: "definition of ''needs'' at the sole discretion of Stabbz." A brown handprint is dried across one corner.', '{"poster_key":"stabbz","hero_poster":true}'::jsonb, 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furniture_streetlight_zone_city_east', 'zone_city_east', 'street lights', 'A row of city-grid streetlights on cracked poles, wired back to the power station. No switch out here — they come on by themselves once it gets dark.', '{}'::jsonb, 'light', 1, 'streetlight', 200, NULL, 8000, 200, NULL, NULL) ON CONFLICT DO NOTHING;
