INSERT INTO furniture ("id", "zone_id", "name", "description", "flags", "object_type", "light_on", "light_type", "power_draw_kw", "light_on_intended", "lumen_output", "price", "hp", "hp_max") VALUES ('furn_hero_poster_cyd', 'zone_mq_cherry_floor', 'hero poster: CYD, THE HAND ON THE BREAKER', 'A poster printed on the same heavy, scorch-edged stock as the one it was torn from. Cyd stands with one boot up on a dead industrial generator the size of a coffin, forearm resting across her knee, utterly unhurried while the skyline behind her browns out floor by floor. A single heavy cable runs from the machine off the left edge of the frame — cut clean, as though it once continued somewhere. CYD — SHE DECIDES WHEN THE POWER COMES BACK. Stencilled beneath in utility-company type: "blackout or dawn, it''s her hand on the breaker, and she is in no hurry to tell you which one you''ve earned." A real length of copper wire, worried bright by passing thumbs, is threaded through two punched holes along the torn left edge.', '{"poster_key":"cyd","hero_poster":true}'::jsonb, 'decoration', 0, 'lamp', NULL, NULL, NULL, 0, NULL, NULL) ON CONFLICT DO NOTHING;
