INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_slow', 'Slow', 'Dulls pain and panic. Popular with people who have seen too much.', 'item_drug_slow', 600, '{"hp":5,"sanity":15}'::jsonb, 0.12, 2, '{"overdose":{"hp":-20,"sanity":-15}}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_glasshollow', 'Glasshollow', 'Architect-adjacent. Reality gets thin and strange. Sanity damage is real; so is whatever you see.', 'item_drug_glasshollow', 180, '{"sanity":-10,"radiation":5}'::jsonb, 0.2, 2, '{"overdose":{"hp":-25,"sanity":-30}}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_coldfire', 'Coldfire', 'A combat stim that turns fear into fuel. Frontline mercs swear by it, and at it.', 'item_coldfire', 240, '{"phases":{"peak_mods":{"hp_max":30,"stat_brawn":5,"stat_endurance":3,"hp_regen_per_sec":1},"end_message":"<span class=\"msg-system\">The fire gutters out. Every wound you ignored is suddenly very loud.</span>","comeup_scale":0.6,"peak_message":"<span class=\"msg-system\">Cold fire floods your veins. Pain becomes a distant rumour.</span>","peak_seconds":140,"comedown_scale":0.6,"comeup_seconds":10,"comedown_seconds":90},"instant":{"hunger":-12,"sanity":6},"diuretic":1.5,"overdose":{"lethal":true,"message":"Your body cannot tell it is dying. It sprints straight past the edge."},"tolerance":{"gain_per_dose":0.15,"max_reduction":0.7},"withdrawal":{"mods":{"stat_brawn":-3,"stat_endurance":-2},"message":"Everything aches. Coldfire fixes that. Coldfire fixes everything.","onset_seconds":1200}}'::jsonb, 0.35, 3, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_static', 'Static', 'A nootropic mist for the overclocked mind. Clarity in a can, with interest.', 'item_static', 360, '{"phases":{"peak_mods":{"stat_brains":4,"sanity_regen_per_sec":1},"end_message":"<span class=\"msg-system\">The signal degrades. Thoughts go grainy again.</span>","comeup_scale":0.5,"peak_message":"<span class=\"msg-system\">The static clears. You can see the shape of every problem at once.</span>","peak_seconds":240,"comedown_scale":0.5,"comeup_seconds":30,"comedown_seconds":90},"instant":{"sanity":10},"diuretic":1.4,"overdose":{"lethal":true,"message":"Too much signal, no more silence. Your mind whites out and does not come back."},"tolerance":{"gain_per_dose":0.1,"max_reduction":0.6}}'::jsonb, 0.18, 4, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_blacktar', 'Blacktar', 'Heavy tar opioid, cut with whatever was nearby. The deepest nod there is.', 'item_blacktar', 480, '{"phases":{"peak_mods":{"stat_brains":-3,"stat_reflexes":-5,"hp_regen_per_sec":3},"end_message":"<span class=\"msg-system\">You surface, gasping, into a world that got worse while you were gone.</span>","comeup_scale":0.6,"peak_message":"<span class=\"msg-system\">You go under. The tar closes over your head, black and total and perfect.</span>","peak_seconds":300,"comedown_scale":0.6,"comeup_seconds":20,"comedown_seconds":160},"instant":{"hunger":-6,"sanity":18},"diuretic":0.4,"overdose":{"lethal":true,"message":"The nod goes all the way down and does not turn around."},"tolerance":{"gain_per_dose":0.18,"max_reduction":0.8,"recovery_per_sec":0.0001},"withdrawal":{"mods":{"hp_max":-25,"stat_cool":-4,"stat_brawn":-3,"stat_endurance":-4},"message":"Withdrawal has you by the spine. You would trade almost anything to make it stop.","onset_seconds":480}}'::jsonb, 0.6, 2, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_lull', 'Lull', 'A blue benzo tab that files the sharp edges off a bad night.', 'item_lull', 360, '{"phases":{"peak_mods":{"stat_cool":3,"stat_reflexes":-2,"sanity_regen_per_sec":1},"end_message":"<span class=\"msg-system\">The calm wears thin and the worries file back in.</span>","comeup_scale":0.5,"peak_message":"<span class=\"msg-system\">The panic unclenches. Whatever it was, it can wait.</span>","peak_seconds":240,"comedown_scale":0.5,"comeup_seconds":30,"comedown_seconds":90},"instant":{"sanity":16},"diuretic":0.7,"overdose":{"lethal":true,"message":"You lie down to rest your eyes for just a second, and never open them."},"tolerance":{"gain_per_dose":0.12,"max_reduction":0.7},"withdrawal":{"mods":{"stat_cool":-3,"sanity_regen_per_sec":-1},"message":"Your nerves are live wires again. You remember exactly what fixes that.","onset_seconds":900}}'::jsonb, 0.3, 3, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_psilocybin', 'Psilocybin', 'A handful of wrinkled grey mushrooms grown in somebody''s ventilation duct.', 'item_psilocybin', 240, '{"instant":{"sanity":-4},"tolerance":{"gain_per_dose":0.3,"max_reduction":0.9,"recovery_per_sec":0.0003},"hallucination":{"mode":"overlay","palette":"purple","eventPool":["[trip]The walls take a slow, deliberate breath.[/trip]","[trip]The floor is a carpet of soft breathing moss now. It doesn''t mind you standing on it.[/trip]","[trip]Every surface is faintly patterned with eyes, all of them kind.[/trip]","[trip]You can hear the colour green. It sounds like your grandmother''s kitchen.[/trip]","[trip]Time pools in the corners of the room like warm honey.[/trip]","[trip]A shaft of light bends toward you and asks, without words, if you are okay.[/trip]"],"intensity":0.5,"eventEverySec":12,"duration_seconds":240}}'::jsonb, 0.02, 6, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_blotter', 'Blotter', 'A single square of high-powered blotter acid, printed with a grinning sun.', 'item_blotter', 600, '{"instant":{"sanity":-8},"tolerance":{"gain_per_dose":0.4,"max_reduction":0.95,"recovery_per_sec":0.0002},"hallucination":{"mode":"overlay","palette":"magenta","eventPool":["[trip]The room inhales and the walls flow outward into cathedral vaults of liquid light.[/trip]","[trip]Fractal vines of every impossible colour crawl up from the floor and flower midair.[/trip]","[trip]Your own hands leave glowing trails, a hundred hands fanning out from your wrists.[/trip]","[trip]Sound has texture. A distant machine hum is velvet dragged across your teeth.[/trip]","[trip]The grinning sun from the tab is on the ceiling now, and it winks at you.[/trip]","[trip]You are absolutely certain, for one perfect second, that you understand it all.[/trip]","[trip]A stranger who is also you steps out of the wall, waves, and folds back in.[/trip]"],"intensity":0.8,"eventEverySec":14,"duration_seconds":600}}'::jsonb, 0.01, 8, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_mescaline', 'Mescaline', 'Seventy-five pellets rattle in a little tin. You only need a few.', 'item_mescaline', 480, '{"instant":{"hunger":-6,"sanity":-6},"tolerance":{"gain_per_dose":0.3,"max_reduction":0.9},"hallucination":{"mode":"overlay","palette":"gold","eventPool":["[trip]Everything is edged in shimmering gold, as if the world were a coin held to the light.[/trip]","[trip]Geometric patterns bloom across every wall, precise and ancient and alive.[/trip]","[trip]Your stomach rolls, but the nausea is just the door you have to walk through.[/trip]","[trip]A desert wind you cannot feel moves the shadows in long slow waves.[/trip]","[trip]An old voice, patient as stone, tells you a story in a language you were born knowing.[/trip]"],"intensity":0.7,"eventEverySec":13,"duration_seconds":480}}'::jsonb, 0.02, 6, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_screamers', 'Screamers', 'A designer psychedelic that does not do gentle. Roll the dice.', 'item_screamers', 300, '{"instant":{"sanity":-18},"tolerance":{"gain_per_dose":0.25,"max_reduction":0.85},"hallucination":{"mode":"overlay","palette":"red","eventPool":["[trip]The walls are the wrong colour. They know they are the wrong colour. They are furious about it.[/trip]","[trip]Something enormous is screaming just below the range of hearing and it is getting closer.[/trip]","[trip]Your reflection in every surface is a half-second behind you, and grinning.[/trip]","[trip]The floor tilts. The ceiling drips. None of it is trying to help you.[/trip]","[trip]You are being watched by the architecture and it does not like what it sees.[/trip]","[trip]For a moment you are certain you have always been here and will never leave.[/trip]"],"intensity":1,"eventEverySec":10,"duration_seconds":300}}'::jsonb, 0.08, 5, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_laughers', 'Laughers', 'Little yellow tabs that turn the apocalypse into the funniest thing you have ever seen.', 'item_laughers', 240, '{"instant":{"sanity":20},"tolerance":{"gain_per_dose":0.2,"max_reduction":0.8},"hallucination":{"mode":"overlay","palette":"gold","eventPool":["[trip]The sheer absurdity of everything hits you and you have to lean on a wall, wheezing.[/trip]","[trip]That grim little machine in the corner looks, on reflection, deeply and hilariously stupid.[/trip]","[trip]Someone somewhere is taking all of this seriously and that is the funniest part.[/trip]","[trip]You catch your own reflection making a face and completely lose it.[/trip]","[trip]Even the dread feels like a joke with a punchline you already know.[/trip]"],"intensity":0.5,"eventEverySec":12,"duration_seconds":240}}'::jsonb, 0.1, 5, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_ether', 'Ether', 'A pint of raw ether and a rag. Not the smart choice, but here we are.', 'item_ether', 120, '{"instant":{"sanity":-10},"diuretic":1.2,"overdose":{"lethal":true,"message":"You breathe in one rag too many. The lights go out mid-thought."},"hallucination":{"mode":"overlay","palette":"cyan","eventPool":["[trip]The floor lurches sideways and the room smears into long cold streaks.[/trip]","[trip]Your thoughts arrive out of order, each one wrapped in cotton wool.[/trip]","[trip]You are extremely far away from your own hands.[/trip]","[trip]A chemical wind blows straight through your skull and out the other side.[/trip]"],"intensity":0.6,"eventEverySec":10,"duration_seconds":120}}'::jsonb, 0.15, 3, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_threshold', 'The Threshold', 'A single breath of vaporised DMT-analog. Ten thousand years in four hundred seconds.', 'item_threshold', 200, '{"instant":{"sanity":-12},"tolerance":{"gain_per_dose":0.2,"max_reduction":0.6},"hallucination":{"mode":"dreamzone","events":[{"text":"[trip]The room peels away like wet paper and you fall UP through it.[/trip]","atSec":4},{"text":"[trip]The machine-elves are showing you something. It is the most important thing there is.[/trip]","atSec":30},{"text":"[trip]You have been here before. You have always been here. You live here.[/trip]","atSec":80},{"text":"[trip]The cathedral begins, very gently, to fold you back up and post you home.[/trip]","atSec":140}],"palette":"magenta","intensity":1,"dreamzone_id":"zone_dream_threshold","eventEverySec":20,"duration_seconds":180}}'::jsonb, 0.01, 6, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_khole', 'K-Hole', 'A dissociative dust that unplugs you from your own body for a while.', 'item_khole', 240, '{"instant":{"sanity":-8},"overdose":{"lethal":true,"message":"You go so far down the hole that you forget the way back, and your body forgets to breathe."},"tolerance":{"gain_per_dose":0.2,"max_reduction":0.8},"withdrawal":{"mods":{"stat_brains":-2},"message":"The grey funnel calls. You keep glancing toward the door that isn''t there.","onset_seconds":1800},"hallucination":{"mode":"dreamzone","palette":"blue","eventPool":["[trip]You slide a little further down the smooth grey funnel.[/trip]","[trip]Your body is somewhere behind you now, waving. You wave back, or think about it.[/trip]","[trip]Continents of thought drift past, too large and too slow to be afraid of.[/trip]","[trip]Someone is speaking. It might be you. It was a long time ago.[/trip]"],"intensity":0.7,"dreamzone_id":"zone_dream_khole","eventEverySec":18,"duration_seconds":200}}'::jsonb, 0.12, 4, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_voidwalk', 'Voidwalk', 'A designer dissociative that drops you into the static between channels.', 'item_voidwalk', 300, '{"instant":{"sanity":-14},"overdose":{"lethal":true,"message":"The static pulls you all the way under and keeps the channel dark."},"tolerance":{"gain_per_dose":0.2,"max_reduction":0.8},"hallucination":{"mode":"dreamzone","palette":"cyan","eventPool":["[trip]The static sea hums your name and you feel it in your back teeth.[/trip]","[trip]A memory swims past wearing someone else''s face. It nods at you.[/trip]","[trip]An advertisement for a product that does not exist plays across the whole sky.[/trip]","[trip]You wade deeper. The blue closes over your knees, your chest, your reasons for leaving.[/trip]"],"intensity":0.9,"dreamzone_id":"zone_dream_void","eventEverySec":20,"duration_seconds":260}}'::jsonb, 0.1, 4, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_memhack', 'Memhack', 'A memory-editing synth. Sands the barbs off your worst recollections. Mostly.', 'item_memhack', 360, '{"phases":{"peak_mods":{"stat_cool":3,"sanity_regen_per_sec":1},"end_message":"<span class=\"msg-system\">The edits settle. A few of the barbs quietly grow back.</span>","comeup_scale":0.5,"peak_message":"<span class=\"msg-system\">Old wounds you carry go soft and distant, like they happened to someone else.</span>","peak_seconds":240,"comedown_scale":0.5,"comeup_seconds":30,"comedown_seconds":90},"instant":{"sanity":24},"overdose":{"lethal":true,"message":"It edits one memory too many — the one where your heart remembers to beat."},"tolerance":{"gain_per_dose":0.12,"max_reduction":0.7},"withdrawal":{"mods":{"stat_cool":-2,"sanity_regen_per_sec":-1},"message":"The memories come back sharp and all at once. Only memhack files them down.","onset_seconds":1200}}'::jsonb, 0.2, 4, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_amyls', 'Amyls', 'Two dozen amyls in a rattling little box. A brief, roaring rush.', 'item_amyls', 60, '{"phases":{"peak_mods":{"stat_brawn":2,"stat_reflexes":2},"end_message":"<span class=\"msg-system\">The rush drops out from under you as fast as it came.</span>","comeup_scale":0.8,"peak_seconds":30,"comedown_scale":0.5,"comeup_message":"<span class=\"msg-system\">A hot rush slams up the back of your neck and the room goes bright and loud.</span>","comeup_seconds":4,"comedown_seconds":26},"instant":{"sanity":6,"horniness_increase":25},"overdose":{"lethal":true,"message":"One popper too many and your blood pressure bottoms out. You fold like a chair."},"tolerance":{"gain_per_dose":0.2,"max_reduction":0.7}}'::jsonb, 0.1, 4, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_beer', 'Beer', 'A mild buzz. Takes the edge off.', 'item_drug_beer', 240, '{"instant":{"hunger":3,"sanity":3,"thirst":12},"diuretic":2,"overdose":{"lethal":true,"message":"You''ve had far too much, far too fast. The room spins hard, your stomach heaves, and then everything just… stops. Alcohol poisoning."}}'::jsonb, 0, 8, '{}'::jsonb, '{"legal":true,"alcoholic":true,"intox_per_dose":22}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_coffee', 'Coffee', 'A jolt of caffeine — sharpens you up for a while.', 'item_drug_coffee', 180, '{"instant":{"sanity":4,"thirst":15},"diuretic":2.5,"overdose":{"lethal":true,"message":"Your heart trips, stutters, and seizes. Too much caffeine, too fast — your chest goes tight and cold, and the world tips over."}}'::jsonb, 0, 6, '{}'::jsonb, '{"legal":true,"sobering":true,"sober_amount":30}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_joint', 'joint', 'A hand-rolled joint, a little crooked, twisted off at the end. Smells like a greenhouse and bad decisions.', 'item_joint', 300, '{"phases":{"peak_mods":{"stat_reflexes":-1},"end_message":"<span class=\"msg-system\">The high tapers off. The colours go back to normal and you are suddenly, urgently thinking about a sandwich.</span>","comeup_scale":0.5,"peak_message":"<span class=\"msg-system\">You are extremely stoned. Everything is faintly hilarious and the music is <em>unbelievable</em>.</span>","peak_seconds":240,"comedown_scale":0.4,"comeup_message":"<span class=\"msg-system\">You spark it up and draw slow. The room exhales with you; the edges go soft and warm.</span>","comeup_seconds":8,"comedown_seconds":60},"instant":{"sanity":6,"thirst":-10},"overdose":{"mods":{"hp":-4,"sanity":-12},"message":"You have smoked far too much. The room tilts, your heart hammers, and a cold wave of paranoid nausea rolls over you. You green out."}}'::jsonb, 0, 5, '{}'::jsonb, '{"legal":true,"cannabis":true,"high_seconds":300}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_cigarettes', 'cigarettes', 'A soft pack of cheap cigarettes. Each one shaves a little off your lungs and hands it to your image.', 'item_cigarettes', 300, '{"phases":{"peak_mods":{"stat_cool":2,"stamina_max":-15},"end_message":"<span class=\"msg-system\">The cigarette burns down to the filter. The cool goes with it; the craving stays.</span>","comeup_scale":0.6,"peak_message":"<span class=\"msg-system\">Nicotine hums through you. You feel, briefly, extremely cool and very slightly winded.</span>","peak_seconds":90,"comedown_scale":0.5,"comeup_message":"<span class=\"msg-system\">You light up and draw deep. Your shoulders drop; the edge comes off your hunger.</span>","comeup_seconds":4,"comedown_seconds":40},"instant":{"sanity":3},"overdose":{"mods":{"hp":-5,"sanity":-8}},"tolerance":{"gain_per_dose":0.1,"max_reduction":0.5},"withdrawal":{"mods":{"stat_cool":-2,"stamina_max":-10},"message":"Your hands are restless and your mood is fraying. You would kill for a cigarette.","onset_seconds":600}}'::jsonb, 0.4, 12, '{}'::jsonb, '{"legal":true,"smokeable":true,"appetite_suppress_seconds":900}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_buzz', 'Buzz', 'A jittery, short-lived stimulant. Common in the Franchise Strip.', 'item_drug_buzz', 240, '{"instant":{"hunger":-5,"stat_agi_temp":2},"diuretic":1.5}'::jsonb, 0.04, 3, '{"overdose":{"hp":-10,"sanity":-5}}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_redline', 'Redline', 'Military-grade cyber-amphetamine. The label is mostly warnings.', 'item_redline', 300, '{"phases":{"peak_mods":{"hp_max":15,"stat_brawn":3,"stat_reflexes":3,"stamina_regen_per_sec":2},"end_message":"<span class=\"msg-system\">The crash lands on you like a dropped ceiling.</span>","comeup_scale":0.4,"peak_message":"<span class=\"msg-system\">You are made of wire and lightning. Nothing can touch you.</span>","peak_seconds":150,"comedown_scale":0.5,"comeup_message":"<span class=\"msg-system\">Your pulse redlines. The world drops into slow motion.</span>","comeup_seconds":20,"comedown_message":"<span class=\"msg-system\">The wire goes slack. Your hands start to shake.</span>","comedown_seconds":90},"instant":{"hunger":-8,"sanity":12,"thirst":-6},"diuretic":1.6,"overdose":{"lethal":true,"message":"Your heart is a fist clenching until it cannot open again."},"tolerance":{"gain_per_dose":0.12,"max_reduction":0.7,"recovery_per_sec":0.0002},"withdrawal":{"mods":{"stat_cool":-2,"stat_reflexes":-2},"message":"Your teeth won''t stop grinding. You need another hit.","onset_seconds":900}}'::jsonb, 0.28, 3, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_overclock', 'Neural Overclock', 'A lace-booster that runs your wetware past the red line. Smoke may be metaphorical.', 'item_overclock', 240, '{"phases":{"peak_mods":{"hp_max":10,"stat_brains":5,"stat_reflexes":4,"sanity_regen_per_sec":-1},"end_message":"<span class=\"msg-system\">The clock drops back to baseline. Your skull throbs where the heat pooled.</span>","comeup_scale":0.5,"peak_message":"<span class=\"msg-system\">You are thinking in parallel now, a dozen threads, all of them screaming.</span>","peak_seconds":150,"comedown_scale":0.6,"comeup_message":"<span class=\"msg-system\">Your lace spins up with a whine only you can hear. The world turns to data.</span>","comeup_seconds":12,"comedown_seconds":78},"instant":{"sanity":-6},"diuretic":1.7,"overdose":{"lethal":true,"message":"Your wetware runs too hot for too long and something delicate inside simply melts."},"tolerance":{"gain_per_dose":0.14,"max_reduction":0.7},"withdrawal":{"mods":{"stat_brains":-3,"stat_reflexes":-2},"message":"Baseline feels like wading through mud. You want the clock back up.","onset_seconds":900}}'::jsonb, 0.3, 3, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_dreamsmoke', 'Dreamsmoke', 'Two bags of engineered grass. Mellow, hungry, harmless-ish.', 'item_dreamsmoke', 300, '{"phases":{"peak_mods":{"stat_cool":2,"stat_reflexes":-1},"end_message":"<span class=\"msg-system\">The mellow lifts. You are mostly just hungry now.</span>","comeup_scale":0.5,"peak_message":"<span class=\"msg-system\">A soft heaviness settles over you. The edges of the room go plush.</span>","peak_seconds":200,"comedown_scale":0.5,"comeup_seconds":20,"comedown_seconds":80},"instant":{"hunger":15,"sanity":12,"thirst":6},"diuretic":0.85,"tolerance":{"gain_per_dose":0.15,"max_reduction":0.7},"hallucination":{"mode":"overlay","palette":"green","eventPool":["[trip]Time slows to a comfortable crawl. There is nowhere you need to be.[/trip]","[trip]You become deeply, urgently aware that you would demolish an entire vending machine of snacks.[/trip]","[trip]A thought drifts by, profound and important, and you completely fail to catch it.[/trip]"],"intensity":0.3,"eventEverySec":20,"duration_seconds":300}}'::jsonb, 0.08, 8, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_grey', 'Grey', 'Synthetic morphine in a grey gelcap. The pain goes away. So does everything else.', 'item_grey', 420, '{"phases":{"peak_mods":{"stat_cool":2,"stat_reflexes":-3,"hp_regen_per_sec":2},"end_message":"<span class=\"msg-system\">The warmth recedes and leaves you cold and small on the shore.</span>","comeup_scale":0.5,"peak_message":"<span class=\"msg-system\">You are floating in warm water in a dark, kind room.</span>","peak_seconds":240,"comedown_scale":0.5,"comeup_message":"<span class=\"msg-system\">A warm grey tide rolls up from your feet. Nothing hurts.</span>","comeup_seconds":25,"comedown_seconds":150},"instant":{"sanity":14},"diuretic":0.5,"overdose":{"lethal":true,"message":"Your breathing slows, and slows, and forgets how."},"tolerance":{"gain_per_dose":0.14,"max_reduction":0.75,"recovery_per_sec":0.00015},"withdrawal":{"mods":{"hp_max":-15,"stat_cool":-3,"stat_endurance":-3},"message":"Your skin crawls, your bones ache, and the whole world is a hand held out for more grey.","onset_seconds":600}}'::jsonb, 0.45, 3, '{}'::jsonb, '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_loose_cannabis', 'loose cannabis', 'A gram of dried, sticky cannabis flower in a little baggie. Useless as-is — roll it into a joint.', 'item_loose_cannabis', 60, '{"instant":{"hunger":-3}}'::jsonb, 0, 5, '{}'::jsonb, '{"sub":"dried","form":"leaf","color":"#5a8a3a","legal":true}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO drugs ("id", "name", "description", "item_id", "duration_seconds", "effects", "addiction_chance", "overdose_threshold", "withdrawal_effects", "flags") VALUES ('drug_loose_tobacco', 'loose tobacco', 'A gram of shredded cured tobacco in a pouch. Roll it into a cigarette — or chew it, if you must.', 'item_loose_tobacco', 60, '{"instant":{"sanity":1}}'::jsonb, 0, 5, '{}'::jsonb, '{"sub":"dried","form":"leaf","color":"#8a6a3a","legal":true}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_extra_eye', 'Extra Eye', 'A third eye has opened on the back of your skull. You see things people don''t.', 'mixed', 1, '{"stat_agi":1}'::jsonb, '{"perception_bonus":2}'::jsonb, '["NPCs find you unsettling"]'::jsonb, 60) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_necrotic_hand', 'Necrotic Hand', 'One hand has darkened and hardened. Melee attacks cause bleeding. You can''t wear gloves.', 'mixed', 1, '{}'::jsonb, '{"chance":0.3,"status_on_hit":"bleeding"}'::jsonb, '["Cannot equip gloves"]'::jsonb, 50) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_static_mind', 'Static Mind', 'Your thoughts are a white noise channel. Partial immunity to sanity loss. Architect signals are louder.', 'positive', 0, '{"stat_wil":2}'::jsonb, '{"sanity_drain_reduction":0.5}'::jsonb, '["Occasional intrusive Architect messages"]'::jsonb, 70) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_iron_stomach', 'Iron Stomach', 'You can eat almost anything. Food poisoning is no longer a concern. What is a concern is what you now find appetizing.', 'positive', 0, '{"stat_end":1}'::jsonb, '{"food_poison_immunity":true}'::jsonb, '[]'::jsonb, 40) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_rad_absorption', 'Rad Absorption', 'Your body has learned to metabolize radiation instead of being destroyed by it. Slowly.', 'positive', 1, '{"stat_end":2}'::jsonb, '{"rad_resistance":0.3}'::jsonb, '["You glow faintly in the dark — stealth is harder"]'::jsonb, 80) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_bone_spurs', 'Bone Spurs', 'Calcified projections have erupted through your knuckles. Unarmed attacks deal more damage and cause bleeding.', 'mixed', 1, '{"stat_str":1}'::jsonb, '{"unarmed_bleed_chance":0.25,"unarmed_damage_bonus":3}'::jsonb, '["Gloves don''t fit"]'::jsonb, 55) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_weeping_sores', 'Weeping Sores', 'Open lesions that never quite heal. Purely cosmetic. Purely awful.', 'negative', 1, '{"stat_cha":-2}'::jsonb, '{}'::jsonb, '["Visibly diseased — NPCs react poorly"]'::jsonb, 45) ON CONFLICT DO NOTHING;
INSERT INTO mutations ("id", "name", "description", "polarity", "visible", "stat_modifiers", "effects", "drawbacks", "radiation_threshold") VALUES ('mut_tremor_hands', 'Tremor Hands', 'Your hands shake constantly now. Fine motor tasks are a struggle.', 'negative', 0, '{"stat_agi":-1}'::jsonb, '{}'::jsonb, '["Crafting and lockpicking rolls take a penalty"]'::jsonb, 40) ON CONFLICT DO NOTHING;
