INSERT INTO scripts ("id", "name", "description", "graph", "updated_at") VALUES ('script_test_p4', 'P4 Test Diagnostic', 'Phase 4 smoke-test script.', '{"nodes":{"flag":{"flag":"ran_test_script","type":"setflag","scope":"player","value":"true"},"check":{"type":"condition","ifTrue":"known","ifFalse":"stranger","condition":{"op":"set","flag":"met_architect"}},"known":{"next":"flag","text":"The script confirms: the Architect already knows you.","type":"say"},"stranger":{"text":"The script reports: you are a stranger here.","type":"say"}},"start":"check"}'::jsonb, '1782470932') ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_0', NULL, '["\"You feel that? Pressure''s dropping. Gonna rain acid again.\"","\"It always rains acid. That''s just weather now.\"","\"Used to mean something, a storm. Now it''s Tuesday.\"","shrugs and pulls their collar up."]'::jsonb, TRUE, 0) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_1', NULL, '["\"Heard they found another body down by the transit line.\"","\"Ours or theirs?\"","\"Does it matter anymore?\"","\"...No. Suppose it doesn''t.\""]'::jsonb, TRUE, 1) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_2', NULL, '["\"Rent went up again. Same box, more credits.\"","\"Complain to who? The landlord''s an algorithm.\"","\"Can''t even argue with it. It just deducts.\"","laughs, but there''s nothing behind it."]'::jsonb, TRUE, 2) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_3', NULL, '["\"You remember real coffee? Before the substitute?\"","\"I remember the smell. Can''t remember the taste.\"","\"That''s the worst part. The forgetting.\"","stares into the middle distance."]'::jsonb, TRUE, 3) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_4', NULL, '["\"The machines were quiet last night. Too quiet.\"","\"Maybe they''re done with us.\"","\"They''re never done. They''re just patient.\"","\"...Yeah. That''s worse, isn''t it.\""]'::jsonb, TRUE, 4) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_5', NULL, '["\"Somebody''s been through here. Look at the dust.\"","\"Everybody''s been through here. It''s a corridor.\"","\"No, recent. Boots, not drones.\"","glances toward the exit and lowers their voice."]'::jsonb, TRUE, 5) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_6', NULL, '["\"I''d kill for a working shower. Real water.\"","\"You''d kill for less, these days.\"","\"Fair.\"","cracks a tired grin."]'::jsonb, TRUE, 6) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_7', NULL, '["\"They say the upper levels still have power. Real light.\"","\"They say a lot of things about the upper levels.\"","\"You ever been?\"","\"Nobody comes back to say.\""]'::jsonb, TRUE, 7) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_8', NULL, '["\"Prices at the market are insane. A tin of protein for what?\"","\"Supply and desperation. Classic combination.\"","\"One of these days I''m just gonna stop eating.\"","\"Let me know how that works out.\""]'::jsonb, TRUE, 8) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_9', NULL, '["\"Curfew drone came by twice already. Nervous night.\"","\"Something''s got them spooked.\"","\"Something''s always got them spooked. That''s the job.\"","nods slowly, watching the ceiling."]'::jsonb, TRUE, 9) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_10', 'bartender', '["\"You want the usual, or are we pretending you have options?\"","\"...The usual.\"","\"Thought so. Pay first.\"","wipes down the counter without looking up."]'::jsonb, TRUE, 10) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_11', 'bartender', '["\"Third one tonight crying into their drink. Full moon or something.\"","\"There''s no moon anymore. Just the haze.\"","\"Then it''s just people. Even worse.\""]'::jsonb, TRUE, 11) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_12', 'thug', '["\"This block''s ours. You standing in it means something.\"","\"I''m just passing through.\"","\"Nobody just passes through. Remember the face.\"","cracks their knuckles, slow."]'::jsonb, TRUE, 12) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_13', 'thug', '["\"Nice gear. Real nice. Be a shame.\"","\"...Is that a threat?\"","\"It''s an observation. For now.\""]'::jsonb, TRUE, 13) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_14', 'guard', '["\"Move along. Nothing to see here.\"","\"I live here.\"","\"Then live somewhere I''m not standing. Keep it moving.\""]'::jsonb, TRUE, 14) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_15', 'guard', '["\"Long shift. Two more like it before I sleep.\"","\"They working you to death?\"","\"Death''d be a day off. Eyes forward.\""]'::jsonb, TRUE, 15) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_16', 'preacher', '["\"The end was promised, friend. And the end delivered.\"","\"I''m not interested.\"","\"Nobody is. That never stopped it coming.\"","raises a hand in something between blessing and warning."]'::jsonb, TRUE, 16) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_17', 'preacher', '["\"Repent. It won''t help, but the gesture matters.\"","\"Repent for what?\"","\"You''ll know. You always know.\""]'::jsonb, TRUE, 17) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_18', 'vagrant', '["\"You got a smoke? Just one, I''m good for it.\"","\"You said that yesterday.\"","\"And I was good for it. Wasn''t I still here?\"","holds out a hopeful hand."]'::jsonb, TRUE, 18) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_19', 'vagrant', '["\"Don''t sleep near the east wall. Trust me.\"","\"Why, what''s at the east wall?\"","\"...You don''t wanna know. I know. That''s enough for both of us.\""]'::jsonb, TRUE, 19) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_20', 'dealer', '["\"Pot''s right. Cards are fair. Read your opponent, not your luck.\"","\"Easy for you to say. You deal them.\"","\"That''s exactly why I say it.\"","squares the deck against the felt."]'::jsonb, TRUE, 20) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_21', 'doctor', '["\"You''re favouring that leg. Old wound?\"","\"It''s nothing.\"","\"It''s never nothing. Sign the waiver and I''ll take a look.\""]'::jsonb, TRUE, 21) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_22', 'scientist', '["\"The readings from last night were... statistically unusual.\"","\"Unusual how?\"","\"The kind of unusual I''d rather not write down. Officially.\"","adjusts a cracked instrument and frowns."]'::jsonb, TRUE, 22) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_23', 'mercenary', '["\"You freelance, or you signed with somebody?\"","\"I keep my options open.\"","\"Options close fast out here. Pick a paymaster before one picks you.\""]'::jsonb, TRUE, 23) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_24', 'cult_member', '["\"He is coming. He is always coming. Can you feel it?\"","\"I feel a draft, mostly.\"","\"That is how it begins. The cold. The certainty.\"","smiles with unsettling patience."]'::jsonb, TRUE, 24) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_25', 'politician', '["\"We''re making real progress. The data supports our approach.\"","\"The data says people are starving.\"","\"...We''re exploring all options. Except, apparently, that one.\""]'::jsonb, TRUE, 25) ON CONFLICT DO NOTHING;
INSERT INTO npc_banter_threads ("id", "personality", "lines", "enabled", "sort_order") VALUES ('bt_seed_26', 'unemployed', '["\"You hiring? No? Figured. Nobody is.\"","\"Times are hard for everyone.\"","\"Some of us are just more thorough about it.\"","kicks at a loose bit of rubble."]'::jsonb, TRUE, 26) ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_pest_control', 'Pest Control', 'The Scavengers out past the gate have been picking the facility clean. Thin them out.', '[{"desc":"Cull 2 Desperate Scavengers in the wastes","type":"kill","count":2,"target":"Scavenger"}]'::jsonb, '{"items":[{"item_id":"item_rad_pills","quantity":1}],"credits":50}'::jsonb, 0, '1782472672') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_paper_trail', 'Paper Trail', 'A spool of citizen records has gone missing in the west wastes, and something is denning on it. The Registrar at Ledger Hall wants it cleared.', '[{"id":"o1","desc":"Destroy the slag wight denning on the lost records (deep west wastes)","type":"kill","count":1,"target":"slag wight"}]'::jsonb, '{"flags":[{"flag":"civic_favor","scope":"player","value":"earned"}],"items":[{"item_id":"item_ration","quantity":3}],"credits":120}'::jsonb, 0, '1783101549') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_wet_cargo', 'The Wet Cargo', 'Harbour lurkers have been taking dockhands and gnawing hulls in Coldwater Bay. The Harbourmaster wants them thinned out.', '[{"id":"o1","desc":"Clear 3 harbour lurkers from Coldwater Bay","type":"kill","count":3,"target":"harbour lurker"}]'::jsonb, '{"flags":[{"flag":"harbour_favor","scope":"player","value":"earned"}],"items":[{"item_id":"item_contraband_crate","quantity":1}],"credits":150}'::jsonb, 0, '1783102160') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_bog_standard', 'Bog Standard', 'Tar-pit horrors have been dragging scavengers off the only clean water in the flats. Ma Cinder wants them dealt with.', '[{"id":"o1","desc":"Kill 2 tar-pit horrors in the flats (the seeps: Tar Seep, Rust Marsh, The Runoff)","type":"kill","count":2,"target":"tar-pit horror"}]'::jsonb, '{"flags":[{"flag":"camp_favor","scope":"player","value":"earned"}],"items":[{"item_id":"item_water_bottle","quantity":2},{"item_id":"item_ration","quantity":2}],"credits":130}'::jsonb, 0, '1783104890') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_leviathan_bounty', 'Deep Pockets', 'The shareholders in the Aerie lounge have grown bored, and a bored shareholder is a dangerous thing. Vane the bartender is quietly brokering a bounty on the bay leviathan.', '[{"id":"o1","desc":"Kill the bay leviathan in the deep water (The Deep / The Wreck)","type":"kill","count":1,"target":"bay leviathan"}]'::jsonb, '{"flags":[{"flag":"aerie_favor","scope":"player","value":"earned"}],"items":[{"item_id":"item_contraband_crate","quantity":1}],"credits":250}'::jsonb, 0, '1783107866') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_prefects_problem', 'A Matter of Record', 'Wire-jackal packs have been crossing the buffer wastes and getting into the Registry''s overflow archives at the quarter''s western edge. Assemblyman Croll wants them culled — quietly.', '[{"id":"o1","desc":"Cull 4 wire jackals in the buffer wastes west of the quarter","type":"kill","count":4,"target":"wire jackal"}]'::jsonb, '{"flags":[{"flag":"ministry_favor","scope":"player","value":"earned"}],"items":[{"item_id":"item_travel_permit","quantity":1}],"credits":140}'::jsonb, 0, '1783108275') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_sidings_cleared', 'Dead Freight', 'Scavengers have been stripping cargo off the parked flatcars in the sidings faster than the Yards can move it. Voss the yardmaster wants the sidings cleared and isn''t fussy how.', '[{"id":"o1","desc":"Clear 3 Desperate Scavengers from the Yards (Skid Row, the Bulk Yard, the bonded store)","type":"kill","count":3,"target":"scavenger"}]'::jsonb, '{"flags":[{"flag":"yard_favor","scope":"player","value":"earned"}],"items":[{"item_id":"item_contraband_crate","quantity":1}],"credits":160}'::jsonb, 0, '1783118241') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_downwind', 'Downwind', 'Slag wights have moved into the wasteland the diplomatic quarter dumps downwind of itself, and an accord signing is days away. Consul Reyes needs the problem to not exist, discreetly.', '[{"id":"o1","desc":"Clear 2 slag wights from Oxide Flats and the Downwind","type":"kill","count":2,"target":"slag wight"}]'::jsonb, '{"flags":[{"flag":"concordat_favor","scope":"player","value":"earned"}],"items":[{"item_id":"item_bearer_bond","quantity":1}],"credits":200}'::jsonb, 0, '1783120109') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_meltline', 'Over the Meltline', 'The rad mutants denning past the Meltline have started pushing east into Slake''s patch, and a fringe outfitter with a shop full of people to protect can''t have that. Two of them, dropped, buys her breathing room and buys you a fistful of RadAway.', '[{"id":"o1","desc":"Kill 2 rad mutants at the Meltline or Vex Hollow","type":"kill","count":2,"target":"rad mutant"}]'::jsonb, '{"flags":[{"flag":"meltline_cleared","scope":"player","value":"earned"}],"items":[{"item_id":"item_rad_pills","quantity":2}],"credits":180}'::jsonb, 1, '1783120813') ON CONFLICT DO NOTHING;
INSERT INTO quests ("id", "name", "description", "objectives", "rewards", "repeatable", "updated_at") VALUES ('quest_redline_core', 'The Killing Floor', 'Slake has watched people walk west into the Redline for years and watched none of them walk back. She doesn''t want the core cleared — it can''t be — she wants proof it can be touched: the ticking heart of the thing that rules the killing floor, cut out and carried home.', '[{"id":"o1","desc":"Kill the Redline horror on the Killing Floor","type":"kill","count":1,"target":"Redline horror"}]'::jsonb, '{"flags":[{"flag":"redline_conqueror","scope":"player","value":"earned"}],"items":[{"item_id":"item_rad_band","quantity":1},{"item_id":"item_rad_pills","quantity":3}],"credits":400}'::jsonb, 0, '1783121478') ON CONFLICT DO NOTHING;
INSERT INTO orgs ("id", "name", "description", "color", "is_npc", "owner_id", "treasury", "founded_at", "flags") VALUES ('faction_custodians', 'The Custodians', 'Former corporate employees who serve the Architect as a divine entity.', '#4A90D9', 1, NULL, 0, '1783000349', '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO orgs ("id", "name", "description", "color", "is_npc", "owner_id", "treasury", "founded_at", "flags") VALUES ('faction_breakers', 'The Breakers', 'Technology abolitionists. Believe destroying all remaining tech will free humanity.', '#D94A4A', 1, NULL, 0, '1783000349', '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO orgs ("id", "name", "description", "color", "is_npc", "owner_id", "treasury", "founded_at", "flags") VALUES ('faction_archivists', 'The Archivists', 'Knowledge hoarders operating from the tunnels. Politically neutral. Deeply weird.', '#F5A623', 1, NULL, 0, '1783000349', '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO orgs ("id", "name", "description", "color", "is_npc", "owner_id", "treasury", "founded_at", "flags") VALUES ('faction_franchise', 'The Franchise', 'A commerce empire built on pre-Handoff retail bones. If it can be sold, they sell it.', '#7ED321', 1, NULL, 0, '1783000349', '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO orgs ("id", "name", "description", "color", "is_npc", "owner_id", "treasury", "founded_at", "flags") VALUES ('faction_glitch', 'The Glitch', 'Hackers and post-Handoff mystics who believe the Architect can be communicated with.', '#9B59B6', 1, NULL, 0, '1783000349', '{}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO org_relations ("org_id", "other_org_id", "stance") VALUES ('faction_custodians', 'faction_breakers', 'hostile') ON CONFLICT DO NOTHING;
INSERT INTO org_relations ("org_id", "other_org_id", "stance") VALUES ('faction_breakers', 'faction_custodians', 'hostile') ON CONFLICT DO NOTHING;
INSERT INTO org_relations ("org_id", "other_org_id", "stance") VALUES ('faction_breakers', 'faction_glitch', 'hostile') ON CONFLICT DO NOTHING;
