INSERT INTO scavenging_tables ("id", "name", "replenish_interval_seconds", "messages", "flags", "fishing_monsters", "fishing_bait_catches") VALUES ('fish_coldwater_bay', 'Coldwater Bay Fishing', 90, '{"quiet":["Nothing''s biting.","The line stays slack. Whatever''s down there isn''t interested.","You feel a nibble — then slack again. Missed it.","A bubble breaks the surface, and that''s all."],"player":["You flick the line out over the black water and settle in to wait.","The float bobs on an oily swell. You watch it, and wait.","You reel in a little slack and cast again, further out past the pilings.","A slick of rainbow scum drifts past your line. Something moves under it.","The bay heaves slow and greasy against the dock. Your line hangs slack."],"broadcast":["casts a line out over the bay and settles in to fish."]}'::jsonb, '{}'::jsonb, '[{"name":"a cable eel","weight":2,"difficulty":9,"enemyTemplateId":"enemy_cable_eel"}]'::jsonb, '[{"name":"glass eel","itemId":"item_glass_eel","weight":3,"difficulty":7,"requiresBaitTag":"bait_bloodworm"}]'::jsonb) ON CONFLICT DO NOTHING;
