INSERT INTO media_broadcasts ("id", "name", "description", "category", "tags", "playback_mode", "messages", "message_interval", "override_duration", "loop", "enabled", "created_by", "updated_at", "broadcast_graph", "channel_id", "fallback_messages", "weather_pools", "sports_pools") VALUES ('bc_1782963155450', 'The Tonight Show with John Akerson', '', 'late_night', '[]'::jsonb, 'scripted', '[{"text":"ACID COLA REPORTS RECORD PROFITS • POLICE ADVISE CITIZENS TO AVOID DISTRICT 12 • CITY TRANSIT EXPECTS ONLY MODERATE EXPLOSIONS TODAY • BUY NEO-NOODLES: NOW 12% LESS SYNTHETIC •"},{"text":"The broadcast opens on a brightly lit studio bathed in neon blues and warm amber lights. A packed audience applauds enthusiastically while the Tonight Show band finishes the opening bars of the theme."},{"text":"From somewhere above the smog and only slightly outside the blast radius..."},{"text":"It''s..."},{"text":"The Tonight Show!"},{"text":"Tonight..."},{"text":"Corporate executives explain why exploding vending machines are actually a premium feature."},{"text":"A local street chef prepares authentic mutant squid tacos."},{"text":"And we''ll meet a man who''s legally declared his apartment to be an independent nation."},{"text":"Ladies and gentlemen..."},{"text":"JOOOOOHN AKERSON!"},{"text":"The camera follows John Akerson as he jogs onto the stage, shaking hands with audience members before stopping behind his desk with a broad smile."},{"text":"Thank you!"},{"text":"Thank you!"},{"text":"Sit down! We''ve got a fantastic show tonight!"},{"text":"Did everyone survive the commute?"},{"text":"Traffic was backed up six blocks after somebody hacked the crossing lights to advertise noodles."},{"text":"Corporate Security says crime is down."},{"text":"Apparently they stopped counting anything outside corporate property."},{"text":"I stopped by a pharmacy today."},{"text":"They''ve started locking up bottled water."},{"text":"The cybernetic organs are still self-service though."},{"text":"You know times are tough when the mugger accepts store credit."},{"text":"Good news though..."},{"text":"My landlord says the building is structurally sound."},{"text":"Apparently that''s a completely different thing than \"safe.\""},{"text":"The camera settles into a comfortable two-shot as John and tonight''s guest sit beneath the warm studio lights."},{"text":"Lenny, welcome to the show."},{"text":"Happy to be here."},{"text":"You won the city lottery seven times."},{"text":"Eight."},{"text":"Eight?"},{"text":"The eighth time they stopped congratulating me and started interviewing me."},{"text":"What''s your secret?"},{"text":"Always buy your ticket after surviving something that should''ve killed you."},{"text":"That''s oddly specific."},{"text":"I''m from Eastside."},{"text":"What''s the first thing you bought?"},{"text":"A deluxe apartment."},{"text":"Nice!"},{"text":"The deluxe part is that only one wall leaks."},{"text":"The broadcast abruptly transitions to an aggressively colorful commercial surrounded by flashing corporate branding."},{"text":"Feeling tired?"},{"text":"Feeling hopeless?"},{"text":"Drink Acid Cola™."},{"text":"Because reality is easier to tolerate when it''s carbonated."},{"text":"That''s all the time we''ve got tonight."},{"text":"Thanks to Lenny for joining us."},{"text":"Remember..."},{"text":"If somebody offers you free cyberware in an alley.."},{"text":"...at least ask if it comes with a warranty."},{"text":"Good night, everybody!"},{"text":"The camera slowly pulls back as John waves to the audience. The Tonight Show band reprises the theme while the audience rises for a standing ovation beneath glowing neon studio lights."}]'::jsonb, 5, NULL, 0, 1, 'ab2d38d0-4f10-4187-8f53-298d61b525c3', '1782963155', '{"nodes":{"bsm_0":{"next":"bsm_1","type":"start","_vine":{"x":80,"y":80}},"bsm_1":{"next":"bsm_2","type":"event","_vine":{"x":300,"y":80},"event_type":"FADE_IN"},"bsm_2":{"next":"bsm_3","type":"title_card","_vine":{"x":520,"y":80},"g